(2, 'review.published', 'Review published', 'Відгук опубліковано — {{profile_name}}', '<p>Вітаємо, {{author_name}}.</p><p>Ваш відгук для профілю <b>{{profile_name}}</b> успішно опубліковано.</p>', NULL, 1, '2026-05-02 12:16:56', '2026-05-02 12:16:56'),
(3, 'review.rejected', 'Review rejected', 'Відгук відхилено — {{profile_name}}', '<p>Вітаємо, {{author_name}}.</p><p>Ваш відгук для профілю <b>{{profile_name}}</b> було відхилено модератором.</p>', NULL, 1, '2026-05-02 12:16:56', '2026-05-02 12:16:56'),
(4, 'review.under_review', 'Review under review', 'Відгук потребує уточнення — {{profile_name}}', '<p>Вітаємо, {{author_name}}.</p><p>Ваш відгук для профілю <b>{{profile_name}}</b> потребує додаткової перевірки.</p>', NULL, 1, '2026-05-02 12:16:56', '2026-05-02 12:16:56'),
(5, 'review.hidden', 'Review hidden', 'Відгук приховано — {{profile_name}}', '<p>Вітаємо, {{author_name}}.</p><p>Ваш відгук для профілю <b>{{profile_name}}</b> тимчасово приховано.</p>', NULL, 1, '2026-05-02 12:16:56', '2026-05-02 12:16:56'),
(6, 'review.reply', 'Official reply', 'Вам відповіли на відгук — {{profile_name}}', '<p>Вітаємо, {{author_name}}.</p><p>Профіль <b>{{profile_name}}</b> залишив офіційну відповідь:</p><blockquote>{{reply_body}}</blockquote>', NULL, 1, '2026-05-02 12:16:56', '2026-05-02 12:16:56');
