INSERT INTO `profiles` (`id`, `owner_user_id`, `created_by_user_id`, `updated_by_user_id`, `region_id`, `type`, `name`, `short_description`, `slug`, `description`, `website`, `contact_cta_url`, `email`, `phone`, `address`, `city`, `district`, `logo_url`, `banner_url`, `gallery`, `social_links`, `is_verified`, `dovira_recommends`, `dovira_recommendation_status`, `is_owner_verified`, `is_pro`, `is_featured`, `status`, `is_published`, `show_in_catalog`, `sort_priority`, `rating_avg`, `reviews_count`, `views_count`, `unique_views_count`, `website_clicks_count`, `contact_clicks_count`, `popularity_score`, `ai_confidence_score`, `ai_enrichment_status`, `ai_enriched_at`, `ai_suggested_data`, `recommend_percent`, `seo_title`, `seo_description`, `og_image_url`, `internal_note`, `created_at`, `updated_at`) VALUES
(502, NULL, 3, 3, NULL, 'company', 'Адвокат Малик Олександр Володимирович', 'Адвокат Малик Олександр Володимирович надає правову допомогу у сфері цивільного, адміністративного, господарського та кримінального права. Практика охоплює представництво в судах різних інстанцій, захист у справах про адміністративні правопорушення та комплексний юридичний супров...', 'advokat-malyk-aleksandr-vladimirovic', '<p>Адвокат Малик Олександр Володимирович надає правову допомогу у сфері цивільного, адміністративного, господарського та кримінального права. Практика охоплює представництво в судах різних інстанцій, захист у справах про адміністративні правопорушення та комплексний юридичний супровід фізичних і юридичних осіб.</p>\n<h3><strong>Основні напрями діяльності</strong></h3>\n<ul> <li>сімейний адвокат: розірвання шлюбу, поділ майна, аліменти, визначення місця проживання дитини;</li> <li>адвокат по спадщині: оформлення спадкових прав, оскарження заповіту, спори між спадкоємцями;</li> <li>цивільні спори та цивільні справи щодо майна, боргових зобов’язань, відшкодування шкоди;</li> <li>автоадвокат у справах після ДТП, спори зі страховими компаніями;</li> <li>пенсійний адвокат у питаннях перерахунку та призначення пенсії;</li> <li>військовий юрист у справах щодо мобілізації та соціальних гарантій;</li> <li>адвокат з нерухомості: перевірка об’єктів, супровід угод, спори щодо права власності;</li> <li>митний адвокат у спорах з митними органами;</li> <li>адміністративні спори та адміністративні правопорушення;</li> <li>господарські спори та податковий адвокат для бізнесу;</li> <li>трудові спори між працівником і роботодавцем;</li> <li>кримінальні справи на стадії досудового розслідування та судового розгляду;</li> <li>адвокат онлайн — дистанційні консультації та аналіз документів.</li> </ul>\n<h3><strong>Професійна практика</strong></h3>\n<p>Адвокат Малик Олександр Володимирович здійснює адвокатську діяльність відповідно до Закону України «Про адвокатуру та адвокатську діяльність». Представництво в суді здійснюється з урахуванням процесуальних кодексів України та актуальної практики Верховного Суду.</p>\n<p>У роботі застосовується поетапна модель: первинна юридична консультація, аналіз доказової бази, формування правової позиції, підготовка процесуальних документів, супровід у суді. Для ведення справ використовуються державні реєстри, система «Електронний суд», аналітика судових рішень.</p>\n<h3><strong>Спеціалізація та особливості</strong></h3>\n<p>Сімейний адвокат та адвокат по спадщині формують окремий напрям практики, який охоплює складні майнові конфлікти. Господарські спори та податковий адвокат забезпечують правовий захист підприємницької діяльності. Військовий юрист і пенсійний адвокат працюють у межах соціального та адміністративного законодавства.</p>\n<p>Цивільні спори, адміністративні спори та кримінальні справи супроводжуються з урахуванням процесуальних строків, доказових стандартів та судової практики. Представництво в суді здійснюється на всіх стадіях процесу.</p>\n<p><strong>У яких судах здійснюється представництво?</strong> Місцеві суди, апеляційні інстанції, участь у касаційних провадженнях відповідно до процесуального законодавства.</p>\n<p><strong>Чи можливий дистанційний формат співпраці?</strong> Формат «адвокат онлайн» передбачає консультації, аналіз документів та підготовку процесуальних матеріалів без особистої присутності.</p>\n<p><strong>Які категорії справ мають найбільшу практику?</strong> Сімейний адвокат, цивільні спори, господарські спори, адміністративні спори та кримінальні справи.</p>\n<p>Адвокат Малик Олександр Володимирович здійснює правову діяльність у межах чинного законодавства України з фокусом на структурований захист прав та інтересів.</p>', 'https://www.malyk.com.ua', 'https://www.malyk.com.ua', NULL, '(050) 105 33 11, (096) 109 76 08', 'вул. Миколи Оводова, 29а', 'Вінниця', 'Центр', 'catalog-media/profiles/8e/advokat-malik-oleksandr-volodimirovic-8e71ed1a541eb595c57b.png', 'catalog-media/profiles/b0/advokat-malik-oleksandr-volodimirovic-b0f1f32ed95ed3ac838c.png', '[\"catalog-media\\/gallery\\/b0\\/advokat-malik-oleksandr-volodimirovic-b0f1f32ed95ed3ac838c.png\",\"catalog-media\\/gallery\\/6f\\/advokat-malik-oleksandr-volodimirovic-6fe789a6512d96b37585.png\",\"catalog-media\\/gallery\\/94\\/advokat-malik-oleksandr-volodimirovic-947dad721dc523c350d2.png\",\"catalog-media\\/gallery\\/60\\/advokat-malik-oleksandr-volodimirovic-60893d02d6198f869ee5.png\",\"catalog-media\\/gallery\\/c4\\/advokat-malik-oleksandr-volodimirovic-c40de1ea1f78aabf460c.png\",\"catalog-media\\/gallery\\/0f\\/advokat-malik-oleksandr-volodimirovic-0f120897bd0c10289b8d.png\",\"catalog-media\\/gallery\\/fe\\/advokat-malik-oleksandr-volodimirovic-fef551eb4c3847f96ee9.png\",\"catalog-media\\/gallery\\/30\\/advokat-malik-oleksandr-volodimirovic-3061b5b4ee4eecbab3ad.png\",\"catalog-media\\/gallery\\/d2\\/advokat-malik-oleksandr-volodimirovic-d2dc575714d060ce3e40.png\",\"catalog-media\\/gallery\\/2a\\/advokat-malik-oleksandr-volodimirovic-2afcd985a69997002b54.png\",\"catalog-media\\/gallery\\/ee\\/advokat-malik-oleksandr-volodimirovic-ee2d06e498e6abf2cfcf.png\",\"catalog-media\\/gallery\\/f7\\/advokat-malik-oleksandr-volodimirovic-f79af3b28ee98d83d4b9.png\",\"catalog-media\\/gallery\\/31\\/advokat-malik-oleksandr-volodimirovic-31d15b074f8263392e6f.png\",\"catalog-media\\/gallery\\/43\\/advokat-malik-oleksandr-volodimirovic-437939e68f2996439a5a.png\",\"catalog-media\\/gallery\\/f2\\/advokat-malik-oleksandr-volodimirovic-f29fa607213af5f38482.png\",\"catalog-media\\/gallery\\/c0\\/advokat-malik-oleksandr-volodimirovic-c0f3654370a4ae641a80.jpg\",\"catalog-media\\/gallery\\/e1\\/advokat-malik-oleksandr-volodimirovic-e191d1e24bc543d7257a.jpg\",\"catalog-media\\/gallery\\/6d\\/advokat-malik-oleksandr-volodimirovic-6d780a0c9cb591107343.jpg\",\"catalog-media\\/gallery\\/b3\\/advokat-malik-oleksandr-volodimirovic-b315489a58cca12b99c7.jpg\"]', '{\"facebook\":\"https:\\/\\/www.facebook.com\\/lawyer.malyk\\/\",\"instagram\":\"https:\\/\\/www.instagram.com\\/lawyer.malyk\\/\",\"telegram\":\"https:\\/\\/t.me\\/lawyermalyk\"}', 0, 0, NULL, 1, 1, 0, 'active', 1, 1, 0, 4.93, 367, 40, 2, 0, 1, 1562.30, 0, NULL, NULL, '{\"profile_services\":[{\"name\":\"\\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043d\\u0438\\u0446\\u0442\\u0432\\u043e \\u0432 \\u0441\\u0443\\u0434\\u0456\",\"description\":\"\",\"category\":\"\\u041f\\u043e\\u0441\\u043b\\u0443\\u0433\\u0438 \\u044e\\u0440\\u0438\\u0441\\u0442\\u0456\\u0432:\",\"price_from\":\"\",\"duration\":\"\",\"cta\":\"\\u0417\\u0430\\u043b\\u0438\\u0448\\u0438\\u0442\\u0438 \\u0437\\u0430\\u044f\\u0432\\u043a\\u0443\"},{\"name\":\"\\u0441\\u043a\\u043b\\u0430\\u0434\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"description\":\"\",\"category\":\"\\u041f\\u043e\\u0441\\u043b\\u0443\\u0433\\u0438 \\u044e\\u0440\\u0438\\u0441\\u0442\\u0456\\u0432:\",\"price_from\":\"\",\"duration\":\"\",\"cta\":\"\\u0417\\u0430\\u043b\\u0438\\u0448\\u0438\\u0442\\u0438 \\u0437\\u0430\\u044f\\u0432\\u043a\\u0443\"},{\"name\":\"\\u043f\\u043e\\u0434\\u0456\\u043b \\u043c\\u0430\\u0439\\u043d\\u0430\",\"description\":\"\",\"category\":\"\\u041f\\u043e\\u0441\\u043b\\u0443\\u0433\\u0438 \\u044e\\u0440\\u0438\\u0441\\u0442\\u0456\\u0432:\",\"price_from\":\"\",\"duration\":\"\",\"cta\":\"\\u0417\\u0430\\u043b\\u0438\\u0448\\u0438\\u0442\\u0438 \\u0437\\u0430\\u044f\\u0432\\u043a\\u0443\"},{\"name\":\"\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440 \\u044e\\u0440\\u0438\\u0434\\u0438\\u0447\\u043d\\u0438\\u0445 \\u043e\\u0441\\u0456\\u0431\",\"description\":\"\",\"category\":\"\\u041f\\u043e\\u0441\\u043b\\u0443\\u0433\\u0438 \\u044e\\u0440\\u0438\\u0441\\u0442\\u0456\\u0432:\",\"price_from\":\"\",\"duration\":\"\",\"cta\":\"\\u0417\\u0430\\u043b\\u0438\\u0448\\u0438\\u0442\\u0438 \\u0437\\u0430\\u044f\\u0432\\u043a\\