\\u0432\\u0430\\u043d\\u043e\\u0433\\u043e.\\n\\u26a0\\ufe0f \\u041e\\u043a\\u0440\\u0435\\u043c\\u0456 \\u043a\\u043b\\u0456\\u0454\\u043d\\u0442\\u0438 \\u0441\\u043a\\u0430\\u0440\\u0436\\u0430\\u0442\\u044c\\u0441\\u044f \\u043d\\u0430 \\u0432\\u0456\\u0434\\u043c\\u043e\\u0432\\u0443 \\u0443 \\u0441\\u043f\\u0456\\u0432\\u043f\\u0440\\u0430\\u0446\\u0456 \\u0442\\u0430 \\u0441\\u043f\\u0456\\u043b\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u043b\\u0438\\u0448\\u0435 \\u043f\\u0456\\u0441\\u043b\\u044f \\u043e\\u043f\\u043b\\u0430\\u0442\\u0438 \\u043a\\u043e\\u043d\\u0441\\u0443\\u043b\\u044c\\u0442\\u0430\\u0446\\u0456\\u0457, \\u043d\\u0430\\u0432\\u0456\\u0442\\u044c \\u044f\\u043a\\u0449\\u043e \\u043f\\u0438\\u0442\\u0430\\u043d\\u043d\\u044f \\u043c\\u043e\\u0436\\u043d\\u0430 \\u043f\\u0440\\u043e\\u044f\\u0441\\u043d\\u0438\\u0442\\u0438 \\u043e\\u0434\\u0440\\u0430\\u0437\\u0443.\\n\\ud83d\\udca1 \\u041f\\u0456\\u0434\\u0456\\u0439\\u0434\\u0435 \\u0442\\u0438\\u043c, \\u0445\\u0442\\u043e \\u0446\\u0456\\u043d\\u0443\\u0454 \\u044f\\u0441\\u043d\\u0456 \\u043f\\u043e\\u044f\\u0441\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0440\\u043e\\u0433\\u043d\\u043e\\u0437\\u0438 \\u0442\\u0430 \\u043f\\u0440\\u0430\\u0433\\u043d\\u0435 \\u0448\\u0432\\u0438\\u0434\\u043a\\u043e\\u0433\\u043e \\u0432\\u0438\\u0440\\u0456\\u0448\\u0435\\u043d\\u043d\\u044f \\u044e\\u0440\\u0438\\u0434\\u0438\\u0447\\u043d\\u0438\\u0445 \\u043f\\u0438\\u0442\\u0430\\u043d\\u044c \\u0431\\u0435\\u0437 \\u0437\\u0430\\u0439\\u0432\\u043e\\u0457 \\u0442\\u044f\\u0433\\u0430\\u043d\\u0438\\u043d\\u0438.\",\"key_factors\":[\"\\u0410\\u0434\\u0432\\u043e\\u043a\\u0430\\u0442 \\u0443\\u0432\\u0430\\u0436\\u043d\\u043e \\u0432\\u0438\\u0432\\u0447\\u0430\\u0454 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438, \\u043f\\u043e\\u044f\\u0441\\u043d\\u044e\\u0454 \\u0441\\u043a\\u043b\\u0430\\u0434\\u043d\\u0456 \\u04