INSERT INTO `profiles` (`id`, `owner_user_id`, `created_by_user_id`, `updated_by_user_id`, `region_id`, `type`, `name`, `short_description`, `slug`, `description`, `website`, `contact_cta_url`, `email`, `phone`, `address`, `city`, `district`, `logo_url`, `banner_url`, `gallery`, `social_links`, `is_verified`, `dovira_recommends`, `dovira_recommendation_status`, `is_owner_verified`, `is_pro`, `is_featured`, `status`, `is_published`, `show_in_catalog`, `sort_priority`, `rating_avg`, `reviews_count`, `views_count`, `unique_views_count`, `website_clicks_count`, `contact_clicks_count`, `popularity_score`, `ai_confidence_score`, `ai_enrichment_status`, `ai_enriched_at`, `ai_suggested_data`, `recommend_percent`, `seo_title`, `seo_description`, `og_image_url`, `internal_note`, `created_at`, `updated_at`) VALUES
(552, NULL, 3, 3, NULL, 'company', 'Центр правової допомоги', 'Юридична компанія «ЦЕНТР ПРАВОВОЇ ДОПОМОГИ» — професійна правова підтримка у Вінниці та по всій Україні «ЦЕНТР ПРАВОВОЇ ДОПОМОГИ» — українська юридична мережа, що з 2019 року надає фахову допомогу фізичним і юридичним особам. Офіс у Вінниці входить до складу всеукраїнської мережі...', 'centr-pravovoyi-dopomogi', '<p><strong>Юридична компанія «ЦЕНТР ПРАВОВОЇ ДОПОМОГИ» — професійна правова підтримка у Вінниці та по всій Україні</strong></p>\n<p>«ЦЕНТР ПРАВОВОЇ ДОПОМОГИ» — українська юридична мережа, що з 2019 року надає фахову допомогу фізичним і юридичним особам. Офіс у Вінниці входить до складу всеукраїнської мережі та надає клієнтам підтримку у ключових галузях права, використовуючи сучасні підходи та європейські стандарти правового супроводу.</p>\n<h4>Основні напрями діяльності</h4>\n<ul> <li> <p><strong>Сімейне право:</strong> розірвання шлюбу, поділ майна, аліменти, визначення місця проживання дитини;</p> </li> <li> <p><strong>Кримінальне право:</strong> захист прав підозрюваних, обвинувачених і потерпілих;</p> </li> <li> <p><strong>Цивільне право:</strong> договори, споживчі спори, нерухомість;</p> </li> <li> <p><strong>Трудове право:</strong> вирішення трудових конфліктів, складання контрактів;</p> </li> <li> <p><strong>Податкове право:</strong> консультації, перевірки, представництво перед податковими органами;</p> </li> <li> <p><strong>Банківське та фінансове право:</strong> кредити, боргові зобов’язання, протидія колекторам;</p> </li> <li> <p><strong>Міжнародне право:</strong> інвестиції, зовнішньоекономічні угоди, міжнародні арбітражі;</p> </li> <li> <p><strong>Адміністративне право:</strong> спори з державними структурами, оскарження рішень.</p> </li> </ul>\n<p><strong>Сімейне право:</strong> розірвання шлюбу, поділ майна, аліменти, визначення місця проживання дитини;</p>\n<p><strong>Кримінальне право:</strong> захист прав підозрюваних, обвинувачених і потерпілих;</p>\n<p><strong>Цивільне право:</strong> договори, споживчі спори, нерухомість;</p>\n<p><strong>Трудове право:</strong> вирішення трудових конфліктів, складання контрактів;</p>\n<p><strong>Податкове право:</strong> консультації, перевірки, представництво перед податковими органами;</p>\n<p><strong>Банківське та фінансове право:</strong> кредити, боргові зобов’язання, протидія колекторам;</p>\n<p><strong>Міжнародне право:</strong> інвестиції, зовнішньоекономічні угоди, міжнародні арбітражі;</p>\n<p><strong>Адміністративне право:</strong> спори з державними структурами, оскарження рішень.</p>\n<h4>Географія та структура</h4>\n<p>Мережа об’єднує 14 офісів по Україні, серед яких і <strong>представництво у Вінниці</strong>, що надає повний спектр юридичних послуг для мешканців області. Команда юристів і адвокатів має понад 10 років досвіду, а щомісяця фахівці опрацьовують понад 5000 звернень.</p>\n<h4>Підхід та особливості</h4>\n<p>У роботі використовуються європейські стандарти юридичної практики, хмарні сервіси для зберігання документів і сучасні системи моніторингу справ. Первинна консультація — безкоштовна, що дозволяє клієнтам отримати оцінку ситуації без ризиків.</p>\n<h4>Як отримати консультацію?</h4>\n<p>Запис здійснюється онлайн або телефоном. Після звернення спеціаліст проводить безкоштовну первинну оцінку справи.</p>\n<h4>Чи можна отримати допомогу дистанційно?</h4>\n<p>Так, більшість послуг доступні онлайн — консультації, підготовка документів, супровід справ незалежно від місця проживання.</p>\n<p>«ЦЕНТР ПРАВОВОЇ ДОПОМОГИ» у Вінниці поєднує досвід, технології та прозорість, формуючи сучасну культуру юридичного сервісу в Україні.</p>', 'https://urist24.com.ua', 'https://urist24.com.ua', NULL, '(050) 330 36 29', 'Миколи Оводова, 51', 'Вінниця', 'Центр', 'catalog-media/profiles/b8/centr-pravovoyi-dopomogi-b8a60d14ac581a63c583.jpg', 'catalog-media/profiles/e7/centr-pravovoyi-dopomogi-e780fca2cf4a7ff1b582.jpg', '[\"catalog-media\\/gallery\\/e7\\/centr-pravovoyi-dopomogi-e780fca2cf4a7ff1b582.