3c\\u0456\\u043b\\u043e, \\u043d\\u0435 \\u0432\\u0438\\u0442\\u0440\\u0430\\u0447\\u0430\\u044e\\u0447\\u0438 \\u0437\\u0430\\u0439\\u0432\\u0438\\u0439 \\u0447\\u0430\\u0441.\\n\\u2705 \\u041a\\u043b\\u0456\\u0454\\u043d\\u0442\\u0438 \\u0446\\u0456\\u043d\\u0443\\u044e\\u0442\\u044c, \\u043a\\u043e\\u043b\\u0438 \\u043e\\u0442\\u0440\\u0438\\u043c\\u0443\\u044e\\u0442\\u044c \\u0447\\u0456\\u0442\\u043a\\u0438\\u0439, \\u043f\\u043e\\u043a\\u0440\\u043e\\u043a\\u043e\\u0432\\u0438\\u0439 \\u043f\\u043b\\u0430\\u043d \\u0434\\u0456\\u0439 \\u0456 \\u0432\\u0456\\u0434\\u0447\\u0443\\u0432\\u0430\\u044e\\u0442\\u044c \\u043f\\u0456\\u0434\\u0442\\u0440\\u0438\\u043c\\u043a\\u0443 \\u0442\\u0430 \\u043b\\u044e\\u0434\\u044f\\u043d\\u0435 \\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f \\u043d\\u0430\\u0432\\u0456\\u0442\\u044c \\u0443 \\u0441\\u0442\\u0440\\u0435\\u0441\\u043e\\u0432\\u0438\\u0445 \\u0441\\u0438\\u0442\\u0443\\u0430\\u0446\\u0456\\u044f\\u0445.\\n\\u26a0\\ufe0f \\u0427\\u0430\\u0441\\u0442\\u043e \\u0441\\u043a\\u0430\\u0440\\u0436\\u0430\\u0442\\u044c\\u0441\\u044f \\u043d\\u0430 \\u043f\\u0441\\u0438\\u0445\\u043e\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u0438\\u0439 \\u0442\\u0438\\u0441\\u043a \\u0456 \\u043f\\u043e\\u0441\\u043f\\u0456\\u0445 \\u043f\\u0440\\u0438 \\u0443\\u043a\\u043b\\u0430\\u0434\\u0430\\u043d\\u043d\\u0456 \\u0434\\u043e\\u0433\\u043e\\u0432\\u043e\\u0440\\u0443, \\u043e\\u0431\\u0456\\u0446\\u044f\\u043d\\u043a\\u0438 \\u0448\\u0432\\u0438\\u0434\\u043a\\u043e\\u0433\\u043e \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u0443 \\u0431\\u0435\\u0437 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0441\\u0443\\u043f\\u0440\\u043e\\u0432\\u043e\\u0434\\u0443, \\u0432\\u0438\\u043c\\u0430\\u0433\\u0430\\u043d\\u043d\\u044f \\u043e\\u043f\\u043b\\u0430\\u0442\\u0438 \\u043d\\u0430 \\u043e\\u0441\\u043e\\u0431\\u0438\\u0441\\u0442\\u0456 \\u043a\\u0430\\u0440\\u0442\\u043a\\u