u0438\\u043f\\u0430\\u0434\\u043e\\u043a \\u0456 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u0443\\u0454 \\u043d\\u0435 \\u0442\\u0456\\u043b\\u044c\\u043a\\u0438 \\u044e\\u0440\\u0438\\u0434\\u0438\\u0447\\u043d\\u043e\\u0457 \\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0438, \\u0430\\u043b\\u0435 \\u0439 \\u043b\\u044e\\u0434\\u044f\\u043d\\u043e\\u0433\\u043e \\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f.\"],\"strengths\":[\"\\u041b\\u044e\\u0434\\u0438 \\u043e\\u0441\\u043e\\u0431\\u043b\\u0438\\u0432\\u043e \\u0446\\u0456\\u043d\\u0443\\u044e\\u0442\\u044c \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u043f\\u0456\\u0434\\u0445\\u0456\\u0434, \\u0443\\u0432\\u0430\\u0436\\u043d\\u0456\\u0441\\u0442\\u044c \\u0434\\u043e \\u0434\\u0435\\u0442\\u0430\\u043b\\u0435\\u0439 \\u0456 \\u0437\\u0434\\u0430\\u0442\\u043d\\u0456\\u0441\\u0442\\u044c \\u0430\\u0434\\u0432\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432 \\u0432\\u0438\\u0440\\u0456\\u0448\\u0438\\u0442\\u0438 \\u0441\\u043a\\u043b\\u0430\\u0434\\u043d\\u0456 \\u043f\\u0438\\u0442\\u0430\\u043d\\u043d\\u044f, \\u044f\\u043a\\u0456 \\u0456\\u043d\\u0448\\u0456 \\u043d\\u0435 \\u043c\\u043e\\u0433\\u043b\\u0438.\",\"\\u041a\\u043b\\u0456\\u0454\\u043d\\u0442\\u0438 \\u0432\\u0456\\u0434\\u0437\\u043d\\u0430\\u0447\\u0430\\u044e\\u0442\\u044c \\u0432\\u0456\\u0434\\u0447\\u0443\\u0442\\u043d\\u0443 \\u043f\\u0456\\u0434\\u0442\\u0440\\u0438\\u043c\\u043a\\u0443, \\u043f\\u043e\\u044f\\u0441\\u043d\\u0435\\u043d\\u043d\\u044f \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u043e\\u044e \\u043c\\u043e\\u0432\\u043e\\u044e \\u0456 \\u0432\\u0456\\u0434\\u0447\\u0443\\u0442\\u0442\\u044f \\u0432\\u043f\\u0435\\u0432\\u043d\\u0435\\u043d\\u043e\\u0441\\u0442\\u0456 \\u043d\\u0430 \\u0432\\u0441\\u0456\\u0445 \\u0435\\u0442\\u0430\\u043f\\u0430\\u0445 \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438.\"],\"risks\":[],\"people\":[{\"name\":\"\\u04