0430 \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0456\\u043e\\u043d\\u0430\\u043b\\u0456\\u0437\\u043c, \\u0434\\u043e\\u0441\\u0432\\u0456\\u0434\\u0447\\u0435\\u043d\\u0456\\u0441\\u0442\\u044c \\u0456 \\u0437\\u0434\\u0430\\u0442\\u043d\\u0456\\u0441\\u0442\\u044c \\u0437\\u043d\\u0430\\u0439\\u0442\\u0438 \\u0440\\u0456\\u0448\\u0435\\u043d\\u043d\\u044f \\u043d\\u0430\\u0432\\u0456\\u0442\\u044c \\u0443 \\u043d\\u0435\\u043f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0445 \\u0441\\u043f\\u0440\\u0430\\u0432\\u0430\\u0445.\"}],\"sentiment\":\"positive\",\"provider\":\"openai\",\"generated_at\":\"2026-06-28T19:45:07+00:00\"}}', 0, NULL, NULL, 'catalog-media/profiles/23/oleksii-kuxar-ta-partneri-advokatska-kompaniia-23bf41954cd4fad6e2f1.jpg', 'Імпортовано з зовнішнього каталогу. Перевірити профіль і вирішити щодо публікації.', '2026-06-28 19:10:29', '2026-07-02 12:16:24');
INSERT INTO `profiles` (`id`, `owner_user_id`, `created_by_user_id`, `updated_by_user_id`, `region_id`, `type`, `name`, `short_description`, `slug`, `description`, `website`, `contact_cta_url`, `email`, `phone`, `address`, `city`, `district`, `logo_url`, `banner_url`, `gallery`, `social_links`, `is_verified`, `dovira_recommends`, `dovira_recommendation_status`, `is_owner_verified`, `is_pro`, `is_featured`, `status`, `is_published`, `show_in_catalog`, `sort_priority`, `rating_avg`, `reviews_count`, `views_count`, `unique_views_count`, `website_clicks_count`, `contact_clicks_count`, `popularity_score`, `ai_confidence_score`, `ai_enrichment_status`, `ai_enriched_at`, `ai_suggested_data`, `recommend_percent`, `seo_title`, `seo_description`, `og_image_url`, `internal_note`, `created_at`, `updated_at`) VALUES
(557, NULL, 3, 3, NULL, 'company', 'Олега Огородника, юридична компанія', 'Адвокатське бюро Олега Огородника в м. Вінниці надає повний спектр юридичних послуг з високим рівнем якості. Діяльність адвокатського бюро передбачає повну конфіденційність, кваліфіковану допомогу і розумну цінову політику. Головні принципи роботи адвокатського бюро Олега Огородн...', 'olega-ogorodnika', '<p>Адвокатське бюро Олега Огородника в м. Вінниці надає повний спектр юридичних послуг з високим рівнем якості. Діяльність адвокатського бюро передбачає повну конфіденційність, кваліфіковану допомогу і розумну цінову політику. Головні принципи роботи адвокатського бюро Олега Огородника з клієнтами - це індивідуальний підхід, професійне обслуговування, дотримання вимог законодавства, надійність і безпека. Які послуги Ви отримаєте в адвокатському бюро Олега Огородника? Послуги адвоката по господарських справах. Досудове врегулювання спорів, складання позовної заяви, подача до відповідного суду; комплексне ведення справ в суді; оскарження рішень суду; допомога адвоката на стадії виконання рішень суду. Реєстрація суб’єктів підприємницької діяльності. Реєстрація змін прізвища, імені, місця проживання, виду діяльності тощо. Реєстрація юридичних осіб (товариств, приватних підприємств). Переведення підприємства з одного району України в інший; реєстрація філій, відділень, представництв підприємств у відповідних органах, відкриття рахунку в банку, виготовлення печатки. Реєстрація змін в юридичних особах. Зміна директора, зміна складу засновників, зміна юридичної адреси, виду діяльності, найменування, розміру статутного капіталу та інших відомостей. Реєстрація повного товариства. Відкриття ломбарду (внесення до реєстру фінансових установ). Внесення до Державного реєстру видавців, виготівників і розповсюджувачів видавничої продукції. Отримання виписки, довідки з реєстру, щорічне підтвердження відомостей. Ліквідація юридичних осіб та фізичних осіб-підприємців. Банкрутство ТОВ через загальну процедуру; ліквідація ТОВ шляхом зміни засновника, через процедуру банкрутства. За рішенням засновників тощо. Абонентське юридичне обслуговування. Відповідно до потреб клієнта є три пакети обслуговування: «Економ», «Класік», «Бізнес». Юридичні консультації. Усні та письмові консультації; консультації по телефону та по електронній пошті; консультації по реєстрації, перереєстрації юридичної особи. Спадкові справи. Позовна заява про встановлення права власності на спадщину; представництво клієнта в державних органах і нотаріаті; оформлення спадщини. Сімейні суперечки. Розлучення та розподіл спільного майна; стягнення заборгованості по аліментах; розробка шлюбних договорів; комплексне ведення судових процесів тощо. Розробка необхідної документації по кадрам. Посадові інструкції; правила внутрішнього розпорядку; складання та реєстрація колективного договору; положення про комерційну таємницю та інше. Земельні спори, корпоративні спори, супроводження бізнесу та представництво ФОП, юридичних осіб в Господарських судах всіх інстанцій. В основу професійної діяльності Олега Огородника покладені глибокі знання в сфері права, досвід роботи в правоохоронних органах, робота юристом на підприємствах та в абонентському юридичному обслуговуванні фізичних і юридичних осіб, багаторазовому представництві інтересів клієнтів в судах різних інстанцій. На даний час адвокат Олег Огородник є членом Асоціації Юристів України, автором багатьох статей в засобах масової інформації.</p>', NULL, NULL, NULL, '(097) 844 44 51', 'проспект Юності, 18', 'Вінниця', 'Вишенька', 'catalog-media/profiles/9d/olega-ogorodnika-iuridicna-kompaniia-9d0c35e5bf2fd0d6c8db.jpg', 'catalog-media/profiles/d0/olega-ogorodnika-iuridicna-kompaniia-d0eb29d683531943ce91.jpg', '[\"catalog-media\\/gallery\\/d0\\/olega-ogorodnika-iuridicna-kompaniia-d0eb29d683531943ce91.jpg\",\"catalog-media\\/gallery\\/6b\\/olega-ogorodnika-iuridicna-kompaniia-6b1cb459f3a5723f6f75.jpg\",\"catalog-media\\/gallery\\/c9\\/olega-ogorodnika-iuridicna-kompanii