c\\u043d\\u043e \\u043f\\u0456\\u0434\\u0442\\u0440\\u0438\\u043c\\u0443\\u0454 \\u043d\\u0430\\u0432\\u0456\\u0442\\u044c \\u0443 \\u043f\\u043e\\u0437\\u0430\\u0440\\u043e\\u0431\\u043e\\u0447\\u0438\\u0439 \\u0447\\u0430\\u0441, \\u043d\\u0430\\u0434\\u0430\\u044e\\u0447\\u0438 \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u0443 \\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0443 \\u0442\\u0430 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0432\\u0456\\u0434\\u0456 \\u043d\\u0430 \\u0441\\u043a\\u043b\\u0430\\u0434\\u043d\\u0456 \\u043f\\u0438\\u0442\\u0430\\u043d\\u043d\\u044f.\",\"\\u0427\\u0430\\u0441\\u0442\\u043e \\u043f\\u0456\\u0434\\u043a\\u0440\\u0435\\u0441\\u043b\\u044e\\u044e\\u0442\\u044c \\u0443\\u0432\\u0430\\u0436\\u043d\\u0456\\u0441\\u0442\\u044c \\u0434\\u043e \\u0434\\u0435\\u0442\\u0430\\u043b\\u0435\\u0439 \\u0456 \\u0432\\u043c\\u0456\\u043d\\u043d\\u044f \\u0432\\u0440\\u0430\\u0445\\u0443\\u0432\\u0430\\u0442\\u0438 \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u0443 \\u0441\\u0438\\u0442\\u0443\\u0430\\u0446\\u0456\\u044e, \\u0430 \\u0442\\u0430\\u043a\\u043e\\u0436 \\u0433\\u043e\\u0442\\u043e\\u0432\\u043d\\u0456\\u0441\\u0442\\u044c \\u043f\\u043e\\u044f\\u0441\\u043d\\u044e\\u0432\\u0430\\u0442\\u0438 \\u0432\\u0441\\u0456 \\u043c\\u043e\\u0436\\u043b\\u0438\\u0432\\u0456 \\u0432\\u0430\\u0440\\u0456\\u0430\\u043d\\u0442\\u0438 \\u0440\\u043e\\u0437\\u0432\\u0438\\u0442\\u043a\\u0443 \\u043f\\u043e\\u0434\\u0456\\u0439.\"],\"risks\":[],\"people\":[{\"name\":\"\\u0422\\u0435\\u0442\\u044f\\u043d\\u0430 \\u0406\\u0432\\u0430\\u043d\\u0456\\u0432\\u043d\\u0430\",\"role\":\"\\u0430\\u0434\\u0432\\u043e\\u043a\\u0430\\u0442\",\"text\":\"\\u0417\\u0430\\u0432\\u0436\\u0434\\u0438 \\u043d\\u0430 \\u0437\\u0432\\u2019\\u044f\\u0437\\u043a\\u0443, \\u0443\\u0432\\u0430\\u0436\\u043d\\u043e \\u0441\\u0442\\u0430\\u0432\\u0438\\u0442\\u044c\\u0441\\u044f \\u0434\\u043e \\u0434\\u0435\\u0442\\u0430\\u043b\\u0435\\u0439 \\u0456 \\u043f\\u0456\\u0434\\u0442\\u0440\\u0438\\u043c\\u0443\\u0454 \\u0443 \\u0432\\u0430\\u0436\\u043b\\u0438\\u0432\\u0456 \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442\\u0438, \\u0434\\u043e\\u043f\\u043e\\u043c\\u0430\\u0433\\u0430\\u044e\\u0447\\u0438 \\u043d\\u0430\\u0432\\u0456\\u0442\\u044c \\u0442\\u043e\\u0434\\u0456, \\u043a\\u043e\\u043b\\u0438 \\u0456\\u043d\\u0448\\u0456 \\u0432\\u0456\\u0434\\u043c\\u043e\\u0432\\u0438\\u043b\\u0438\\u0441\\u044f.\"}],\"sentiment\":\"positive\",\"provider\":\"openai\",\"generated_at\":\"2026-06-28T19:45:13+00:00\"}}', 0, NULL, NULL, 'catalog-media/profiles/9e/advokatske-biuro-dmitrisinoyi-tetiani-9ee9e84d1a13bc65f601.jpg', 'Імпортовано з зовнішнього каталогу. Перевірити профіль і вирішити щодо публікації.', '2026-06-28 19:10:51', '2026-07-02 12:16:50'),
(559, NULL, 3, 3, NULL, 'company', 'Адвокат з сімейних правовідносин Шевчук Тетяна Володимирівна', 'Адвокат Шевчук Тетяна Володимирівна – досвідчений спеціаліст у сфері сімейних правовідносин, являється діючим членом Національної асоціації адвокатів України, яка працює по всій території України та за кордоном. На її користь каже не лише професіоналізм і високий рівень компетенц...', 'advokat-sevcuk-tetiana-volodimirivna', '<p><strong>Адвокат Шевчук Тетяна Володимирівна</strong> – досвідчений спеціаліст у сфері сімейних правовідносин, являється діючим членом Національної асоціації адвокатів України, яка працює по всій території України та за кордоном. На її користь каже не лише професіоналізм і високий рівень компетенції у різних галузях права, а й 10-річний стаж роботи в суді та адвокатурі та сотні виграних справ.</p>\n<p>Шевчук Тетяна Володимирівна гарантовано надасть фахову юридичну допомогу в сімейних спорах і не тільки:</p>\n<ul> <li>розлучення, в тому числі у випадках, коли одна зі сторін перебуває за кордоном;</li> <li>аліменти: <ul> <li>на неповнолітню дитину або повнолітню дитину, яка продовжує навчання;</li> <li>на дружину (до досягнення дитиною 3-річного віку);</li> <li>на утримання батьків;</li> <li>зміна розміру аліментів або способу їх стягнення (частка від доходу / тверда грошова сума) та припинення їх стягнення.</li> </ul> </li> <li>визначення місця проживання дитини;</li> <li>встановлення графіку побачень з дітьми;</li> <li>встановлення/визнання факту батьківства (в тому числі після смерті батька) або, навпаки, його оспорювання;</li> <li>виключення із актового запису про народження відомостей про батька;</li> <li>позбавлення батьківських прав;</li> <li>поділ подружнього майна;</li> <li>клопотання про видачу обмежувального припису щодо кривдника;</li> <li>адвокатські запити, відзиви, відповіді на відзив / заперечення / пояснення;</li> <li>оформлення паспорта громадянина України зразка 1994-го року (книжечки);</li> <li>допомога в отримання повторної видачі свідоцтва про шлюб, про народження дітей, про смерть тощо;</li> <li>допомога в отриманні інформації з реєстру речових прав на нерухоме майно;</li> <li>спадкові/цивільні справи та ін.</li> </ul>\n<ul style=\"list-style-type:circle\"> <li>на неповнолітню дитину або повнолітню дитину, яка продовжує навчання;</li> <li>на дружину (до досягнення дитиною 3-річного віку);</li> <li>на утримання батьків;</li> <li>зміна розміру аліментів або способу їх стягнення (частка від доходу / тверда грошова сума) та припинення їх стягнення.</li> </ul>\n<p>Ось лише декілька причин звернутися до адвоката Шевчук Тетяни Володимирівни:</p>\n<ul> <li>можливість повного супроводу справи без участі учасників у судових засіданнях;</li> <li>чудова обізнаність в останніх змінах законодавства, прецедентах судової практики та юридичних новинах;</li> <li>постійний професійний ріст і розвиток як фахівчині;</li> <li>розгорнуті консультації з кожного питання, надані доступною і зрозумілою мовою;</li> <li>комплексний підхід до будь-якого випадку клієнта.</li> </ul>\n<p>Адвокат надає послуги в зручному для вас форматі – очно або дистанційно (телефоном, у месенджерах, по відеозв’язку).</p>', NULL, NULL, NULL, '(097) 796 42 89', 'Тімірязєва, 23', 'Вінниця', 'Центр', 'catalog-media/profiles/a6/advokat-z-simeinix-pravovidnosin-sevcuk-tetiana-volodimirivna-a61bdf5818de9938882b.jpg', 'catalog-media/profiles/8b/advokat-z-simeinix-pravovidnosin-sevcuk-tetiana-volodimirivna-8b8e210d45c40edf8a96.jpg', '[\"catalog-media\\/gallery\\/8b\\/advokat-z-simeinix-pravovidnosin-sevcuk-tetiana-volodimirivna-8b8e210d45c40edf8a96.jpg\",\"catalog-media\\/gallery\\/34\\/advokat-z-simeinix-pravovidnosin-sevcuk-tetiana-volodimirivna-342d473e6c2790f92157.jpg\",\"catalog-media\\/gallery\\/e4\\/advokat-z-simeinix-pravovidnosin-sevcuk-tetiana-volodimirivna-e4f49f018ca86b6a34ba.jpg\"]', '[]', 0, 0, NULL, 0, 0, 0, 'active', 1, 1, 0, 5.00, 35, 0, 0, 0, 0, 190.00, 0, NULL, NULL, '{\"profile_services\":[{\"name\":\"\\u043f\\u0440\\u043