(1159, NULL, 3, 3, NULL, 'company', 'Kostenko Legal Company', 'Kostenko Legal Company надає широкий спектр юридичних консультацій та послуг у різних галузях права, включаючи цивільне, сімейне, господарське та кримінальне право. Представництво в судах та інших державних органах, а також складання юридичних документів є ключовими аспектами роб...', 'kostenko-legal-company', '<p>Kostenko Legal Company надає широкий спектр юридичних консультацій та послуг у різних галузях права, включаючи цивільне, сімейне, господарське та кримінальне право. Представництво в судах та інших державних органах, а також складання юридичних документів є ключовими аспектами роботи компанії. Реєстрація юридичних осіб також доступна для клієнтів, які потребують професійної підтримки.</p>', NULL, NULL, NULL, '(096) 157 12 97', 'Грушевсього, 87', 'Хмельницький', 'Центр', 'https://top20.ua/media-resize/company_square/thumbnail%20%288%29-1236136.jpeg?timestamp=1765981286', 'https://top20.ua/media-resize/company_large/thumbnail%20%288%29-1236136.jpeg?timestamp=1765981286', '[\"https:\\/\\/top20.ua\\/media-resize\\/company_large\\/thumbnail%20%288%29-1236136.jpeg?timestamp=1765981286\"]', '[]', 0, 0, NULL, 0, 0, 0, 'draft', 0, 0, 0, 4.43, 7, 0, 0, 0, 0, 72.30, 0, NULL, NULL, '{\"profile_services\":[{\"name\":\"\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440 \\u044e\\u0440\\u0438\\u0434\\u0438\\u0447\\u043d\\u0438\\u0445 \\u043e\\u0441\\u0456\\u0431\",\"description\":\"\",\"category\":\"\\u041f\\u043e\\u0441\\u043b\\u0443\\u0433\\u0438 \\u044e\\u0440\\u0438\\u0441\\u0442\\u0456\\u0432:\",\"price_from\":\"\",\"duration\":\"\",\"cta\":\"\\u0417\\u0430\\u043b\\u0438\\u0448\\u0438\\u0442\\u0438 \\u0437\\u0430\\u044f\\u0432\\u043a\\u0443\"}],\"specializations_title\":\"\\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u044f \\u0430\\u0434\\u0432\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432:\"}', 0, NULL, NULL, 'https://top20.ua/media-resize/company_large/kostenko-legal-company-2