(1270, NULL, 3, 3, NULL, 'company', 'Іваніщев Олег Валерійович', 'юридичні консультації; представництво в судах; захист прав та інтересів клієнтів; складання юридичних документів; правовий супровід бізнесу; інші юридичні послуги.', 'ivanishhev-oleg-valeriiovic', '<p>юридичні консультації; представництво в судах; захист прав та інтересів клієнтів; складання юридичних документів; правовий супровід бізнесу; інші юридичні послуги.</p>', NULL, NULL, NULL, '(096) 073 12 70', 'Шульгиних, 13', 'Кропивницький', 'Центр', 'https://top20.ua/media-resize/company_square/thumbnail%20%281%29-1236316.jpeg?timestamp=1766049039', 'https://top20.ua/media-resize/company_large/thumbnail%20%281%29-1236316.jpeg?timestamp=1766049039', '[\"https:\\/\\/top20.ua\\/media-resize\\/company_large\\/thumbnail%20%281%29-1236316.jpeg?timestamp=1766049039\"]', '[]', 0, 0, NULL, 0, 0, 0, 'draft', 0, 0, 0, 5.00, 4, 0, 0, 0, 0, 66.00, 0, NULL, NULL, '{\"profile_services\":[{\"name\":\"\\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043d\\u0438\\u0446\\u0442\\u0432\\u043e \\u0432 \\u0441\\u0443\\u0434\\u0456\",\"description\":\"\",\"category\":\"\\u041f\\u043e\\u0441\\u043b\\u0443\\u0433\\u0438 \\u044e\\u0440\\u0438\\u0441\\u0442\\u0456\\u0432:\",\"price_from\":\"\",\"duration\":\"\",\"cta\":\"\\u0417\\u0430\\u043b\\u0438\\u0448\\u0438\\u0442\\u0438 \\u0437\\u0430\\u044f\\u0432\\u043a\\u0443\"},{\"name\":\"\\u0441\\u043a\\u043b\\u0430\\u0434\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"description\":\"\",\"category\":\"\\u041f\\u043e\\u0441\\u043b\\u0443\\u0433\\u0438 \\u044e\\u0440\\u0438\\u0441\\u0442\\u0456\\u0432:\",\"price_from\":\"\",\"duration\":\"\",\"cta\":\"\\u0417\\u0430\\u043b\\u0438\\u0448\\u0438\\u0442\\u0438 \\u0437\\u0430\\u044f\\u0432\\u043a\\u0443\"}],\"specializations_title\":\"\\u042e\\u0440\\u0438\\u0434\\u0438\\u0447\\u043d\\u0456 