(1298, NULL, 3, 3, 14, 'company', 'Карпова Ольга Викторовна', 'Карпова Ольга Викторовна, адвокат. Находится в Одесса. помощь адвоката регистрации и ликвидации компаний; сопровождение бизнеса юридических лиц; внесение изменений в уставные документы; смена адреса предприятия; смена директора предприятия; изменение состава учредителей предприят...', 'karpova-olga-viktorovna', '<p>Карпова Ольга Викторовна, адвокат. Находится в Одесса. помощь адвоката регистрации и ликвидации компаний; сопровождение бизнеса юридических лиц; внесение изменений в уставные документы; смена адреса предприятия; смена директора предприятия; изменение состава учредителей предприятия регистрация ФЛП; развод супругов; взыскание алиментов; определение места жительства ребенка; споры со страховой компанией; кредитные споры; выселение из жилья; административные споры; раздел имущества супругов; взыскание долга.</p>', NULL, NULL, NULL, '(063) 568 65 55', 'Малиновського, 44', 'Одеса', NULL, 'https://top20.ua/media-resize/company_square/138eb19b12ddd3ba787a92c1bdd8fe40bff43c98-960041.jpeg?timestamp=1666006028', 'https://top20.ua/media-resize/company_large/138eb19b12ddd3ba787a92c1bdd8fe40bff43c98-960041.jpeg?timestamp=1666006028', '[\"https:\\/\\/top20.ua\\/media-resize\\/company_large\\/138eb19b12ddd3ba787a92c1bdd8fe40bff43c98-960041.jpeg?timestamp=1666006028\",\"https:\\/\\/top20.ua\\/media-resize\\/company_large\\/8EF2FA89-FC71-4619-90FE-0ECE22EF924B-958988.jpeg?timestamp=1665690394\",\"https:\\/\\/top20.ua\\/media-resize\\/company_large\\/C4195FAB-E087-46F1-8E02-39BD8E062121-958989.jpeg?timestamp=1665690394\",\"https:\\/\\/top20.ua\\/media-resize\\/company_large\\/59A366D5-341A-4A10-B17A-6908899C0A3B-958990.jpeg?timestamp=1665690394\",\"https:\\/\\/top20.ua\\/media-resize\\/company_large\\/6F720DF6-35D6-442C-9AF3-20E4FEA53E01-958991.jpeg?timestamp=1665690394\"]', '[]', 0, 0, NULL, 0, 0, 0, 'draft', 0, 0, 0, 5.00, 26, 0, 0, 0, 0, 154.00, 0, NULL, NULL, '{\"profile_services\":[{\"name\":\"\\u043f\\u04