INSERT INTO `profile_reviews` (`id`, `profile_id`, `user_id`, `author_name`, `author_email`, `is_anonymous`, `author_ip`, `author_user_agent`, `risk_score`, `rating`, `title`, `body`, `pros`, `cons`, `interaction_date`, `media`, `status`, `moderation_note`, `moderation_reason`, `admin_note`, `is_verified_purchase`, `verification_type`, `is_suspicious`, `is_featured`, `helpful_count`, `like_count`, `dislike_count`, `published_at`, `external_source_url`, `external_review_hash`, `external_source_type`, `external_review_author`, `external_review_author_avatar_url`, `external_review_date`, `created_at`, `updated_at`) VALUES
(9616, 502, NULL, 'Cyber ZET', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталися до Малика О. В. у межах господарської справи. Вже перша консультація залишила хороше враження. Адвокат детально ознайомився з документами, не обмежуючись поверхневим переглядом. Відчувається професійний досвід і практичні знання.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-14 00:00:00', NULL, '88b609a9117ceff2f7ba86f6479ed9863b17d62b', 'google', 'Cyber ZET', 'img/empty.png?a2499e3b0', '2026-06-14', '2026-06-28 15:16:13', '2026-07-02 12:17:48'),
(9617, 502, NULL, 'Poco F1', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мав складну ситуацію з боргами та розписками. Інші юристи говорили загальними фразами, а тут отримав конкретний план дій. Частину питання вирішили навіть швидше, ніж очікував.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-12 00:00:00', NULL, '23bcd1d347321689b39db27499f12f9a45755c7d', 'google', 'Poco F1', 'img/empty.png?a2499e3b0', '2026-06-12', '2026-06-28 15:16:13', '2026-07-02 12:17:48'),
(9618, 502, NULL, 'Юля Рабошапка', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернулася до Олександра Володимировича по рекомендації знайомих. Потрібно було терміново підготувати документи до суду. Все зробили швидко та без помилок.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-07 00:00:00', NULL, 'f06764994de58d1b23e157e969c32cabda88963a', 'google', 'Юля Рабошапка', 'img/empty.png?a2499e3b0', '2026-06-07', '2026-06-28 15:16:14', '2026-07-02 12:17:48'),
(9619, 502, NULL, 'Софія Тюхтій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Працювали з Маликом О. В. по господарській справі. Навіть перша консультація адвоката справила позитивне враження. Сподобалося, що він уважно вивчив документи, а не просто пробігся поверхнево. Видно досвід і практику.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-23 00:00:00', NULL, '10ee2784983fde87cb9cc64079bb03a86f3ded22', 'google', 'Софія Тюхтій', 'img/empty.png?a2499e3b0', '2026-05-23', '2026-06-28 15:16:14', '2026-07-02 12:17:48'),
(9620, 502, NULL, 'Liana Muchnuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хороший адвокат. Консультація була зрозуміла навіть для людини без юридичних знань. Не нав’язує зайвих послуг і нормально пояснює ризики.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-21 00:00:00', NULL, '7ce6d06f36dc065a30af24ba71f0b774f00405d3', 'google', 'Liana Muchnuk', 'img/empty.png?a2499e3b0', '2026-05-21', '2026-06-28 15:16:14', '2026-07-02 12:17:48'),
(9621, 502, NULL, 'Sacha892', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Довелося звернутись через проблеми з документами на квартиру після покупки. Шукав хорошого адвоката у Вінниці. Орієнтувався на відгуки. Не прогадав. Олександр Володимирович швидко пояснив, у чому проблема і як її можна вирішити. Без зайвих обіцянок, все по факту. У результаті питання закрили для мене позитивно.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-19 00:00:00', NULL, 'cfe1279afc7648a2b79adf28ef072539e185b227', 'google', 'Sacha892', 'img/empty.png?a2499e3b0', '2026-05-19', '2026-06-28 15:16:15', '2026-07-02 12:17:48'),
(9622, 502, NULL, 'Максим Яромeнко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро дякую адвокату Малику Олександру Володимировичу за професіоналізм, підтримку та відповідальне ставлення до своєї справи. Ви уважно поставилися до моєї ситуації, усе детально пояснили та допомогли знайти правильне рішення. Завдяки вашій компетентності й наполегливості я почувався впевнено та спокійно. Рекомендую вас як надійного, чесного та досвідченого фахівця.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-17 00:00:00', NULL, '14a77b2ea2eefc6cb103f30d942a36ae434402fb', 'google', 'Максим Яромeнко', 'img/empty.png?a2499e3b0', '2026-05-17', '2026-06-28 15:16:15', '2026-07-02 12:17:48'),
(9623, 502, NULL, 'Svitlana Heikina', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую Олександру Володимировичу за відповідальність та професійний підхід. Робота виконана швидко та якісно, потрібні документи отримала навіть раніше, ніж очікувала. Дуже задоволена! Однозначно рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-07 00:00:00', NULL, '93530ad1111a112d5ec3761c86a63b97b4c3cb20', 'google', 'Svitlana Heikina', 'img/empty.png?a2499e3b0', '2026-05-07', '2026-06-28 15:16:15', '2026-07-02 12:17:48'),
(9624, 502, NULL, 'Yaryna Pryimak', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталася до адвоката Малика Олександра Володимировича за консультацією з цивільного питання. Усе пояснив просто й доступно, без зайвої юридичної складності. Допоміг розібратися в документах і порадив, як краще діяти надалі. Загалом консультацією залишилася задоволена.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-26 00:00:00', NULL, '74bba6749180018b351ed66fa8b8f290d0086686', 'google', 'Yaryna Pryimak', 'img/empty.png?a2499e3b0', '2026-04-26', '2026-06-28 15:16:16', '2026-07-02 12:17:48'),
(9625, 502, NULL, 'Міха', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Скористався онлайн-консультацією — зручно, що зараз такі послуги доступні. Все пройшло оперативно і по суті. Олександр Володимирович відповів на всі запитання та допоміг розібратися в юридичних нюансах ситуації.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-25 00:00:00', NULL, '60707dc391e4ded4fe058a88ad6deb86fdf39eca', 'google', 'Міха', 'img/empty.png?a2499e3b0', '2026-04-25', '2026-06-28 15:16:16', '2026-07-02 12:17:48'),
(9626, 502, NULL, 'Лиза', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійний підхід до справи. Олександр Володимирович детально роз’яснив можливі варіанти вирішення та пояснив, які наслідки може мати кожен із них.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-09 00:00:00', NULL, 'e0ddc6482e40ff9f2160544b1c497ff5362a0a23', 'google', 'Лиза', 'img/empty.png?a2499e3b0', '2026-04-09', '2026-06-28 15:16:16', '2026-07-02 12:17:48'),
(9627, 502, NULL, 'Алена Чередніченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Не довіряйте штучному інтелекту, довіряйте професіоналам та знавцям Законодавства. Дякую Олександру, що відповів на всі мої запитання та прояснив ситуацію.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-09 00:00:00', NULL, '3ec34f1284d3995866f67ed157643cc4b2d8b60e', 'google', 'Алена Чередніченко', 'img/empty.png?a2499e3b0', '2026-04-09', '2026-06-28 15:16:17', '2026-07-02 12:17:48'),
(9628, 502, NULL, 'Миша Михаил', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Гарний адвокат у Вінниці: допоміг з підготовкою документів і детально пояснив, як діяти на кожному етапі справи. Відчувається, що має реальний практичний досвід.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-04 00:00:00', NULL, '1dd8724f7ed109856f5c03ea30b0e2bc38b93475', 'google', 'Миша Михаил', 'img/empty.png?a2499e3b0', '2026-04-04', '2026-06-28 15:16:17', '2026-07-02 12:17:48'),
(9629, 502, NULL, 'Стаська Курило', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Треба була допомога юриста онлайн, бо можливості кудись їхати не було. Олександр Володимирович відповів швидко, вислухав уважно, предложив пару можливих варіантів рішення моєї питання. Спілкування було і спокійним, і професійним.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-01 00:00:00', NULL, '77c9890541b2063c0b8a3988910c59c6bbb0d749', 'google', 'Стаська Курило', 'img/empty.png?a2499e3b0', '2026-04-01', '2026-06-28 15:16:17', '2026-07-02 12:17:48'),
(9630, 502, NULL, 'Maloy2012', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую за юридичну підтримку. Правовик допоміг розібратися у складному питанні та пояснив подальші кроки. Якщо вам потрібен хороший адвокат у Вінниці, рекомендую саме Малика О. В.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-28 00:00:00', NULL, '99a2adc70e2e355cc9dbf0f607e3c4f7aa9fb2de', 'google', 'Maloy2012', 'img/empty.png?a2499e3b0', '2026-03-28', '2026-06-28 15:16:18', '2026-07-02 12:17:48'),
(9631, 502, NULL, 'Евгения Чернушенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Отримала консультацію онлайн – круто, шо подібне в наші дні доступно. Все пройшло швидко і по суті. Олександр Володимирович відповів на всі питання і допоміг зрозуміти юридичну сторону ситуації.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-27 00:00:00', NULL, 'abdbdf64a84b5a88c9b19d074c5fd7ad49b99226', 'google', 'Евгения Чернушенко', 'img/empty.png?a2499e3b0', '2026-03-27', '2026-06-28 15:16:18', '2026-07-02 12:17:48'),
(9632, 502, NULL, 'Анна Гірфанова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась до адвоката вперше. Отримала зрозумілі відповіді на всі питання і чітке пояснення щодо процедури розгляду справи.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-25 00:00:00', NULL, '40c5fd0ec2cb7b68f760c6b8a10b13b343dd6635', 'google', 'Анна Гірфанова', 'img/empty.png?a2499e3b0', '2026-03-25', '2026-06-28 15:16:19', '2026-07-02 12:17:48'),
(9633, 502, NULL, '1.15-С Риженко Олександр', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звертався щодо спору по договору. Адвокат уважно вивчив документи та запропонував оптимальне рішення. Пояснення були чіткі та зрозумілі.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-21 00:00:00', NULL, '2ca3ee2a0830246204b7821336267ed23f995d70', 'google', '1.15-С Риженко Олександр', 'img/empty.png?a2499e3b0', '2026-03-21', '2026-06-28 15:16:19', '2026-07-02 12:17:48'),
(9634, 502, NULL, 'Oleh Malik', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійний підхід до роботи. Олександр Володимирович детально пояснив, які є варіанти вирішення справи та які можуть бути наслідки кожного з них.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-21 00:00:00', NULL, 'c7dd114a5ddb9906eb61b14856a9acb532fd52f7', 'google', 'Oleh Malik', 'img/empty.png?a2499e3b0', '2026-03-21', '2026-06-28 15:16:19', '2026-07-02 12:17:48'),
(9635, 502, NULL, 'Віталій Петришин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Консультувався щодо сімейного питання. Розглядав кількох вінницьких адвокатів, але обрав цього, бо в нього багато позитивних відгуків, як виявилося, не дарма. Юрист детально пояснив усі нюанси та можливі ризики. Сподобалося, що не дає порожніх обіцянок, а чесно говорить про перспективи.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-17 00:00:00', NULL, '0cf003b627971aa72f5586caf0e3ea237b6ff8a6', 'google', 'Віталій Петришин', 'img/empty.png?a2499e3b0', '2026-03-17', '2026-06-28 15:16:20', '2026-07-02 12:17:48'),
(9636, 502, NULL, 'Саша', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звертався до Малика Олександра Володимировича за консультацією стосовно цивільної справи. Адвокат пояснив ситуацію нормальною простою мовою, без складних юридичних слів. Допоміг розібратися з документами і підказав, як краще діяти далі. В цілому залишився задоволений консультацією.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-16 00:00:00', NULL, 'ab7fd15f270195354526626345292897f1bed374', 'google', 'Саша', 'img/empty.png?a2499e3b0', '2026-03-16', '2026-06-28 15:16:20', '2026-07-02 12:17:48'),
(9637, 502, NULL, 'Barbara', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрібна була юридична допомога онлайн, так як можливості кудись їхати не було. Олександр Володимирович швидко відповів, уважно вислухав і запропонував кілька можливих варіантів вирішення питання. Спілкування було спокійним і професійним.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-12 00:00:00', NULL, '5c6df57f3f6032162de779270e89ffcb35f20d14', 'google', 'Barbara', 'img/empty.png?a2499e3b0', '2026-03-12', '2026-06-28 15:16:20', '2026-07-02 12:17:48'),
(9638, 502, NULL, 'споем вместе', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Малик Олександр Володимирович найкращий адвокат. Рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-05 00:00:00', NULL, '873586becf2b4c62fedf504a6ae116ef2a480ec8', 'google', 'споем вместе', 'img/empty.png?a2499e3b0', '2026-03-05', '2026-06-28 15:16:21', '2026-07-02 12:17:48'),
(9639, 502, NULL, 'Papa321', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Вдячний Олександру Володимировичу за допомогу! Він не тільки вирішив юридичне питання, а й вселив упевненість і спокій. Раджу всім, хто шукає адвоката у Вінниці.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-27 00:00:00', NULL, 'a48fb5e78046483a61483080d09cbeacc5b5003e', 'google', 'Papa321', 'img/empty.png?a2499e3b0', '2026-02-27', '2026-06-28 15:16:21', '2026-07-02 12:17:48'),
(9640, 502, NULL, 'Vasyl Holinei', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити щиру подяку адвокату за професійну та оперативну допомогу у отриманні витягу з державного реєстру цивільного стану. Я залишив заяву на сайті, і вже за кілька хвилин отримав від нього відповідь. Протягом кількох днів питання було вирішено, а за тиждень я отримав необхідний документ, надісланий новою поштою. Рекомендую цього спеціаліста всім, хто цінує швидкість, якість та надійність у юридичних послугах.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-26 00:00:00', NULL, '911ad33fdfd06119db01ddc47f4333459d8126d2', 'google', 'Vasyl Holinei', 'img/empty.png?a2499e3b0', '2026-02-26', '2026-06-28 15:16:21', '2026-07-02 12:17:48'),
(9641, 502, NULL, 'максим крещенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат постійно був на зв’язку, пояснював ризики й перспективи та відстоював саме мою позицію. Враження від роботи — позитивні.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-24 00:00:00', NULL, '2fee1f701f8ac9c3962fde2e7c2642e8e32b18c1', 'google', 'максим крещенко', 'img/empty.png?a2499e3b0', '2026-02-24', '2026-06-28 15:16:22', '2026-07-02 12:17:48'),
(9642, 502, NULL, 'Olena Stancea', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Довірила панові Олександру свою ситуацію, за яку довго не наважувалась братись, бо не була певна, що є можливе рішення лише в межах українського законодавства. На консультації мені було запропоновано кілька шляхів вирішення проблеми, а в подальшому завдяки професійному підходу, послідовності дій і досвіду адвоката вдалось досягти успіху у суді, за що дуже вдячна. Співпраця відбулась без нервів і стресу, все чітко і по суті. Буду рекомендувати Олександра як знавця своєї справи!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-23 00:00:00', NULL, 'd5a3a44e3b2a5ae3e6d78f817221494de74151ff', 'google', 'Olena Stancea', 'img/empty.png?a2499e3b0', '2026-02-23', '2026-06-28 15:16:22', '2026-07-02 12:17:48'),
(9643, 502, NULL, 'Іванна Сюсько', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Ми співпрацюємо з Олександром уже не вперше. Він добре розуміє бізнес-процеси, дає грамотні юридичні поради та забезпечує передбачуваний результат. Якщо потрібен спеціаліст з юридичних питань для бізнесу — рекомендую його без вагань.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-21 00:00:00', NULL, '6abd193668f569b7aa64bf0aefbab5b386dd9001', 'google', 'Іванна Сюсько', 'img/empty.png?a2499e3b0', '2026-02-21', '2026-06-28 15:16:22', '2026-07-02 12:17:48'),
(9644, 502, NULL, 'Іванка 6630', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Все чітко й професійно. Раніше не зверталась до адвокатів, але тут пояснили все доступно та зрозуміло. Постійно відчувала підтримку.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-20 00:00:00', NULL, 'c0f2b77c0c8a1b0143d167624f2ec171b7475712', 'google', 'Іванка 6630', 'img/empty.png?a2499e3b0', '2026-02-20', '2026-06-28 15:16:23', '2026-07-02 12:17:48'),
(9645, 502, NULL, 'StuDent', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Звернувся до цього адвоката, поставив питання чи зможе він допомогти в отриманні дозволу від національно соціальної служби, на що відразу прийшла відповідь, консультація 1800. Я запитав за що я повинен платити якщо ви мені дасте ту ж інформацію, що я знаю, я запитав чи може він відповісти, зможе допомогти чи ні, і далі вирішуватимемо питання співпраці. На що мені відразу написав я з вами не працюватиму, ви мене з першої хвилини не чуєте. Серйозно не чую, дай 1800 за інформацією загальнодоступну, і досвідання.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-19 00:00:00', NULL, 'fc1aba7df3bcb8676d9d95bcdd916d66c56c6b90', 'google', 'StuDent', 'img/empty.png?a2499e3b0', '2026-02-19', '2026-06-28 15:16:23', '2026-07-02 12:17:48'),
(9646, 502, NULL, 'Andriy Partyka', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Юрист показав справжній професіоналізм: відповідальний, компетентний і завжди дотримується домовленостей. Я звернувся з непростим питанням, де важливо було не гаяти час. Олександр швидко розібрався у всьому, пояснив можливі ризики і запропонував найкраще рішення. Результат перевершив мої очікування.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '7c46e43ec3d257486cb8cdb655eb9e409fa38a56', 'google', 'Andriy Partyka', 'img/empty.png?a2499e3b0', '2026-02-18', '2026-06-28 15:16:23', '2026-07-02 12:17:48'),
(9647, 502, NULL, 'Viktorovich', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Якщо шукаєте адвоката, який працює на результат, а не створює видимість діяльності — сміливо звертайтесь. Досвід співпраці виключно позитивний.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-07 00:00:00', NULL, 'ab49f373e24bded6b3be012a426484005241e652', 'google', 'Viktorovich', 'img/empty.png?a2499e3b0', '2026-02-07', '2026-06-28 15:16:24', '2026-07-02 12:17:48'),
(9648, 502, NULL, 'Elena Dudnik', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Класний спеціаліст. Моє питання вирішив швидше, ніж я очікувала. Без затягувань і зайвої бюрократії.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-29 00:00:00', NULL, 'f457e91da80892fe039bc55e2ad4b95abe0e4e7b', 'google', 'Elena Dudnik', 'img/empty.png?a2499e3b0', '2026-01-29', '2026-06-28 15:16:24', '2026-07-02 12:17:48'),
(9649, 502, NULL, 'StuDent', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Обратился к этому адвокату, задал вопрос сможет ли он помочь в получении разрешения от национально социальной службы , на что сразу пришёл ответ, консультация 1800. Я спросил за что я должен платить если вы мне дадите ту же информацию что я знаю, я спросил может ли он ответить, сможет помочь или нет, и дальше будем решать вопрос сотрудничества. На что мне сразу написал я с вами работать не буду, вы меня с первой минуты не слышите. Серьёзно не слышу, дай 1800 за информацтю общедоступную, и досвиданье👍👍👍👍', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-27 00:00:00', NULL, '641295a77a3e942921245aae68789a2e14bed3dd', 'google', 'StuDent', 'img/empty.png?a2499e3b0', '2026-01-27', '2026-06-28 15:16:25', '2026-07-02 12:17:48'),
(9650, 502, NULL, 'Кристина Упіровець', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Малик Олександр Володимирович уважний до деталей, добре орієнтується в законодавстві та завжди на зв’язку. Співпрацею залишилась задоволена.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-26 00:00:00', NULL, 'fb443f332d30ca0596fef7159e34f67180283878', 'google', 'Кристина Упіровець', 'img/empty.png?a2499e3b0', '2026-01-26', '2026-06-28 15:16:25', '2026-07-02 12:17:48'),
(9651, 502, NULL, 'Вікторія «Косметолог - Естетист» Миза', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійний адвокат, який чітко пояснює кожен крок і тримає справу під контролем. Результатом повністю задоволена.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-19 00:00:00', NULL, 'e7c80ed22ab0edb1878f03063e9010c77086df9b', 'google', 'Вікторія «Косметолог - Естетист» Миза', 'img/empty.png?a2499e3b0', '2026-01-19', '2026-06-28 15:16:25', '2026-07-02 12:17:48'),
(9652, 502, NULL, 'Alina Kravets', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Олександр Володимирович, майстер своєї справи . Делікатно підходить до справи , професійно вирішує навіть самі не стандартні проблеми . Дуже задоволена роботою та щиро рекомендую Малика Олександра Володимировича , як адвоката!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-15 00:00:00', NULL, '1215160588da68fde713ac7bc0fa88880424ac66', 'google', 'Alina Kravets', 'img/empty.png?a2499e3b0', '2026-01-15', '2026-06-28 15:16:26', '2026-07-02 12:17:48'),
(9653, 502, NULL, 'Валя Поташова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрібен був надійний адвокат для вирішення спадкових питань. Олександр Володимирович систематизував усі документи, підготував необхідні запити та допоміг досягти позитивного результату. Щиро дякую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-04 00:00:00', NULL, 'f54b37347c50da33e4b176ebbe0c1bb59af81846', 'google', 'Валя Поташова', 'img/empty.png?a2499e3b0', '2026-01-04', '2026-06-28 15:16:26', '2026-07-02 12:17:48'),
(9654, 502, NULL, 'Артем Філімон', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Сам кілька разів звертався за допомогою, тому сміливо можу рекомендувати до співпраці.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-12-30 00:00:00', NULL, 'be27991aefd565636ff496154f863da60c5a698d', 'google', 'Артем Філімон', 'img/empty.png?a2499e3b0', '2025-12-30', '2026-06-28 15:16:26', '2026-07-02 12:17:48'),
(9655, 502, NULL, 'Льоня Непийвода', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Наданою адвокатською послугою Олександра Васильовича задоволений цілком та повністю .Особливості -професійність ,вічливість ,тактовність ,людяність та вміння вислухати людину і допомогти у захисті своїх інтересів .Рекомендую !', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-12-30 00:00:00', NULL, 'e8aeb542d92a5e4c8d9c72a25760da1ac8d11a04', 'google', 'Льоня Непийвода', 'img/empty.png?a2499e3b0', '2025-12-30', '2026-06-28 15:16:27', '2026-07-02 12:17:48'),
(9656, 502, NULL, 'Дима Тиша', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Навіть законослухняна людина може втрапити в халепу і отримати обвинувачення у злочині. Саме це трапилося з моїм близьким другом. Адвокат оперативно виїхав,взяв справу під контроль,зібрав докази. Справу закрили за відсутностю складу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-12-29 00:00:00', NULL, '3b0e557341c9f042e4fd539521f32ebf53810108', 'google', 'Дима Тиша', 'img/empty.png?a2499e3b0', '2025-12-29', '2026-06-28 15:16:27', '2026-07-02 12:17:48'),
(9657, 502, NULL, 'Женя Женя', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Круто, що сьогодні отримати юридичну консультацію можна в режимі онлайн, не виходячи з дому. Нещодавно скористався цією можливістю. Дякую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-12-22 00:00:00', NULL, 'bc56e3e90764952b38100db4bf9cb219d0c8f4aa', 'google', 'Женя Женя', 'img/empty.png?a2499e3b0', '2025-12-22', '2026-06-28 15:16:27', '2026-07-02 12:17:48'),
(9658, 502, NULL, 'Діма Борсученко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Проводили угоду купівлі квартири у місті Вінниця. Самі там не проживаємо, тому потрібна була компетентна людина, що знається на законодавстві та з усім допоможе. Адвокат Малик виявився саме тим, хто нам був потрібен.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-12-19 00:00:00', NULL, 'db53aeb6e8ab221861aab4e24146b4f00d3b9e9f', 'google', 'Діма Борсученко', 'img/empty.png?a2499e3b0', '2025-12-19', '2026-06-28 15:16:28', '2026-07-02 12:17:48'),
