(9664, 502, NULL, 'Marina Podolianu', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась до адвоката Олександра Малика у Вінниці з питання розлучення — усе пройшло спокійно, швидко й без жодних нервів. Щиро рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-11-08 00:00:00', NULL, 'dcead0d8b196397687662962aa50b855c32f3df3', 'google', 'Marina Podolianu', 'img/empty.png?a2499e3b0', '2025-11-08', '2026-06-28 15:16:30', '2026-07-02 12:17:48'),
(9665, 502, NULL, 'Людмила Борушко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже сподобався сервіс — юрист уважний, відповідальний і завжди на зв’язку. Отримала детальну консультацію та кваліфіковану допомогу з документами.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-11-04 00:00:00', NULL, '1f8e0c7cd73afe9f79bca27cb467d2791e55453c', 'google', 'Людмила Борушко', 'img/empty.png?a2499e3b0', '2025-11-04', '2026-06-28 15:16:30', '2026-07-02 12:17:48'),
(9666, 502, NULL, 'Татьяна Горошко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Високий професіоналізм, ввічливість і швидке реагування на запити. Чудовий адвокат.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-31 00:00:00', NULL, '740e6322cef0f829a520249004549b9402ea93a7', 'google', 'Татьяна Горошко', 'img/empty.png?a2499e3b0', '2025-10-31', '2026-06-28 15:16:31', '2026-07-02 12:17:48'),
(9667, 502, NULL, 'Марина Костюніна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професіонал. Кілька разів наша сім’я зверталася до Олександра з різних питань і у всіх він нам допоміг. Знається на різних сферах права. Дуже ввічливий та людяний.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-30 00:00:00', NULL, 'c003151388335ba93697f7e6b08a9a72da9b33f9', 'google', 'Марина Костюніна', 'img/empty.png?a2499e3b0', '2025-10-30', '2026-06-28 15:16:31', '2026-07-02 12:17:48'),
(9668, 502, NULL, 'Клієнт ****6464', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звертався до адвоката Малика Олександра щодо розлучення та супутніх питань із майном. Професіонал своєї справи! Всі етапи справи пояснив детально, підготував потрібні документи та супроводжував процес у суді від початку до кінця. Результат — повне задоволення позову без зайвих проблем. Рекомендую всім, хто шукає надійного та відповідального адвоката у Вінниці.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-28 00:00:00', NULL, 'b8fb7b6853355ae621a83c6df19ab895f6b06e22', 'google', 'Клієнт ****6464', 'img/empty.png?a2499e3b0', '2025-10-28', '2026-06-28 15:16:31', '2026-07-02 12:17:48'),
(9669, 502, NULL, 'Екатерина Беседина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась за юридичними послугами для оформлення розлучення – все пройшло гладко та без нервів. Велика подяка! Якщо вам потрібен адвокат Вінниця, то сміливо можу рекомендувати до співпраці Малика О.В.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-26 00:00:00', NULL, 'ed78551627410f575a26f93bdcd658f175cfb7d7', 'google', 'Екатерина Беседина', 'img/empty.png?a2499e3b0', '2025-10-26', '2026-06-28 15:16:32', '2026-07-02 12:17:48'),
(9670, 502, NULL, 'Сергій Остапенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Малик допоміг вирішити сімейну суперечку. Він підтримував мене на всіх етапах.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-26 00:00:00', NULL, '4673b5744308aff3f3e6e82d9124f9a0f508e8a0', 'google', 'Сергій Остапенко', 'img/empty.png?a2499e3b0', '2025-10-26', '2026-06-28 15:16:32', '2026-07-02 12:17:48'),
(9671, 502, NULL, 'Yuriy Panchenko', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'дуже професійна консультація, п. Олександр детально відповідає на питання, раджу ретельно готуватися до спілкування', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-19 00:00:00', NULL, 'ca74f72b48a65a8528ceaacebed1967b9246a6c8', 'google', 'Yuriy Panchenko', 'img/empty.png?a2499e3b0', '2025-10-19', '2026-06-28 15:16:33', '2026-07-02 12:17:48'),
(9672, 502, NULL, 'Геннадій Коба', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрібна була консультація з розірвання шлюбу. Знайомі порадили до співпраці Малика. Олександр Володимирович справді допоміг, а судові процеси пройшли без зайвого стресу. Дуже задоволений.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-19 00:00:00', NULL, '1cb5154f3c7b91d54f38980dd17fdbf21f18b8e0', 'google', 'Геннадій Коба', 'img/empty.png?a2499e3b0', '2025-10-19', '2026-06-28 15:16:33', '2026-07-02 12:17:48'),
(9673, 502, NULL, 'Миша Троян', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Вражений рівнем сервісу – юрист уважний до деталей і завжди на зв’язку. Надав мені повну консультацію, а потім допоміг з паперами.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-08 00:00:00', NULL, 'fc8ff4eba5814bf4b69aa5bb986b53aa39d42631', 'google', 'Миша Троян', 'img/empty.png?a2499e3b0', '2025-10-08', '2026-06-28 15:16:33', '2026-07-02 12:17:48'),
(9674, 502, NULL, 'Виталий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже вдячний цьому адвокату за професійну допомогу. Всі документи, що мені були потрібні, підготовлені швидко та чітко.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-04 00:00:00', NULL, '6b2130bd6c3ac133ab7e466244d279b08248b15f', 'google', 'Виталий', 'img/empty.png?a2499e3b0', '2025-10-04', '2026-06-28 15:16:34', '2026-07-02 12:17:48'),
(9675, 502, NULL, 'Маргаріта', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Треба було терміново вирішити спадкове питання. Олександр одразу взявся за роботу та показав високий рівень знань у юриспруденції. У результаті все завершилось успішно, співпрацею залишилась задоволена!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-29 00:00:00', NULL, '3336b37c3ee2fa7735696145d6425316ff98ce8f', 'google', 'Маргаріта', 'img/empty.png?a2499e3b0', '2025-09-29', '2026-06-28 15:16:34', '2026-07-02 12:17:48'),
(9676, 502, NULL, 'Руслан Попов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Консультувався у пана Олександра з приводу розірвання шлюбу. Отримав дуже багато корисної інформації. Пан Олександр не лише детально відповів на всі мої запитання, але й розповів про всі ймовірні варіанти розвитку подій та можливі стратегії поведінки для них. Консультацією дуже задоволений. Планую доручити пану Олександру ведення самої справи щодо розірвання шлюбу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-28 00:00:00', NULL, '6accfb293e48b25dec27f085a3f645f6135d1a35', 'google', 'Руслан Попов', 'img/empty.png?a2499e3b0', '2025-09-28', '2026-06-28 15:16:34', '2026-07-02 12:17:48'),
(9677, 502, NULL, 'анна маросина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити подяку адвокату Малику Олександру Володимировичу за кваліфіковану допомогу. У разі якщо шукаєте хорошого юриста у Вінниці - сміливо можна звертатися сюди! Перевірено на власному досвіді.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-24 00:00:00', NULL, '8d698fbf508867c6c2ce370f0823e05aea1f2eda', 'google', 'анна маросина', 'img/empty.png?a2499e3b0', '2025-09-24', '2026-06-28 15:16:35', '2026-07-02 12:17:48'),
(9678, 502, NULL, 'Гліб Чесноков', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрапив у трудовий спір і не знав, як правильно захищати свої права. Юрист у Вінниці надав вичерпну консультацію, яка справді допомогла. P.S. Дивно усвідомлювати, наскільки ми часто не знаємо своїх прав і через це втрачаємо більше, ніж мали б', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-19 00:00:00', NULL, '58860263df2cf8349f7787ad2afd76a4500b5fb3', 'google', 'Гліб Чесноков', 'img/empty.png?a2499e3b0', '2025-09-19', '2026-06-28 15:16:35', '2026-07-02 12:17:48'),
(9679, 502, NULL, 'Софія Жолоб', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро дякую адвокату Олександру Малику за допомогу у розірванні шлюбу через суд. Все пройшло добре, без зайвих непотрібних на цей час емоцій. Ще раз дякую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-16 00:00:00', NULL, 'd8760baebdd389ac4e6b52c8ea00bd86de96fde0', 'google', 'Софія Жолоб', 'img/empty.png?a2499e3b0', '2025-09-16', '2026-06-28 15:16:36', '2026-07-02 12:17:48'),
(9680, 502, NULL, 'Женька Енінгій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрібно було терміново оформити спадщину. Олександр оперативно взявся за справу та показав високий рівень знань у законодавстві. У результаті все вдалося вирішити успішно. Дуже вдячна за професійну допомогу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-13 00:00:00', NULL, 'c5e056f08145bc7c648fb114a99cf4c2e73b27f1', 'google', 'Женька Енінгій', 'img/empty.png?a2499e3b0', '2025-09-13', '2026-06-28 15:16:36', '2026-07-02 12:17:48'),
(9681, 502, NULL, 'Наталія Катано', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталася до адвоката Малика з дуже важливого для мене сімейного питання – розлучення та аліменти. Олександр Володимирович уважно проаналізував справу, все детально пояснив і чітко окреслив план дій. Завдяки його професіоналізму процес пройшов швидко та з мінімальними переживаннями. Раджу цього юриста у Вінниці як надійного та компетентного.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-11 00:00:00', NULL, '0315cdfcdbbe84a93176aaf115b5dc4b501c0a0d', 'google', 'Наталія Катано', 'img/empty.png?a2499e3b0', '2025-09-11', '2026-06-28 15:16:36', '2026-07-02 12:17:48'),
(9682, 502, NULL, 'Маріанна Грицюк', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернулась за допомогою до Василя Васильовича і задоволена. Швидко, якісно і головне результативно, завжди на зв\'язку. Щиро рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-10 00:00:00', NULL, 'ea652864f011040e9543725c12abc52f2b2a161c', 'google', 'Маріанна Грицюк', 'img/empty.png?a2499e3b0', '2025-09-10', '2026-06-28 15:16:37', '2026-07-02 12:17:48'),
(9683, 502, NULL, 'Катерина Стамат', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Шукали фахівця з військових питань у м.Вінниця – Олександр Володимирович допоміг. Вдячні за професіоналізм. У такий непростий час це зустрічається й не так часто.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-09 00:00:00', NULL, 'c883fc7b3e0061fc7e8ad8015606b41c27615cc2', 'google', 'Катерина Стамат', 'img/empty.png?a2499e3b0', '2025-09-09', '2026-06-28 15:16:37', '2026-07-02 12:17:48'),
(9684, 502, NULL, 'Nataliia Andrukhova', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Користувалась послугами адвоката вперше, залишилась дуже задоволена! Питання були пов‘язані з розірванням трудового договору Після консультації залишилась з відповідями на всі запитання, було дуже приємно, що адвокат консультував до повного вирішення ситуації також заспокоював та надавав впевненості у вирішенні всіх подробиць Дуже раджу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-09 00:00:00', NULL, '15ab9d21a99aaacc348d9deefb937ba7e533c491', 'google', 'Nataliia Andrukhova', 'img/empty.png?a2499e3b0', '2025-09-09', '2026-06-28 15:16:37', '2026-07-02 12:17:48'),
(9685, 502, NULL, 'Asya Volkova', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я підприємець і по роботі постійно виникають правові питання − усе довіряю Малику Олександру Володимировичу. Знаю його досить довго – ні разу не підводив!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-09-06 00:00:00', NULL, 'cb28ae56bf1ccc9d28008a9d0d79c3a48f81152a', 'google', 'Asya Volkova', 'img/empty.png?a2499e3b0', '2025-09-06', '2026-06-28 15:16:38', '2026-07-02 12:17:48'),
(9686, 502, NULL, 'Катерина Хижевская', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрібна була допомога у трудовому спорі: я опинилась у ситуації, де права порушувались, а я не знала, як діяти. Консультація юриста у Вінниці дуже мені допомогла. P.S. Навіть смішно з того, як погано ми знаємо свої права, через що часто й страждаємо.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-30 00:00:00', NULL, 'a7aa9d0b4f5529f84000f0763b3a8bf065d530d0', 'google', 'Катерина Хижевская', 'img/empty.png?a2499e3b0', '2025-08-30', '2026-06-28 15:16:38', '2026-07-02 12:17:48'),
(9687, 502, NULL, 'Віола Шелюженко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Наша сім’я, як і багато хто, стала учасником правового спору з забудовником. Інвестування в нерухомість – завжди ризик... Довелося звертатися за допомогою до юриста. Знайомі порадили Олександра. Він проконсультував, підготував сильну стратегію, відстояв мої права у суді. Ми дуже задоволені результатом.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-25 00:00:00', NULL, '0f16efec09d9fc2a2d1a73e1d3bf90def49c0594', 'google', 'Віола Шелюженко', 'img/empty.png?a2499e3b0', '2025-08-25', '2026-06-28 15:16:38', '2026-07-02 12:17:48'),
(9688, 502, NULL, 'андрей фесик', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійний підхід результативно і без зайвих слів. Дякуємо за чітку та своєчасну допомогу', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-24 00:00:00', NULL, '9228dc3d940909f9bc5d9a4c55035e766f81b621', 'google', 'андрей фесик', 'img/empty.png?a2499e3b0', '2025-08-24', '2026-06-28 15:16:39', '2026-07-02 12:17:48'),
(9689, 502, NULL, 'Ярослав Марченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Став учасником ДТП не зі своєї вини. Почалися правові спори. Адвокат Олександр Малик провів грамотну консультацію і супроводжував справу до переможного завершення. Його підтримка і професіоналізм варті довіри. Дуже вдячний!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-23 00:00:00', NULL, '75438cb71137ab5ac21f0e003fd139974de7ee37', 'google', 'Ярослав Марченко', 'img/empty.png?a2499e3b0', '2025-08-23', '2026-06-28 15:16:39', '2026-07-02 12:17:48'),
(9690, 502, NULL, 'андрей фесик', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Профессиональный подход, результативно, и без лишних слов. Спасибо за чёткую и своевременную помощь', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-20 00:00:00', NULL, '6634356e3f6d7cb15d32d7a175a287272db4e595', 'google', 'андрей фесик', 'img/empty.png?a2499e3b0', '2025-08-20', '2026-06-28 15:16:40', '2026-07-02 12:17:48'),
(9691, 502, NULL, 'Оксана Глух', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мені потрібно було швидко вирішити питання спадщини. Олександр сміливо взявся за справу. У роботі продемонстрував глибоке знання законодавства. Питання закрите успішно. Співпрацею задоволена!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-18 00:00:00', NULL, '6719322a48b6897020a544c27791617a7441f041', 'google', 'Оксана Глух', 'img/empty.png?a2499e3b0', '2025-08-18', '2026-06-28 15:16:40', '2026-07-02 12:17:48'),
(9692, 502, NULL, 'Алина Евченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Нещодавно звернулася до адвоката Малика у надважливому для мене сімейному питанні − розлученні та стягненні аліментів. Олександр Володимирович детально вивчив ситуацію, пояснив кожен крок і чітко дав зрозуміти, як саме захищатиме мої інтереси. У результаті справа була завершена оперативно, з найменшим стресом для мене. Рекомендую як надійного й професійного юриста у м.Вінниця!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-16 00:00:00', NULL, 'c9fde5ba740fdc6b5307e5c6a2a4dcbb175dc71c', 'google', 'Алина Евченко', 'img/empty.png?a2499e3b0', '2025-08-16', '2026-06-28 15:16:40', '2026-07-02 12:17:48'),
(9693, 502, NULL, 'Ірина Скрипник', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Фахівець з великої літери! Дуже допоміг мені, сміливо рекомендую звертатись за потреби 👍', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-12 00:00:00', NULL, '5b8a24fb6b046f0634e54a1945fc8ffe7eaab60b', 'google', 'Ірина Скрипник', 'img/empty.png?a2499e3b0', '2025-08-12', '2026-06-28 15:16:41', '2026-07-02 12:17:48'),
(9694, 502, NULL, 'Дина Шевченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Після безпідставного звільнення з роботи мені терміново потрібен був адвокат у Вінниці. Знайшла Олександра Малика через відгуки в інтернеті — і жодного разу не пошкодувала про свій вибір.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-04 00:00:00', NULL, 'ac1622bfd53438bb88ed2baf926908551e71a295', 'google', 'Дина Шевченко', 'img/empty.png?a2499e3b0', '2025-08-04', '2026-06-28 15:16:41', '2026-07-02 12:17:48'),
(9695, 502, NULL, 'Ксюша Глазкова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась по юридичну консультацію – дуже приємне враження. Все доступно пояснив, підказав, як краще вчинити. Відчувається, що це не тільки відмінний фахівець своєї справи, але й просто хороша людина.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-02 00:00:00', NULL, '766f752022a132ea034062514d22789aaad0bae8', 'google', 'Ксюша Глазкова', 'img/empty.png?a2499e3b0', '2025-08-02', '2026-06-28 15:16:41', '2026-07-02 12:17:48'),
(9696, 502, NULL, 'Галина Цимбаліста', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійний підхід, ввічливість, знання законодавства – все це про адвоката Малика. Відразу після консультації стало зрозуміло, як діяти далі.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-28 00:00:00', NULL, '071bc36cfbe69ae9f163acbe6767ab937c947410', 'google', 'Галина Цимбаліста', 'img/empty.png?a2499e3b0', '2025-07-28', '2026-06-28 15:16:42', '2026-07-02 12:17:48'),
(9697, 502, NULL, 'Мирося Мариновська', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Найкращий юрист у м.Вінниця! 5 з 5.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-27 00:00:00', NULL, '6b852fe424b49def713652b34a97d807d585c4ab', 'google', 'Мирося Мариновська', 'img/empty.png?a2499e3b0', '2025-07-27', '2026-06-28 15:16:42', '2026-07-02 12:17:48');
