(9698, 502, NULL, 'Вікторія Половина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Не вперше звертаюсь до Олександра – спочатку по цивільні справі, трохи пізніше - по сімейній. В обох випадках усе було на висоті.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-25 00:00:00', NULL, 'cceeb596aedfcfb38946e4a927de195568d7f858', 'google', 'Вікторія Половина', 'img/empty.png?a2499e3b0', '2025-07-25', '2026-06-28 15:16:42', '2026-07-02 12:17:48'),
(9699, 502, NULL, 'Сергій Шелепун', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую адвокат знає свою роботу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-24 00:00:00', NULL, '9c08d1bb092773bff47f38b152cbba4489ae100a', 'google', 'Сергій Шелепун', 'img/empty.png?a2499e3b0', '2025-07-24', '2026-06-28 15:16:43', '2026-07-02 12:17:48'),
(9700, 502, NULL, 'Лєра Чорна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже задоволена роботою цього адвоката. Олександр Володимирович допоміг мені з питанням виплати заборгованості по зарплаті через суд. Я розуміла, що роботодавець дурить мене і користується моєю необізнаністю у законодавстві, але довести свою правоту не могла. Юрист все оформив, підготував документи, представляв мої інтереси. Справу ми виграли. Якщо вам потрібен хороший адвокат у Вінниці – це він!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-21 00:00:00', NULL, 'e4bc0442d853ef52c60b61a70c851f27e4a8d9f9', 'google', 'Лєра Чорна', 'img/empty.png?a2499e3b0', '2025-07-21', '2026-06-28 15:16:43', '2026-07-02 12:17:48'),
(9701, 502, NULL, 'Anna Semenchuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Шукала надійного адвоката у Вінниці для вирішення спадкових питань. Знайомі порекомендували Олександра Малика бо же мали досвід співпраці з ним і залишились задоволені. І я тепер теж дуже вдячна за професіоналізм - усе було вирішено швидко, чітко і без зайвого стресу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-17 00:00:00', NULL, '356fe2b544e2c134d4f4acf6ded804f7e45801f2', 'google', 'Anna Semenchuk', 'img/empty.png?a2499e3b0', '2025-07-17', '2026-06-28 15:16:43', '2026-07-02 12:17:48'),
(9702, 502, NULL, 'Яна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Справжній професіонал своєї справи, якщо вам потрібні послуги адвоката у Вінниці – то сміло раджу! Допоміг мені у дуже складній справі по ДТП. Не пошкодувала, що звернулась саме до нього. Респект!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-14 00:00:00', NULL, 'e5baafc712f6989bfdb956e8362520bb928e9f1e', 'google', 'Яна', 'img/empty.png?a2499e3b0', '2025-07-14', '2026-06-28 15:16:44', '2026-07-02 12:17:48'),
(9703, 502, NULL, 'Roman Voityuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернувся до адвоката Олександра — пояснив усе просто і доступно, без юридичних «заворотів». Послуги на рівні, залишились лише хороші враження. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-11 00:00:00', NULL, '9b517e4995d82556f6d6fe196b226ce6c81cd222', 'google', 'Roman Voityuk', 'img/empty.png?a2499e3b0', '2025-07-11', '2026-06-28 15:16:44', '2026-07-02 12:17:48'),
(9704, 502, NULL, 'Mary Made', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Пунктуальна і хороша консультація.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-11 00:00:00', NULL, '54500c42c57f47775ef595064180ee5e3eee31de', 'google', 'Mary Made', 'img/empty.png?a2499e3b0', '2025-07-11', '2026-06-28 15:16:44', '2026-07-02 12:17:48'),
(9705, 502, NULL, 'Максим Покришка', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Шукав хорошого адвоката у Вінниці для вирішення спадкової справи. Знайомі порадили Малика Олександра, бо якось зверталися до нього за допомогою і залишилися задоволені. Дуже вдячний юристу! Все пройшло швидко, грамотно і без зайвих нервів.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-09 00:00:00', NULL, '21533117cb1b591c731cc24c520b82490a065d1e', 'google', 'Максим Покришка', 'img/empty.png?a2499e3b0', '2025-07-09', '2026-06-28 15:16:45', '2026-07-02 12:17:48'),
(9706, 502, NULL, 'Олена Черешня', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я займаюся бізнесом і зіткнулась із проблемами з податковою. Мені Потрібен був не просто юрист, а спеціаліст, який добре орієнтується в господарському праві. Малик допоміг оформити всі необхідні документи й супроводжував справу до кінця. Компетентний, спокійний і дуже грамотний фахівець.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-03 00:00:00', NULL, '6a75c40c7e728acc84d9d6c246acb9fd305c63f4', 'google', 'Олена Черешня', 'img/empty.png?a2499e3b0', '2025-07-03', '2026-06-28 15:16:45', '2026-07-02 12:17:48'),
(9707, 502, NULL, 'Клієнт ****3722', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую адвокату за допомогу. Мені сподобалось те, що адвокат глибоко аналізує проблему і підбирає комплексний підхід. Мені підстрахував дуже круто і в наслідок його допомоги я уникнув проблем, які могли бути.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-03 00:00:00', NULL, '312dcf9f8bfda2c8727a8ea26dfd9d43d4f8db04', 'google', 'Клієнт ****3722', 'img/empty.png?a2499e3b0', '2025-07-03', '2026-06-28 15:16:45', '2026-07-02 12:17:48'),
(9708, 502, NULL, 'Valera', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернувся до цього адвоката через непорозуміння з поліцією: мене безпідставно затримали, складали якісь протоколи та навіть погрожували відповідальністю, хоча я так і не зрозумів, у чому справа. Олександр професійно відреагував, подав скаргу, і все було врегульовано :) Якщо потрібен адвокат у Вінниці з адміністративних питань — не вагайтеся, одразу звертайтеся до нього, щоб уникнути зайвих неприємностей із правоохоронцями.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-06-30 00:00:00', NULL, '127fdc4198337c5d98011ef636f6b7135ac8d202', 'google', 'Valera', 'img/empty.png?a2499e3b0', '2025-06-30', '2026-06-28 15:16:46', '2026-07-02 12:17:48'),
(9709, 502, NULL, 'Snezka Karaman', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Як підприємець мала досвід роботи з різними адвокатами, але лише з цим могла просто все довірити та ні про що не хвилюватися. Він сам тримав справу під контролем та оперативно реагував на ситуації.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-06-26 00:00:00', NULL, '806a5e140379668dcbdb93e99e9537a419ab1881', 'google', 'Snezka Karaman', 'img/empty.png?a2499e3b0', '2025-06-26', '2026-06-28 15:16:46', '2026-07-02 12:17:48'),
(9710, 502, NULL, 'Іван 1', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Допомагав мені в конфлікті з банком – хотіли через суд забрати майно. Професіонал і просто хороша людина. Завдяки грамотному захисту вдалося зберегти житло.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-06-24 00:00:00', NULL, '0a04af47bc2a0e229d569c4f045b50207ed940ba', 'google', 'Іван 1', 'img/empty.png?a2499e3b0', '2025-06-24', '2026-06-28 15:16:47', '2026-07-02 12:17:48'),
(9711, 502, NULL, 'Оксана Панасюк', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвоката рекомендую, все чітко, лаконічно та зрозумілою мовою юридичні питання', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-06-23 00:00:00', NULL, '5fd6a872434d28b0f5afaa99d6c4312df4e973e7', 'google', 'Оксана Панасюк', 'img/empty.png?a2499e3b0', '2025-06-23', '2026-06-28 15:16:47', '2026-07-02 12:17:48'),
