(11480, 553, NULL, 'Назар Мельник', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мав можливість співпрацювати з чудовим спеціалістом Анастасією Олександрівною. За рекомендацією знайомих та друзів. Дякую спеціалісту, за роботу, та за оперативність.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-31 00:00:00', NULL, '904f6d7479e18644d0685dfd4f7aa88562b3252c', 'google', 'Назар Мельник', 'img/empty.png?a2499e3b0', '2025-10-31', '2026-06-28 19:10:04', '2026-07-02 12:19:00'),
(11481, 553, NULL, 'Verona Musi', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Найкращі послуги в цій компінії', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-29 00:00:00', NULL, 'ccd34e3d1081316f22a69b748be598ade4520df0', 'google', 'Verona Musi', 'img/empty.png?a2499e3b0', '2025-10-29', '2026-06-28 19:10:04', '2026-07-02 12:19:00'),
(11482, 553, NULL, 'Клієнт ****6155', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Чудовий адвокатський центр! Вже не раз допомагали мені у вирішенні юридичних питань, у яких інші адвокати не могли знайти рішень. Чудовим є те, що в центрі працюють фахівці в різних сферах права, які між собою взаємодіють і у складних питаннях знаходять чудовий спосіб вирішення проблеми!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-25 00:00:00', NULL, 'c57a68273312ba665fbb96d4fc4718b7d25d9d74', 'google', 'Клієнт ****6155', 'img/empty.png?a2499e3b0', '2025-10-25', '2026-06-28 19:10:05', '2026-07-02 12:19:00'),
(11483, 553, NULL, 'Клієнт ****4429', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Думав, що вже нічого не зроблю по своїй справі, але адвокати центру допомогли виграти і досягти бажаного результату. Безмежно вдячний!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-22 00:00:00', NULL, 'b61451f273f04f15606bd91708c95882d4825b0d', 'google', 'Клієнт ****4429', 'img/empty.png?a2499e3b0', '2025-10-22', '2026-06-28 19:10:05', '2026-07-02 12:19:00'),
(11484, 553, NULL, 'Клієнт ****8183', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Неймовірний колектив, дуже кваліфіковані працівники. Як завжди на вищому рівні!!!!!!!!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-22 00:00:00', NULL, '534794e219d4eb7eb7675291eb1cdda1404175fb', 'google', 'Клієнт ****8183', 'img/empty.png?a2499e3b0', '2025-10-22', '2026-06-28 19:10:05', '2026-07-02 12:19:00'),
(11485, 553, NULL, 'Клієнт ****8098', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Приємно вражений якістю юридичних послуг! Все чітко, доступно, а головне - якісно та результативно. Вкотре впевнився, що кращих у Вінниці немає!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-21 00:00:00', NULL, '3bd7b40594342f15f2b37ff2d0aaf48e400670cf', 'google', 'Клієнт ****8098', 'img/empty.png?a2499e3b0', '2025-10-21', '2026-06-28 19:10:05', '2026-07-02 12:19:00'),
(11486, 553, NULL, 'Клієнт ****6193', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже вдячна адвокатському центру Жанни Грушко за підтримку та компетентність. Тут справді слухають, пояснюють і доводять справу до результату. Раджу всім, хто шукає надійних юристів.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-18 00:00:00', NULL, '58035a13ecb61e968d83acb7983ddde30daa8cf8', 'google', 'Клієнт ****6193', 'img/empty.png?a2499e3b0', '2025-10-18', '2026-06-28 19:10:05', '2026-07-02 12:19:00'),
(11487, 553, NULL, 'Клієнт ****5676', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Однозначно рекомендую, вирішила своє питання за одну консультацію! Все чітко та зрозуміло. Дякую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-18 00:00:00', NULL, '729d395184766d01bbe7f339d1685e02a04aa1a3', 'google', 'Клієнт ****5676', 'img/empty.png?a2499e3b0', '2025-10-18', '2026-06-28 19:10:05', '2026-07-02 12:19:00'),
