(11519, 554, NULL, 'Алексей Листовский', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже грамотні та високо кваліфіковані спеціалісти своєї не легкої справи! Доброзичливі та порядні, що також зовсім не мало означає!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2017-10-21 00:00:00', NULL, '04b581d4da51f660ed330e65a56456204cca0949', 'google', 'Алексей Листовский', 'img/empty.png?a2499e3b0', '2017-10-21', '2026-06-28 19:10:15', '2026-07-02 12:19:07'),
(11520, 554, NULL, 'Василий Мусиенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Кваліфіковані, і головне - порядні спеціалісти своєї справи. Дуже допомогли мені кваліфікованим юридичним супроводом моєї справи в судах, за що я їм дуже вдячний. Рекомендую. Звертайтеся, не пожалкуєте.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2017-10-16 00:00:00', NULL, 'a8baceebb46027a954bf92a93e020931a4674fe4', 'google', 'Василий Мусиенко', 'img/empty.png?a2499e3b0', '2017-10-16', '2026-06-28 19:10:16', '2026-07-02 12:19:07'),
(11521, 554, NULL, 'Kolya Pavelchuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Грамотні і кваліфіковані спеціалісти. Завжди готові відгукнутися і допомогти. Знають тонкощі українського законодавства. Професійно взялися за мою справу, чудово підготувалися, і звісно, перемога була за нами. Дякую вам за допомогу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2017-06-16 00:00:00', NULL, '5799d979b554e9c1ab2de7e341fab11cf4749aa8', 'google', 'Kolya Pavelchuk', 'img/empty.png?a2499e3b0', '2017-06-16', '2026-06-28 19:10:16', '2026-07-02 12:19:07'),
(11522, 555, NULL, 'Mykhailo Kravchuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Уклав договір з малою платою і знайшовся кращий орендар і тільки через суд потрібно було розривати. Михайло Олександрович надав якісні послуги, та знайшов спосіб розірвати той договір та вернути мені землю', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-31 00:00:00', NULL, '99bfb6c8a6e2527f09d2b93539dfc036c9d6e0f5', 'google', 'Mykhailo Kravchuk', 'img/empty.png?a2499e3b0', '2024-10-31', '2026-06-28 19:10:20', '2026-07-02 12:19:17'),
(11523, 555, NULL, 'Сергій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую. Мені тут надали кваліфіковану правову допомогу, вдалось відсудити в держави 200тис.грн.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-01 00:00:00', NULL, '1ad24501bc4320b5d580442b154fc6279ba0a3fd', 'google', 'Сергій', 'img/empty.png?a2499e3b0', '2024-04-01', '2026-06-28 19:10:20', '2026-07-02 12:19:17'),
(11524, 555, NULL, 'Сергій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'мені самому не вдавалось повернути земельну ділянку, невигідно підписав договір оренди. Адвокату приколупатись до якогось юридичного нюансу і через суд мені землю повернули)))', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-05-31 00:00:00', NULL, '7484a6d4e80de4182a8cc8f3c099cf1666648aad', 'google', 'Сергій', 'img/empty.png?a2499e3b0', '2023-05-31', '2026-06-28 19:10:20', '2026-07-02 12:19:17'),
(11525, 555, NULL, 'Іван', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро дякую, адвокату Кравчуку за чудово виконану роботу', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-09-27 00:00:00', NULL, '9607a15cb94306d033d53ab8150ecadc74058c56', 'google', 'Іван', 'img/empty.png?a2499e3b0', '2022-09-27', '2026-06-28 19:10:21', '2026-07-02 12:19:17'),
(11526, 555, NULL, 'Віктор', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Михайло Олександрович допоміг зареєструвати звіт про кінцевого бенефіціара, щиро дякую. Мені сподобалась ціна та швидкість', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-04 00:00:00', NULL, '34e9a191120296a03bd2b3521a9a070fe903155b', 'google', 'Віктор', 'img/empty.png?a2499e3b0', '2021-10-04', '2026-06-28 19:10:21', '2026-07-02 12:19:17'),
(11527, 555, NULL, 'Олена Федорівна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'адвокатам - Кравчуком М.О. були надані послуги професійно. Суд тривав довго, але в кінцевому ми його виграли, стягнули з Пенсійного фонду витрати які я понесла на адвоката. В цілому я задоволена', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-09-10 00:00:00', NULL, '25204edd14c8d5e28e3237f8ded9863b642a5f2b', 'google', 'Олена Федорівна', 'img/empty.png?a2499e3b0', '2021-09-10', '2026-06-28 19:10:21', '2026-07-02 12:19:17'),
(11528, 555, NULL, 'Aleksander', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хорошие специалисты своего дела, рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-03-05 00:00:00', NULL, '9ce11fe8ea84e875d3afab0d5f6a07b61b6cb928', 'google', 'Aleksander', 'img/empty.png?a2499e3b0', '2021-03-05', '2026-06-28 19:10:21', '2026-07-02 12:19:17'),
(11529, 555, NULL, 'Людмила', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'я працювала з Юлією, справжній професіонал, рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-02-19 00:00:00', NULL, 'ff9719fae90107f3a0ff997379ce7812d8287f6b', 'google', 'Людмила', 'img/empty.png?a2499e3b0', '2021-02-19', '2026-06-28 19:10:21', '2026-07-02 12:19:17'),
(11530, 555, NULL, 'Ivan Shemeta', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Cправжні професіонали своєї справи.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-09-25 00:00:00', NULL, '634b74bab8f75031b179cd15f3282721c1451933', 'google', 'Ivan Shemeta', 'img/empty.png?a2499e3b0', '2020-09-25', '2026-06-28 19:10:21', '2026-07-02 12:19:17'),
(11531, 555, NULL, 'Вадим', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'ПФУ зменшело мені пенсію з 90% до 70%. Щиро дякую адвокату за визнання таких дій пенсійного незаконними та зобов\'язання їх повернути мені мій попередній розмір пенсії в 90% та стягнути різницю, яку залишила собі держава', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-09-18 00:00:00', NULL, '339b9eaed981e88673895d0fdf11c728f21a1fc3', 'google', 'Вадим', 'img/empty.png?a2499e3b0', '2020-09-18', '2026-06-28 19:10:21', '2026-07-02 12:19:17'),
(11532, 555, NULL, 'Лідія Іванівна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Попри те, що суд я в своєму районі програла, мені відмовили усі місцеві адвокати - сказавши що справа програшна. Дякую Михайлу Олександровичу, що повірив в мою правоту і переконав обласних суддів. Рішення скасували, справедливість восторожествувала', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-07-27 00:00:00', NULL, '4f658fb380af39269df0611e55e84a48b1fe5ff2', 'google', 'Лідія Іванівна', 'img/empty.png?a2499e3b0', '2020-07-27', '2026-06-28 19:10:22', '2026-07-02 12:19:17'),
(11533, 555, NULL, 'Олег Володимирович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Чи маю я право доступу до публічної інформації? Так. Але якщо запитую про вартість закупленого лікарнею майна - чи можуть вони відповісти, що це мене не стосується? Ми звернулись до суду та визнали протиправною відмову, витребували необхідну інформацію. Вартувало звернення до суду 840грн. (держ.мито), допомога адвоката Кравчука М.О. 4тис. Але судом було присуджено лікарні повернути мені ці кошти - 4840грн. Борітися - поборите.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-07-24 00:00:00', NULL, '96ddb5c755c47deb1c5ff900e83d8040442355e8', 'google', 'Олег Володимирович', 'img/empty.png?a2499e3b0', '2020-07-24', '2026-06-28 19:10:22', '2026-07-02 12:19:17'),
(11534, 555, NULL, 'Вододимир', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Фермер підробив підпис мого померлого батька і орав землю. Платив копійки за землю. Дякую адвокату, що визнав договір недійсним та стягнув із фермера борг. Тепер я можу розпоряджатись своєю землею', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-06-17 00:00:00', NULL, '554189cea349e338086c35111431213f260e652d', 'google', 'Вододимир', 'img/empty.png?a2499e3b0', '2020-06-17', '2026-06-28 19:10:22', '2026-07-02 12:19:17'),
(11535, 555, NULL, 'Михайло', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Фіскали збільшили мені орендну плату в 10разів, бо бачте земельний податок виріс і вони провели нову норматино-грошову оцінку. Щиро дякую адвокату Кравчуку М.О. за оскарження в суді та скасування ППР.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-02-24 00:00:00', NULL, 'a5021e9cfb3b6d1ec0cf4b11bb6139ceb4df5b33', 'google', 'Михайло', 'img/empty.png?a2499e3b0', '2020-02-24', '2026-06-28 19:10:22', '2026-07-02 12:19:17'),
(11536, 555, NULL, 'Олег', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'ПФУ мені було відмовлено у призначені пенсії із зменшенням пенсійного віку . Дякую адвокатам за допомогу та встановлення справедливості через суд.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-02-17 00:00:00', NULL, '1cd3eab4b0d81554f51d4762c85b0b53b3b52c84', 'google', 'Олег', 'img/empty.png?a2499e3b0', '2020-02-17', '2026-06-28 19:10:22', '2026-07-02 12:19:17'),
(11537, 555, NULL, 'Olga', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Протягом трьох років ми судились за спадкове майно після смерті моєї двоюрідної бабці із мєнтом, який вирішив записатись чоловіком самотньої бабці. Адвокатам вдалось знайти архівні записи та довести мою родинність відносин, та викрити усю брехню мєнта який підробив документи. Верховний суд підтримав позицію моїх адвокатів та ми перемогли. Щиро дякую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-01-13 00:00:00', NULL, '27077e9301f3d03d451acfddd39ce0331033cf05', 'google', 'Olga', 'img/empty.png?a2499e3b0', '2020-01-13', '2026-06-28 19:10:22', '2026-07-02 12:19:17'),
(11538, 555, NULL, 'Володя', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хорошие адвокати ,отстояли мою честь и справедливость,компания профи советую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-12-27 00:00:00', NULL, '2c0336361ddf080848f3a1456b7033b9b1b01030', 'google', 'Володя', 'img/empty.png?a2499e3b0', '2019-12-27', '2026-06-28 19:10:22', '2026-07-02 12:19:17'),
(11539, 555, NULL, 'Павло', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звертаюся до Олексія Олексійовича вже не перший рік. Дуже компетентний адвокат. Всім раджу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-12-02 00:00:00', NULL, '9bf04eb0a71444be721c1751238c99a7f645c2c9', 'google', 'Павло', 'img/empty.png?a2499e3b0', '2019-12-02', '2026-06-28 19:10:23', '2026-07-02 12:19:17'),
(11540, 555, NULL, 'Діма', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'У пошуках роботи закордоном я заплатив фірмі за працевлаштування. Але виявилось мене обдурили, а гроші я заплатив не за роботу - а за аналітику. Завдяки адвокату Кравчуку М. \"Якименко та партнери\" договір визнали недійсним та мені повернули гроші. Варто відстоювати свою правоту!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-11-25 00:00:00', NULL, 'ab02b8d335f7b6e0a158d90088661070f76c03e9', 'google', 'Діма', 'img/empty.png?a2499e3b0', '2019-11-25', '2026-06-28 19:10:23', '2026-07-02 12:19:17'),
(11541, 555, NULL, 'Ренат', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійно! Якісно! Оперативно! Рекомендую!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-11-22 00:00:00', NULL, '081a9b34c7377cfeb14ae99caa94261c395c6344', 'google', 'Ренат', 'img/empty.png?a2499e3b0', '2019-11-22', '2026-06-28 19:10:23', '2026-07-02 12:19:17'),
(11542, 555, NULL, 'Вікторія', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мені сподобалося працювати з адвокатами компанії “Якименко та партнери”. Позовна заява складена. Відчувається, що вони – кваліфіковані юристи. Можу сміливо рекомендувати їх своїм знайомим, якщо знадобиться юридична допомога.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-11-18 00:00:00', NULL, '12ffe1569c4b19e71d79d1e696b4483bc21c94d2', 'google', 'Вікторія', 'img/empty.png?a2499e3b0', '2019-11-18', '2026-06-28 19:10:23', '2026-07-02 12:19:17'),
(11543, 555, NULL, 'Людмила', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую за допомогу і професіоналізм на найвищому рівні! Добробуту і процвітання вашій справі!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-11-07 00:00:00', NULL, 'dfccbd0d3be39e93ae72aaae9d50f0206501a87f', 'google', 'Людмила', 'img/empty.png?a2499e3b0', '2019-11-07', '2026-06-28 19:10:23', '2026-07-02 12:19:17'),
(11544, 555, NULL, 'Юлия Шабанова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Велике спасибі за кваліфіковану юридичну допомогу в моєму питанні. Дуже допомогли і своїми консультаціями, за які, до речі, не взяли ні копійки. Особисто для мене досвід роботи з вами став прикладом досвіду роботи зі справжніми профі. Бажаю удачі компанії і її фахівцям!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-11-05 00:00:00', NULL, '5f7a6aafcf7acca6f7284fbc6eb6fda875bd51e4', 'google', 'Юлия Шабанова', 'img/empty.png?a2499e3b0', '2019-11-05', '2026-06-28 19:10:23', '2026-07-02 12:19:17'),
(11545, 555, NULL, 'Вадим Вадимович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'В бізнесі виникає питання щодо надійності контрагента, чи можна поставляти товар з післяплатою щоб тебе не кинули. Адже в судах можна просидіти довго, а фактично тобі уже ні товар, ні гроші не вернуть. Дякуєю, особисто Кравчуку Михайлу за супровід мого бізнесу та убезпечення мене від ризикових операцій. Раджу скористатись послугами цієї фірми.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-10-23 00:00:00', NULL, '9f2eee043cafa294d1b0323e352ac6c27ad200f6', 'google', 'Вадим Вадимович', 'img/empty.png?a2499e3b0', '2019-10-23', '2026-06-28 19:10:23', '2026-07-02 12:19:17'),
(11546, 555, NULL, 'Катя Скрипник', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Успіху Вам у вашій роботі! Ви робите гарну справу ! Щиро дякую за допомогу', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-10-23 00:00:00', NULL, 'b879abc9f07c89593da5702c3778cc46886abd55', 'google', 'Катя Скрипник', 'img/empty.png?a2499e3b0', '2019-10-23', '2026-06-28 19:10:24', '2026-07-02 12:19:17');
