(11574, 556, NULL, 'Виктор Савкин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернувся в адвокатську компанію по своєму питанню. Як завжди професійно і правдиво. Якщо треба хороший адвокат, рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-04 00:00:00', NULL, '3e610a753a438ce17b2583f041886f3290dbda04', 'google', 'Виктор Савкин', 'img/empty.png?a2499e3b0', '2025-10-04', '2026-06-28 19:10:33', '2026-07-02 12:19:25'),
