(11716, 559, NULL, 'Юлия Рубанець', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тетяна Володимирівна майстер своєї справи!!!Допомагає людям вирішити питання швидко,професійно і справедливо!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-10-09 00:00:00', NULL, '757ac081ac53ba08658c274ef453e5605aaad8d0', 'google', 'Юлия Рубанець', 'img/empty.png?a2499e3b0', '2023-10-09', '2026-06-28 19:11:04', '2026-07-02 12:19:46'),
(11717, 559, NULL, 'Наталья Жолонко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тетяна майстер в своїй професії .Роботу виконує професійно,швидко,якісно і що найважливіше завжди ціватися як в подальшому як проходить справа за якою до неї звертаються.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-10-09 00:00:00', NULL, '6f92d669b8cb53cca707a6aa991016cdb401c618', 'google', 'Наталья Жолонко', 'img/empty.png?a2499e3b0', '2023-10-09', '2026-06-28 19:11:04', '2026-07-02 12:19:46'),
(11718, 559, NULL, 'Mariia Hamulinska', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тетяна Володимирівна дуже гарний фахівець. Допомогла розібратися з моїми питаннями найкращим способом.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-10-09 00:00:00', NULL, '83abdf3dbe060b633a41caea9e0b3bc0c9e998c6', 'google', 'Mariia Hamulinska', 'img/empty.png?a2499e3b0', '2023-10-09', '2026-06-28 19:11:05', '2026-07-02 12:19:46'),
(11719, 559, NULL, 'Diana Yurkevich', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тетяна Володимирівна, фахівець який знається у свій роботі. Допоможе, все детально розповість, та підтримує до завершення справи. Рекомендую)', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-10-09 00:00:00', NULL, 'bf1add3ae7382317322c5f30597c195b9ada6a31', 'google', 'Diana Yurkevich', 'img/empty.png?a2499e3b0', '2023-10-09', '2026-06-28 19:11:05', '2026-07-02 12:19:46'),
(11720, 559, NULL, 'Антолій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тетяна Володимирівна, висококваліфікований спеціаліст, допомогла мені швидко та якісно вирішити проблеми з арештом майна, який був накладений ДВС. Також допомогла зберегти мою сім’ю, коли дружина подала на розлучення, Тетяна Володимирівна підготувала заяву для примирення і за цей час, який надав суддя я помирився з дружиною! Дуже вдячний вам за вашу роботу !', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-10-07 00:00:00', NULL, '7b1afc76c9d1b72989e478abafe6d56438f06d31', 'google', 'Антолій', 'img/empty.png?a2499e3b0', '2023-10-07', '2026-06-28 19:11:05', '2026-07-02 12:19:46'),
(11721, 559, NULL, 'Вадим Зінько', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мав справу з Тетяною Володимирівною . Подавав запит по Конвенції про цивільно-правові аспекти міжнародного викрадення дітей . Реально в Тетяни Володимирівної в голові величезний сервер - тільки дай запит . Дякую їй безмежно , наразі з нашим запитом , позовом Мін.Юст. (закордонної країни) подав до суду цієї країни та питання вирішується вже в правовому полі . Впевнений як що прийдеться не дай Бог до міжнародного суду звертатись , то я знаю до якого адвоката проситись. Тетяна Володимирівна , дякую Ви найкращі !', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-08-19 00:00:00', NULL, 'f286087bb459d8c04b926eb2fb954ac58988ef32', 'google', 'Вадим Зінько', 'img/empty.png?a2499e3b0', '2023-08-19', '2026-06-28 19:11:05', '2026-07-02 12:19:46'),
(11722, 559, NULL, 'Віра Панькова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тетяна Володимирівна чудовий спеціаліст 🤗. Дуже відповідально ставиться до своєї справи. Якщо щось не зрозуміло, завжди розскаже, покаже і пояснить простими словами,скаже як правильно вчинити в даному випадку. Я з нею пережила три позови і на далі підтримуємо зв\'язок. Ціна за її послуги -адекватна. Крім цього, вона молода, красива, енергійна дівчина. Всім її раджу. Тетяна Володимирівна, дякую Вам за все 🌹🌹🌹', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-06 00:00:00', NULL, 'e3327ef22a752d83a3914d608be1421c4455d023', 'google', 'Віра Панькова', 'img/empty.png?a2499e3b0', '2023-04-06', '2026-06-28 19:11:05', '2026-07-02 12:19:46'),
(11723, 559, NULL, 'Петро', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'У мене був приємний досвід роботи з цим адвокатом. Вона дуже обізнана та професійна. Допомогла мені з моєю справою, і я був дуже задоволений результатами. Однозначно рекомендую її всім, хто потребує юридичної допомоги', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-02-20 00:00:00', NULL, 'e6a676f2cc7b36fcf8cf5ecb9f4c012fc19a3e11', 'google', 'Петро', 'img/empty.png?a2499e3b0', '2023-02-20', '2026-06-28 19:11:06', '2026-07-02 12:19:46'),
