(11728, 560, NULL, 'Василий Павлюк', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щира вдячність команді юридичного ценру за те, що відстояли моє законне право на пенсію! Особлива подяка пані Світлані за компетентність і оперативність. Ви найкращі!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-06-29 00:00:00', NULL, '1279835f015422b03c142f2128377a05775e5e88', 'google', 'Василий Павлюк', 'img/empty.png?a2499e3b0', '2025-06-29', '2026-06-28 19:11:10', '2026-07-02 12:19:54'),
(11729, 560, NULL, 'Юля Крупка', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже вдячна фаховим юристам центру. Користуюся послугами Подільського юридичного центру багато років. Хочу зазначити, що у моєму випадку немає ні однієї програшної справи. Особлива вдячність пану Оскомі Олександру Миколайович у за підтримку і високий професіоналізм. Дякую. Замазій О.О.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-06-04 00:00:00', NULL, 'b8113e57a9b2856a839cdb20288f14dfac9c4b27', 'google', 'Юля Крупка', 'img/empty.png?a2499e3b0', '2025-06-04', '2026-06-28 19:11:11', '2026-07-02 12:19:54'),
(11730, 560, NULL, 'Джулія', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Подільський юридичний центр\" та Олександр Оскома – справжні професіонали! Зіткнувшись з необхідністю юридичної допомоги, я отримала висококласну консультацію та підтримку. Всі питання вирішуються швидко та ефективно, а обслуговування на найвищому рівні. Щиро рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-03-14 00:00:00', NULL, 'ee49ec5bdaeb5997ae7e11d061e4e9285fd89cc9', 'google', 'Джулія', 'img/empty.png?a2499e3b0', '2025-03-14', '2026-06-28 19:11:11', '2026-07-02 12:19:54'),
(11731, 560, NULL, 'Саня Власенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Чудова організація, рекомендую👍👍👍…', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-02-01 00:00:00', NULL, '5585dc5dcf45f166aa97e35c4390d34e12cc624a', 'google', 'Саня Власенко', 'img/empty.png?a2499e3b0', '2025-02-01', '2026-06-28 19:11:11', '2026-07-02 12:19:54'),
(11732, 560, NULL, 'Nik Gob', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Завдяки Оскомі О.М. та його команді, здійснено повноцінний перегляд моєї справи , щодо виплати моїх пенсійних коштів, в повному обсязі, чим я дуже задоволена. Дякую за ефективно проведену роботу, та рекомендую в подальшому звертатися до Оскоми О.М. Людмила', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-18 00:00:00', NULL, 'c73a8d379e2981e98406a75be00d35edf5379a3c', 'google', 'Nik Gob', 'img/empty.png?a2499e3b0', '2025-01-18', '2026-06-28 19:11:11', '2026-07-02 12:19:54'),
(11733, 560, NULL, 'Иван Иванов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Висловлюю подяку п. Олександру Оскомі за професіоналізм та порядність у своїй роботі! Завжди своєчасно отримував відповіді та роз’яснення від Подільського юридичного центру на свої запитання. Справа про щомісячну доплату у розмірі 2000 грн, передбаченої постановою КМУ №713 від 14.07.2021, завершена за 4 місяці. Слава Подільському юридичному центру, Слава ЗСУ і Слава Україні!!! З повагою, військовий пенсіонер, ветеран військової служби', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-07-19 00:00:00', NULL, '1a03d96042783618d5710d82b084939d77ed519f', 'google', 'Иван Иванов', 'img/empty.png?a2499e3b0', '2023-07-19', '2026-06-28 19:11:11', '2026-07-02 12:19:54'),
(11734, 560, NULL, 'Вячеслав Агеев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Виконали те, що обіцяли ! Дякую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-07-18 00:00:00', NULL, '159ed159597e6089a0809dccaa546a5fff7c7832', 'google', 'Вячеслав Агеев', 'img/empty.png?a2499e3b0', '2023-07-18', '2026-06-28 19:11:11', '2026-07-02 12:19:54'),
(11735, 560, NULL, 'Vladimir Raviolli', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Норм. Культурные, приветливые юристы, чисто, уютно...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-11-18 00:00:00', NULL, '58bce4f90d763bdef59409a630bc222c5a1b2b0f', 'google', 'Vladimir Raviolli', 'img/empty.png?a2499e3b0', '2021-11-18', '2026-06-28 19:11:12', '2026-07-02 12:19:54'),
(11736, 560, NULL, 'Иван Иванов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Висловлюю щиру подяку п. Олександру Оскомі за професіоналізм та порядність у своїй роботі! По всім чотирьом судовим справам стосовно перерахунку моїй пенсії колишнього військовослужбовця судом прийняті рішення на мою користь, в результаті чого пенсія збільшилась на 83% за останні півтора року (якби я не подавав до суду, то збільшення склало би 27% - це надбавка 2000грн. згідно постанови кабміну). Слава військовим адвокатам, Слава Подільському юридичному центру і Слава Україні!!! З повагою, військовий пенсіонер, ветеран військової служби', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-11-09 00:00:00', NULL, 'd55f7e82a1fc8df0fd289d5d23a97417c5e0a0c6', 'google', 'Иван Иванов', 'img/empty.png?a2499e3b0', '2021-11-09', '2026-06-28 19:11:12', '2026-07-02 12:19:54'),
(11737, 560, NULL, 'Михайло', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро вдячний співробітникам центру, особисто Олександру Миколайовичу Оскомі, за якісну консультативну допомогу, професійний юридичний супровід спірних питань та зрозумілу, прозору і доступну економічну політику. Позитивний досвід співпраці протягом трьох років. Рекомендую - Ви тут зустрінете щирих, адекватних і високопрофесійних фахівців з питань юристпруденції, які допоможуть вирішити ваші проблеми у законний спосіб. Ще раз ДЯКУЮ, нехай нам всім щастить.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-13 00:00:00', NULL, '1b9747c61deb4d3e1b91f220bbe8456fb570dc35', 'google', 'Михайло', 'img/empty.png?a2499e3b0', '2021-10-13', '2026-06-28 19:11:12', '2026-07-02 12:19:54'),
(11738, 560, NULL, 'Anastasia Boichuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Працює справжня команда професіоналів, котрі люблять свою роботу! Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-11 00:00:00', NULL, '00e5f902adee0cebbe5e53699788504595992f7c', 'google', 'Anastasia Boichuk', 'img/empty.png?a2499e3b0', '2021-10-11', '2026-06-28 19:11:12', '2026-07-02 12:19:54'),
(11739, 560, NULL, 'Софія', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Супер! працюють дійсно професіонали. Зверталась по досить складній справі, думала. що вирішити її неможливо. Проте, мені допомогли у можливі найкоротші терміни!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-11 00:00:00', NULL, '0237916ac2571840feab84e3461733b81d9a7c3d', 'google', 'Софія', 'img/empty.png?a2499e3b0', '2021-10-11', '2026-06-28 19:11:12', '2026-07-02 12:19:54'),
(11740, 560, NULL, 'Alekandr', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'П‘ять позовів - п‘ять позитивних рішень суду. Своєчасна підготовка документів на високому професійному рівні. Толерантність, доброзичливість членів команди PLC у роботі з клієнтами. Щиро вдячний Оскомі Олександру Миколаєвичу за надану результативну допомогу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-07 00:00:00', NULL, '6819695588e61e1548e36e007f0b4aa9e00a430b', 'google', 'Alekandr', 'img/empty.png?a2499e3b0', '2021-10-07', '2026-06-28 19:11:12', '2026-07-02 12:19:54'),
(11741, 560, NULL, 'Oksana Kotenko', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Супроводжували мене в процесі розірвання шлюбу з іноземцем. Справа була складна, так як я не мала зв\'язку з чоловіком і шлюб було укладено закордоном. Я довго шукала юриста, який би мені допоміг, та більшість відмовлялись, так як справа складна, або за свої послуги називали неймовірні ціни. Подільський юридичний центр я знайшла випадково в інтернеті і відчула, що маю справу з вахівцями. Підтримували мене протягом всього процесу і ось сьогодні я отримала рішення з суду, нарешті шлюб розірвано. Дуже дякую за допомогу!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-08-21 00:00:00', NULL, '4d2a314da4fa1d212beb7b063d932f867c216e08', 'google', 'Oksana Kotenko', 'img/empty.png?a2499e3b0', '2021-08-21', '2026-06-28 19:11:12', '2026-07-02 12:19:54'),
(11742, 560, NULL, 'Sergey Bezumanuy', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Категорически не рекомендую, иски и построении защиты на уровне первого курса университета', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-08-13 00:00:00', NULL, '9df8bc636561ffa5bbe13e2a4fb32ffe0c2a5697', 'google', 'Sergey Bezumanuy', 'img/empty.png?a2499e3b0', '2021-08-13', '2026-06-28 19:11:13', '2026-07-02 12:19:54'),
(11743, 560, NULL, 'Roman Shevchenko', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Кваліфікована допомога! Спасибі Оскомі Олександру Миколайовичу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-05-28 00:00:00', NULL, '20be137ede47e3e24dfdce9e8f98745dabf99672', 'google', 'Roman Shevchenko', 'img/empty.png?a2499e3b0', '2021-05-28', '2026-06-28 19:11:13', '2026-07-02 12:19:54'),
(11744, 560, NULL, 'Олександр Хорошевський', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Компанія надає дуже якісні послуги по перерахунку пенсій військових пенсіонерів навіть за межами Вінниці. Я особисто виграв суди і почав отримувати підвищену пенсію у Львові. Рекомендую скористатися допомогою. Мої четверо колег теж виграли. Дуже вдячний за роботу!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-04-08 00:00:00', NULL, 'baba9d5798ef6ee880b6594d9f951e7e9cb0c042', 'google', 'Олександр Хорошевський', 'img/empty.png?a2499e3b0', '2021-04-08', '2026-06-28 19:11:13', '2026-07-02 12:19:54'),
(11745, 560, NULL, 'Ревізійний Клієнт', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тут Вы можете найти хорошего адвоката по ДТП. Адвокаты работают в Киеве, Виннице. Если Вам нужна защита в уголовном деле по ДТП или защита в суде по делу об административном нарушении (124, 130 КУпАП) - Вам сюда. У них есть подготовка апеляционной жалобы по делу о ДТП, подготовка касационной жалобы. Знаю, что могут подготовить иск на возмещение ущерба. Также широко представлены семейный адвокат (Киев, Винница), налоговый адвокат (Киев, Винница), военный адвокат, адвокат по экстрадициям, обращения в ЕСПЛ. Рекомендую как фирму, которая предоставляет юридические консультации.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-03-22 00:00:00', NULL, '5e3b3e2d255a0c0648654abdccc83d65fdf2bbe6', 'google', 'Ревізійний Клієнт', 'img/empty.png?a2499e3b0', '2020-03-22', '2026-06-28 19:11:13', '2026-07-02 12:19:54'),
(11746, 560, NULL, 'Олег GG8907', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Шукав адвоката для звернення до Європейського суду з прав людини. Тільки в Подільському юридичному центрі знайшов. Адвокат Козачук та Адвокат Оскома кращі в своїй справі!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-02-22 00:00:00', NULL, '4404aefc696c46fbec172cdc468b48f5bc42cc18', 'google', 'Олег GG8907', 'img/empty.png?a2499e3b0', '2020-02-22', '2026-06-28 19:11:13', '2026-07-02 12:19:54'),
(11747, 560, NULL, 'Darya 0987P', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую, якщо у Вас виникли проблеми з отриманням земельних паїв у спадок. За життя мама не встигла оформити держ.акт на землю, а нотаріус відмовила у реєстрації спадку. Швидко вирішили всі питання через суд. Гарні спеціалісти, професіонали найвищого ґатунку!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-10-09 00:00:00', NULL, 'ffa55a14c307ded9a5d62ae25b955e8394535580', 'google', 'Darya 0987P', 'img/empty.png?a2499e3b0', '2019-10-09', '2026-06-28 19:11:13', '2026-07-02 12:19:54'),
(11748, 560, NULL, 'Antin Shevchuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Отримав якісну та дієву правову допомогу! Адвокати Центру допомогли мені виграти спір у суді з податковою щодо боргу на 20 тис. по соц. внеску.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-08-23 00:00:00', NULL, '2412f85a8f9b76cbfb11e148113a6ce4be25cef3', 'google', 'Antin Shevchuk', 'img/empty.png?a2499e3b0', '2019-08-23', '2026-06-28 19:11:13', '2026-07-02 12:19:54'),
(11749, 560, NULL, 'Дмитро Білий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернувся до Подільського юридичного центру з питанням щодо боргу по кредиту, отримав повну та вичерпну інформацію на консультації, вдячний за розуміння та професійний підхід. Окреме дякую за дистанційне ведення справи та постійний зворотній зв\'язок. Рекомендуватиму Вас та за потреби звернусь знову.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-08-10 00:00:00', NULL, 'aa9ab68308d4ba720195c13b5c0cc46b6bed82a1', 'google', 'Дмитро Білий', 'img/empty.png?a2499e3b0', '2019-08-10', '2026-06-28 19:11:14', '2026-07-02 12:19:54'),
(11750, 560, NULL, 'Miroslava F375322', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Це єдине місце де мені допомогли. Не могла оформити будинок, що залишився мені у спадок. Мене швидко зорієнтували, надали вичерпну інструкцію, підготували всі необхідні документи. І от вже як місяць, я законний власник всього спадкового майна.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-07-14 00:00:00', NULL, 'e80cb2ed3c54c04b587fdef77a70b1613473cf63', 'google', 'Miroslava F375322', 'img/empty.png?a2499e3b0', '2019-07-14', '2026-06-28 19:11:14', '2026-07-02 12:19:54'),
(11751, 560, NULL, 'Ганна Харченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Чудова юридична фірма! Вже друге звертаюсь за допомогою до сімейних адвокатів центру. Цього разу вирішили з чоловіком укласти шлюбний договір. Швидко підготували проект з урахуванням всіх наших побажань. Крім того, пояснили всі правові наслідки, які можуть виникнути під час укладання та виконання договору. Надалі буду звертатись лише до них!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-06-25 00:00:00', NULL, 'd5e54d968a33802b33e6dff0c0ac4bb72594660c', 'google', 'Ганна Харченко', 'img/empty.png?a2499e3b0', '2019-06-25', '2026-06-28 19:11:14', '2026-07-02 12:19:54'),
(11752, 560, NULL, 'Інна Комарчук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже вчасно допомогли з вирішенням питання в суді. Спасибі за гарну роботу. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-06-01 00:00:00', NULL, '3dd190d26231c5d94e7df4809535ca22e9235e0b', 'google', 'Інна Комарчук', 'img/empty.png?a2499e3b0', '2019-06-01', '2026-06-28 19:11:14', '2026-07-02 12:19:54'),
(11753, 560, NULL, 'Edward Tompson', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Великі адвокати! Швидкий, професійний і чуйний. Якщо мені коли-небудь потрібен адвокат в Україні, я буду телефонувати PLC.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-05-25 00:00:00', NULL, '072aabdb788244ff0e2468a8f95ce9d8149bd631', 'google', 'Edward Tompson', 'img/empty.png?a2499e3b0', '2019-05-25', '2026-06-28 19:11:14', '2026-07-02 12:19:54'),
(11754, 560, NULL, 'Cris Longfred', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Це був мій перший випадок, коли я зіткнувся з проблемами в Україні. На щастя, я зустрівся з цими висококваліфікованими українськими юристами. Захисник Михайло Козачук зробив величезну роботу у справі про екстрадицію мого друга. У кримінальних справах, я настійно рекомендую адвокатську фірму з упевненими адвокатами.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-05-25 00:00:00', NULL, '72ddbb266fe76b9ea7aa2e543ebd9ea3be6f0bdc', 'google', 'Cris Longfred', 'img/empty.png?a2499e3b0', '2019-05-25', '2026-06-28 19:11:14', '2026-07-02 12:19:54'),
(11755, 560, NULL, 'Влада 00893', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мені відмовили у видачі довгострокової візи, оскільки, нібито, мене внесли у список осіб, яким заборонений в\'їзд до країни. Юристи центру допомогли скласти запит до уповноважених структур, щоб вирішити це питання. Все доступно пояснили. Дуже приємно, що існують такі адвокати, віддані своїй справі!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-05-18 00:00:00', NULL, '98bbcca676b0532dfd30468c508ab922fb896df9', 'google', 'Влада 00893', 'img/empty.png?a2499e3b0', '2019-05-18', '2026-06-28 19:11:15', '2026-07-02 12:19:54'),
(11756, 560, NULL, 'Тимур Шевченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Надійні адвокати. Не дають марних обіцянок! Представляли інтереси моєї компанії у суді у спорі з контрагентом. Виграли мою справу. Все чудово!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-05-18 00:00:00', NULL, 'd4c1b5ebe6099a56ba1b084b347bb3a23436c956', 'google', 'Тимур Шевченко', 'img/empty.png?a2499e3b0', '2019-05-18', '2026-06-28 19:11:15', '2026-07-02 12:19:54'),
(11757, 560, NULL, 'Сімейний Адвокат', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталася у Вінниці до адвоката по аліментам. До мене колишній чоловік подав позов про зменшення аліментів. Сімейні адвокати центру навпаки подали зустрічний позов про звільненні розміру аліментів. Суд задоволив позов саме адвокатів цього центру. Зараз вирішуємо справу про поділ майна та можливо позбавлення батьківських прав. Приємно спілкуватися з грамотними людьми.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-05-08 00:00:00', NULL, '494f41847a4ff0dc618041e90074bfa19f879043', 'google', 'Сімейний Адвокат', 'img/empty.png?a2499e3b0', '2019-05-08', '2026-06-28 19:11:15', '2026-07-02 12:19:54'),
(11758, 560, NULL, 'Аster 2010', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Допомогли мені в оформленні мого бізнесу. Відтепер не укладаю жодного договору без консультування фахівців Подільського юридичного центру. Шукаєте надійних юристів, які 24/7 можуть Вам допомогти - звертайтесь до них. 100% не пошкодуєте!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-04-08 00:00:00', NULL, '99d06502e76d3199c407bb7a292fab0fb43e9e71', 'google', 'Аster 2010', 'img/empty.png?a2499e3b0', '2019-04-08', '2026-06-28 19:11:15', '2026-07-02 12:19:54'),
(11759, 560, NULL, 'Лена Петровська', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Саме тут, працюють дійсно висококваліфіковані спеціалісти, які допомогли у справі яка здавалася безнадійною.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2019-03-30 00:00:00', NULL, '5c3bf54cb321a65ec908c975e42a96b17520c789', 'google', 'Лена Петровська', 'img/empty.png?a2499e3b0', '2019-03-30', '2026-06-28 19:11:15', '2026-07-02 12:19:54'),
