(11791, 561, NULL, 'Иван Борисович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Чудовий та добросовісний спеціаліст, а головне - дуже хороша людина)', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-19 00:00:00', NULL, '3fa0795b6902bd87571671988afe9abc11a111d7', 'google', 'Иван Борисович', 'img/empty.png?a2499e3b0', '2024-03-19', '2026-06-28 19:11:24', '2026-07-02 12:19:59'),
(11792, 561, NULL, 'Кристина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Раджу Альону Сергіївну, як чудового спеціаліста! Особисто мені вона допомагала і підтримувала у справі нерухомості; чітко все пояснювала на усіх етапах справи, знаходила усі потрібні підтверджуючі документи. Дуже порядна людина та досвідчений адвокат!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-19 00:00:00', NULL, '06ce30f8eb08d66b4b5f6a6ae72461012774e8f8', 'google', 'Кристина', 'img/empty.png?a2499e3b0', '2024-03-19', '2026-06-28 19:11:24', '2026-07-02 12:19:59'),
(11793, 561, NULL, 'Наталья Ковалинская', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Особисто мені Альона Сергіївна надає моральну підтримку,відчуття того,що я не залишилася в біді насамоті.Вона дійсно прагне допомогти в дуже складній для мене ситуації.Уважно ставиться до розгляду та підготовки матеріалу.Кваліфіковано представляє мої інтереси на судових засіданнях.Дуже вдячна Альоні Сергіївні за людяність та високий професіоналізм.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-17 00:00:00', NULL, 'de698fae0c2ff0283429927c2cddbc3eee85abd6', 'google', 'Наталья Ковалинская', 'img/empty.png?a2499e3b0', '2024-03-17', '2026-06-28 19:11:24', '2026-07-02 12:19:59'),
(11794, 561, NULL, 'Інна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити подяку Альоні Сергіївні .Завжди дає зрозумілі консультації, швидко і якісно виконує питання. Рекомендую, як професіонала своєї справи та гарну людину.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-16 00:00:00', NULL, '77090730ffc7688c0114ccab681c488f435a86ce', 'google', 'Інна', 'img/empty.png?a2499e3b0', '2024-03-16', '2026-06-28 19:11:24', '2026-07-02 12:19:59'),
(11795, 561, NULL, 'Світлана', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Альона Сергіївна чудовий фахівець і приємна людина. Дуже уважне ставлення до людей та їхніх проблем. Якісні консультації та виважений підхід до вирішення питань. Допомогла швидко вирішити мою справу. Рекомендую ❤️', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-16 00:00:00', NULL, 'db878e97b0c2d6282eee3863629fc3b7651e19bd', 'google', 'Світлана', 'img/empty.png?a2499e3b0', '2024-03-16', '2026-06-28 19:11:24', '2026-07-02 12:19:59'),
(11796, 561, NULL, 'Alex Surayev', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Вражає поєднання швидкості, оперативності, компетентності і одночасно творче ставлення, вміння знайти нестандартне рішення, яке відповідає вимогам нашого суперечливого законодавства і потребам клієнта.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-15 00:00:00', NULL, 'c2b16d1c5c6daad1a372960d7da8de5492700266', 'google', 'Alex Surayev', 'img/empty.png?a2499e3b0', '2024-03-15', '2026-06-28 19:11:24', '2026-07-02 12:19:59'),
(11797, 561, NULL, 'Олександра', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Альона Сергіївна легко й доступно пояснила складні юридичні питання, з якими я звернулася, була уважна до моїх потреб. Завдяки компетентній роботі Альони Сергіївни вдалося вирішити питання.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-15 00:00:00', NULL, '2c3270bd1fd5bffaa84323654dcf841d5fdb9884', 'google', 'Олександра', 'img/empty.png?a2499e3b0', '2024-03-15', '2026-06-28 19:11:24', '2026-07-02 12:19:59'),
(11798, 561, NULL, 'Mariia Dovbenko', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професіонал своєї справи та порядна людина. Отримали грамотний супровід у дуже складній ситуації та вирішення ряду спорів на нашу користь.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-15 00:00:00', NULL, 'bc883858a96a6e78ca386c41e25e8213d2b881ed', 'google', 'Mariia Dovbenko', 'img/empty.png?a2499e3b0', '2024-03-15', '2026-06-28 19:11:25', '2026-07-02 12:19:59'),
(11799, 561, NULL, 'Олег', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Був радий співпрацювати з Альоною. Надала мені консультацію з вичерпною інформацією та допомогла вирішити питання, які мене турбували. Буду радий знову звернутися по допомогу. Швидко та якісно.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-15 00:00:00', NULL, 'd9ccc6ca9f3b7ff42f9a775bac1ea46ec233f9eb', 'google', 'Олег', 'img/empty.png?a2499e3b0', '2024-03-15', '2026-06-28 19:11:25', '2026-07-02 12:19:59'),
(11800, 561, NULL, 'Руслан', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже професійний адвокат, майстер своєї справи. Звиртався за допомогою, швидко, ефективно та якісно вирішила питання. Рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-15 00:00:00', NULL, 'aa67e5d02fc8f2274e7a3b8a490af8a9c57b9c7a', 'google', 'Руслан', 'img/empty.png?a2499e3b0', '2024-03-15', '2026-06-28 19:11:25', '2026-07-02 12:19:59'),
