(11822, 562, NULL, 'Клієнт ****1621', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую. Молодці. Особлива подяка за роботу і за компетентність Сергію Чорному і Бурковській Олександрі', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-04 00:00:00', NULL, 'c29322e42eb9823d4749542ef5cb3c4c937333a8', 'google', 'Клієнт ****1621', 'img/empty.png?a2499e3b0', '2024-10-04', '2026-06-28 19:11:32', '2026-07-02 12:20:08'),
(11823, 562, NULL, 'Валентин Сліпак', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Попрацювавши з юристами та менеджерами АО \"Макс Гарант\" можу впевнено сказати, що залишився задоволеним! Компетентні юристи, які уважно вислухають питання і по полицях його розкладуть, відповідаючи на всі питання, які б не виникли в клієнта. Окремо хочу виділити адвоката Чорного Сергія, який взявся за мою справу не дивлячись на її важкість та довів її до кінця та його помічницю Олександру Бурковську, яка допомагала йому на кожному етапі роботи. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-04 00:00:00', NULL, 'b4871a8475822c8959865aadebcaf717b0824995', 'google', 'Валентин Сліпак', 'img/empty.png?a2499e3b0', '2024-10-04', '2026-06-28 19:11:32', '2026-07-02 12:20:08'),
(11824, 562, NULL, 'Клієнт ****4073', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Роботою Адвокатського об\'єднання задоволений , все швидко та професійно виконали. Працював з юристом Альоною Григорівною, дуже професійний юрист, завжди була на зв\'язку та відповідала на усі питання. Відсудили мені більше 50 тисяч гривень.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-04 00:00:00', NULL, 'bac430d89f3824bc6f78e4f17a2bb47253f6b14b', 'google', 'Клієнт ****4073', 'img/empty.png?a2499e3b0', '2024-10-04', '2026-06-28 19:11:32', '2026-07-02 12:20:08'),
(11825, 562, NULL, 'Клієнт ****4073', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже професійні Юристи. Консультацією задоволений ,відповіли на усі питання.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-04 00:00:00', NULL, 'a35c277d7fc12f2d2246c5462b0a8e850165eb8a', 'google', 'Клієнт ****4073', 'img/empty.png?a2499e3b0', '2024-10-04', '2026-06-28 19:11:32', '2026-07-02 12:20:08'),
(11826, 562, NULL, 'Клієнт ****3770', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую пані Аліні за ведення моєї справи по розлученню. Дуже приємно спілкуватися, зрозумілі консультації та швидке вирішення мого питання, незважаючи на складнощі, які виникали.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-04 00:00:00', NULL, 'ee3241f10ca51bd92609e1e16d14e5d963dc47d3', 'google', 'Клієнт ****3770', 'img/empty.png?a2499e3b0', '2024-10-04', '2026-06-28 19:11:33', '2026-07-02 12:20:08'),
(11827, 562, NULL, 'Клієнт ****5592', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'все зробили як треба, пенсія приходить більша на 3200 грн - це перший перерахунок . і плюс 2000 грн другий суд... пенсія збільшилася на 5200 грн. За що дякую дуже', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-26 00:00:00', NULL, '99b547ad78b2c134f4bd78a330d07ba0533f319c', 'google', 'Клієнт ****5592', 'img/empty.png?a2499e3b0', '2024-09-26', '2026-06-28 19:11:33', '2026-07-02 12:20:08'),
(11828, 562, NULL, 'Клієнт ****5592', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Співпрацюю з АО МаксГарант з 2022 року. Нарікань немає, все перерахував і вже втретє перераховую. Відповідають на дзвінки , пояснюють все і скидають документи по справі на вайбер... Можете не боятися і користуватися послугами цієї фірми !', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-26 00:00:00', NULL, 'e2bb8058748a5dff4fbece2b4858f9db2c7914c9', 'google', 'Клієнт ****5592', 'img/empty.png?a2499e3b0', '2024-09-26', '2026-06-28 19:11:33', '2026-07-02 12:20:08'),
