(11831, 562, NULL, 'Клієнт ****3110', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Якісно та швидко допомогли у вирішенні усіх питань! Приємно вразила ціна за надані послуги!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '0f8d8b50a621ae2725ca212785c5f5b437fb89d3', 'google', 'Клієнт ****3110', 'img/empty.png?a2499e3b0', '2024-09-25', '2026-06-28 19:11:33', '2026-07-02 12:20:08'),
(11832, 562, NULL, 'Клієнт ****0764', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професіонали своєї справи, найкращі спеціалісти, надали допомогу швидко, якісно і ефективно! Дуже рекомендую усім', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '01e68f4ff029e2abb646c9897dfbbf1cd89ccd17', 'google', 'Клієнт ****0764', 'img/empty.png?a2499e3b0', '2024-09-25', '2026-06-28 19:11:33', '2026-07-02 12:20:08'),
(11833, 562, NULL, 'Клієнт ****9221', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Швидко та якісно виконали роботу. Приємний колектив, з радістю надали професійну консультацію та допомогли у вирішенні питань.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '92b1778cceab14f7c6e0f2568eb24b6368015e93', 'google', 'Клієнт ****9221', 'img/empty.png?a2499e3b0', '2024-09-25', '2026-06-28 19:11:34', '2026-07-02 12:20:08'),
(11834, 562, NULL, 'Клієнт ****7790', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дійсно професіонали своєї справи ! Виконали роботу у зазначені терміни, дуже задоволена роботою!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '3d2a09b9f737c2c8f28b4e2bd76e334704373092', 'google', 'Клієнт ****7790', 'img/empty.png?a2499e3b0', '2024-09-25', '2026-06-28 19:11:34', '2026-07-02 12:20:08'),
(11835, 562, NULL, 'Світлана Гаджук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Юристи компанії не тільки надавали чіткі рекомендації, але й допомогли зрозуміти всі нюанси мого випадку. Їхня команда проявила високу експертність та готовність вирішувати складні питання, що в результаті призвело до успішного завершення справи. Я з упевненістю рекомендую цю компанію всім, хто шукає надійного правового партнера!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '6b2837e4810c1234d0b3dae302e3b039ea74962e', 'google', 'Світлана Гаджук', 'img/empty.png?a2499e3b0', '2024-09-25', '2026-06-28 19:11:34', '2026-07-02 12:20:08'),
(11836, 562, NULL, 'Анастасия Авраменко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Компанію порадили знайомі , дуже вдячна Максиму Станіславовичу за виграну справу по військовій пенсії , збільшилась на 7 423 грн , вдячні що завжди були на звʼязку , працюємо далі по відсудженю добавки 2000 ,дуже вам вдячні !!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '6f1397cc6ac33904b0459c262fa28858432df515', 'google', 'Анастасия Авраменко', 'img/empty.png?a2499e3b0', '2024-09-25', '2026-06-28 19:11:34', '2026-07-02 12:20:08'),
(11837, 562, NULL, 'Клієнт ****7793', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Висловлюю щиру подяку адвокатському об\'єднанню за професіоналізм та ефективну правову допомогу. Команда була уважною до деталей, завжди на зв\'язку та чітко пояснювала всі нюанси справи. Завдяки їхній підтримці вдалося досягти позитивного результату. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '38bd46a21178b698fbffc1f01f836eb2ce29a4d3', 'google', 'Клієнт ****7793', 'img/empty.png?a2499e3b0', '2024-09-25', '2026-06-28 19:11:34', '2026-07-02 12:20:08'),
(11838, 562, NULL, 'Oleksandr Shkut', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже дякую АО \"МаксГарант\" у позитивному вирiшеннi питань , по яким я звертався ! Особливо дякую Вiкторii П. , представнику цiєī адвокатськоī компанiī , яка являлася моīм куратором по справах юридичних !!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-08 00:00:00', NULL, '4760280d52458316aecbfab59662db64fdf55c30', 'google', 'Oleksandr Shkut', 'img/empty.png?a2499e3b0', '2024-09-08', '2026-06-28 19:11:34', '2026-07-02 12:20:08'),
(11839, 562, NULL, 'Валентин', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Шарашкина контора. За два роки документи ще не дійшли до суду. Шкода і одиницю поставити. Шкода 3,5 тис., шкода потраченого часу, шкода нервів, здоровʼя. Аферисти!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-07-29 00:00:00', NULL, '3982698ca4bb25e6e18d67867d4ad4c05035211d', 'google', 'Валентин', 'img/empty.png?a2499e3b0', '2024-07-29', '2026-06-28 19:11:34', '2026-07-02 12:20:08'),
(11840, 562, NULL, 'Olenka Kravchuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Роботою задоволена! Звернулась за допомогою з перерахунком пенсії для мого діда. До перерахунку пенсія була 6300,20 грн, після першого перерахунку пенсія стала 11134,40 грн, після того допомогли повернути щомісячну надбавку 2000 грн. Дуже Вам дякую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-05-29 00:00:00', NULL, '5c649abc7ae3a6ce0974534424873a0ff90c4b71', 'google', 'Olenka Kravchuk', 'img/empty.png?a2499e3b0', '2024-05-29', '2026-06-28 19:11:35', '2026-07-02 12:20:08'),
(11841, 562, NULL, 'Nastia83 Olxovic', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Доброго дня. Можливо моє повідомлення прочитає хтось, хто може допомогти в моїй справі. Мене цікавить пані Анастасія Підлужняк, яка допомагала в моїй справі, та з лютого місяця не виходить на зв\'язок. До кого ще можна звернутись? Буду вдячна за відповідь.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-29 00:00:00', NULL, '62157c4eb61541f6d14460709ca28b6af0d662e5', 'google', 'Nastia83 Olxovic', 'img/empty.png?a2499e3b0', '2024-04-29', '2026-06-28 19:11:35', '2026-07-02 12:20:08'),
(11842, 562, NULL, 'Елена Шумило', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Тільки найкращі враження від роботи співробітників «Макс Гарант»! Чітко, професійно та все під контролем було у вирішенні проблеми з перерахунком пенсії. Пенсія перерахована та отримую вже оновлену! Рекомендую цю адвокатську контору!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-03-06 00:00:00', NULL, '645db7b74690c1ad6b267995754a47bd2f21e835', 'google', 'Елена Шумило', 'img/empty.png?a2499e3b0', '2024-03-06', '2026-06-28 19:11:35', '2026-07-02 12:20:08'),
(11843, 562, NULL, 'Елена Шумило', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Только самые хорошие впечатления от работы сотрудников «Макс Гарант»!!! Четко, профессионально и всё под контролем было в решении проблемы с перерасчетом пенсии. Пенсия пересчитана и получаю уже обновленную! Рекомендую эту адвокатскую контору!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-29 00:00:00', NULL, '7b30bfd346cb04d17afc6af91da7a87de34a45e6', 'google', 'Елена Шумило', 'img/empty.png?a2499e3b0', '2024-02-29', '2026-06-28 19:11:35', '2026-07-02 12:20:08'),
(11844, 562, NULL, 'Liliia Korolova', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Місяць немає жодного зв\'язку. Чекаю на документи. Що сталось? Ви не працюєте?', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-29 00:00:00', NULL, '2c7d4c0e59b8af0f4fdf5311144b62a5a37ad46d', 'google', 'Liliia Korolova', 'img/empty.png?a2499e3b0', '2024-01-29', '2026-06-28 19:11:35', '2026-07-02 12:20:08'),
(11845, 562, NULL, 'Сильченкова Лидия', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Відмінна адвокатська компанія! Онлайн документи швидко, все чесно!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-11-06 00:00:00', NULL, 'f9147ce7c4b6557a990c64e97736811ebc91ef57', 'google', 'Сильченкова Лидия', 'img/empty.png?a2499e3b0', '2023-11-06', '2026-06-28 19:11:35', '2026-07-02 12:20:08'),
(11846, 562, NULL, 'Сильченкова Лидия', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Отличная адвокатская компания!!! Онлайн документы быстро,все честно!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-10-29 00:00:00', NULL, '308adf96ab4a9739667f431dd40150fa2705d60f', 'google', 'Сильченкова Лидия', 'img/empty.png?a2499e3b0', '2023-10-29', '2026-06-28 19:11:35', '2026-07-02 12:20:08'),
(11847, 563, NULL, 'Софія', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрібно було терміново оскаржити податкове повідомлення-рішення — строки піджимали. Адвокат за день зібрав позицію, підготував скаргу й чітко відпрацював на засіданні. Рішення скасували, я зекономила і час, і гроші. Дуже професійно, без зайвих обіцянок.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-30 00:00:00', NULL, '39f75e5dc6cc5f100a3ca2f27747200b251b82ab', 'google', 'Софія', 'img/empty.png?a2499e3b0', '2025-07-30', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11848, 563, NULL, 'Mobistyle14.09', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Що мені найбільше сподобалося — це чесність. Без прикрас сказали, що справа непроста, але є шанси. І справді, все обернули на мою користь. У процесі завжди тримали в курсі, відповідали на повідомлення навіть ввечері. Такого сервісу в адвокатурі ще не бачив.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, '0866c574d91c4d3529136b6d8fdbb48a6563bc10', 'google', 'Mobistyle14.09', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11849, 563, NULL, 'Владислав Борисенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Не розумію, звідки беруться негативні коментарі. Можливо, хтось просто не отримав бажаного результату і звинувачує всіх навколо. Моя справа тягнулась майже рік, і саме Роман Люлик взявся за неї тоді, коли інші вже відмовлялись. Все закінчилось позитивно для мене. Пояснював кожен крок, завжди був на зв’язку. Людина на своєму місці.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, 'bc30d798d3246972f1a1627a662751347bcd8a06', 'google', 'Владислав Борисенко', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11850, 563, NULL, 'Vika Honcarova', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже грамотний підхід і чітка стратегія дій. Я розгубилася в ситуації, але мені все пояснили простою мовою, з прикладами. Після цього стало зрозуміло, як буде проходити процес і на що варто розраховувати. Виграли справу, як і обіцяли. Все пройшло гідно.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, 'a10658b67ebf815527c6549e21b25ff674b15bb1', 'google', 'Vika Honcarova', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11851, 563, NULL, 'Валерія Василенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую за швидку та ефективну допомогу. Питання з нерухомістю, здавалося, буде тягнутися вічність, але юрист усе вирішив за кілька тижнів. Був постійний контакт, інформували про кожен крок. Приємно мати справу з людьми, які знаються на своєму ділі.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, 'ae654122ae579c4479ab6b948c4e7017fc63183e', 'google', 'Валерія Василенко', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11852, 563, NULL, 'Kristina Maruk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталася зі складною сімейною справою, вже не вірила, що щось можна вирішити. Але після консультації зрозуміла — я в надійних руках. Все чітко, спокійно пояснили, документи підготували швидко, і вже за місяць питання було закрите. Дуже вдячна за професіоналізм і ставлення.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, 'a9f794ec66118fc120df81604562fab62179cdf0', 'google', 'Kristina Maruk', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11853, 563, NULL, 'Дар\'я Бондаренко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась із сімейного питання, дуже хвилювалась, бо не знала, з чого почати. Від першої консультації стало зрозуміло, що людина дійсно фахівець. Все пояснив по суті, без води, запропонував кілька варіантів дій, і вже за два тижні питання було вирішено. Дуже вдячна за підтримку й швидку реакцію. Рада, що обрала саме цього адвоката.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, 'c95036f55cddfa1169f2c529e35822ec3a782e66', 'google', 'Дар\'я Бондаренко', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11854, 563, NULL, 'Sasisca Doma', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Побачив тут негативні коментарі, але в мене був абсолютно протилежний досвід. Враження, що частина тих відгуків — просто замовні. У моєму випадку питання вирішувалось терміново — потрібна була юридична допомога в господарській справі. Реакція була швидка, консультація — чітка й аргументована, у суді все пройшло так, як і планували. Я був приємно здивований рівнем підготовки. Професійно і з повагою до клієнта.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, '99b2ae2d4d90c3615bda9f8c78610692a6d04e90', 'google', 'Sasisca Doma', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:39', '2026-07-02 12:20:14'),
(11855, 563, NULL, 'Диана -', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталася сюди зі справою, яка вже, чесно кажучи, здавалася мені безнадійною — до цього консультувалась в інших місцях, де тільки заплутали ще більше. Але саме тут нарешті отримала чітку відповідь і реальну допомогу. Все пояснили простою мовою, підготували документи швидко, тримали мене в курсі кожного етапу. Справу вирішили на мою користь, і без затягувань. Видно, що людина на своєму місці. Дякую за професіоналізм і людське ставлення!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, 'a7b18923757ed32b6f4dae0d0976c3eb563eb11c', 'google', 'Диана -', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:40', '2026-07-02 12:20:14'),
(11856, 563, NULL, 'Віталій Жилкін', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Після кількох невдалих спроб вирішити свою справу з іншим юристом, вирішив звернутися до Романа Люлика за рекомендацією. І чесно — не пошкодував. Людина чітко пояснила, що реально можна зробити, а що — просто затягування часу. Буквально за пару тижнів усе зрушило з місця. Без зайвих обіцянок, але з дією. До цього читав коментарі — деякі явно написані на замовлення, і тому мав сумніви, але тепер можу з впевненістю сказати: працює чітко, грамотно і без “води”. Рекомендую, як фахівця.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-23 00:00:00', NULL, 'a8b47315d736827e0a937cd92f92def8337d4565', 'google', 'Віталій Жилкін', 'img/empty.png?a2499e3b0', '2025-07-23', '2026-06-28 19:11:40', '2026-07-02 12:20:14'),
