(11881, 565, NULL, 'Andrey Wayfarer', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Чудовий фахівець, людина знає свою справу. Завдяки його професійному підходу до справи виграв справу в суді. Я задоволений. Всім рекомендую)', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-10-09 00:00:00', NULL, '33765efac32f7df0c6838528d490421c01fae2c5', 'google', 'Andrey Wayfarer', 'img/empty.png?a2499e3b0', '2022-10-09', '2026-06-28 19:11:49', '2026-07-02 12:20:22'),
(11882, 565, NULL, 'Лёша Мамчур', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Лучший юрист. После того, как столкнулся с проблемой все юристы, которым звонил, предлагали абстрактные действия, садились на ушли и рассказали насколько непростое дело. Максим сразу же дал рекомендации к действиям, рассказал про конкретные шаги как нужно действовать и выиграл дело! Твердая пятёрка. Рекомендую всем, кто оказался в непростой ситуации.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-11-15 00:00:00', NULL, '3818a3011da864e8c8c635f4d4ca7e40c5446759', 'google', 'Лёша Мамчур', 'img/empty.png?a2499e3b0', '2021-11-15', '2026-06-28 19:11:49', '2026-07-02 12:20:22'),
(11883, 565, NULL, 'Николай Казаков', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую! Професіонал, до роботи ставиться відповідально, ціна помірна, постійно на зв\'язку.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-07-02 00:00:00', NULL, '1b24666860974a51ba39b5684cb21099fd1b31af', 'google', 'Николай Казаков', 'img/empty.png?a2499e3b0', '2021-07-02', '2026-06-28 19:11:49', '2026-07-02 12:20:22'),
(11884, 565, NULL, 'Muhammed', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Great Lawyer. A person you could trust. I’m glad that I found Maxim. He is genuine and will help you win. He kept his word in my case and helped me solve my problem.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-07-01 00:00:00', NULL, 'f1001eb1e88cd18f3d30013551c699837190fdd4', 'google', 'Muhammed', 'img/empty.png?a2499e3b0', '2021-07-01', '2026-06-28 19:11:49', '2026-07-02 12:20:22'),
(11885, 565, NULL, 'Юлия', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Грамотный, профессиональный адвокат. Очень порядочный, чесный человек. Оказал мне правовую помощь оперативно. Рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-04-12 00:00:00', NULL, '0d8c5d4df2e908d01f368db6e5319cf9c2c90ec1', 'google', 'Юлия', 'img/empty.png?a2499e3b0', '2021-04-12', '2026-06-28 19:11:49', '2026-07-02 12:20:22'),
(11886, 565, NULL, 'Олександр', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Гарна та розумна людина. Допоміг виграти суд за 130 ст. Всім раджу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-03-31 00:00:00', NULL, '2194fe3dc89f11d097360d63cfd56086687cf3a8', 'google', 'Олександр', 'img/empty.png?a2499e3b0', '2021-03-31', '2026-06-28 19:11:49', '2026-07-02 12:20:22'),
(11887, 565, NULL, 'Сергій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Прекрасный адвокат, тот человек который подбодрит вас и поддержит, даёт вам надежду и потом оправдывает свои слова делом. Профессионал в своей сфере. Выиграли 2 дела 130 и 369... индивидуальный и не всегда стандартный подход к делам. Даже в ситуации в которой кажется нету выхода Максим Олегович нашел его... Максис вам огромная благодарность ... Рекомендую всем...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-03-26 00:00:00', NULL, 'ea0a37c748e26e4a77cd7009716bd0787b7b7238', 'google', 'Сергій', 'img/empty.png?a2499e3b0', '2021-03-26', '2026-06-28 19:11:49', '2026-07-02 12:20:22'),
(11888, 565, NULL, 'Эдуард', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую всім!!! Прекрасна людина, професіонал своєї справи! З його допомогою виграли 2 справи. Тож якщо вам потрібні послуги адвоката звертайтесь до Максима Олексійовича.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-03-21 00:00:00', NULL, '696b0d0270b35d36d866cec9b58af5649e19e448', 'google', 'Эдуард', 'img/empty.png?a2499e3b0', '2021-03-21', '2026-06-28 19:11:50', '2026-07-02 12:20:22'),
(11889, 565, NULL, 'Татьяна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Примерно 4 года назад, мне подруга посоветовала Быстрицкого. Я не пожалела ни капельки. Он действительно хороший адвокат.Знает своё дело на все 💯. В то время когда у меня опускались руки от аферистов, и сама ничего я не могла добиться. Он помог мне. Я очень благодарна ему за это и до сих пор!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-02-20 00:00:00', NULL, 'ab4d366d91deb6cef5b6e756bb7e0d54a0041b94', 'google', 'Татьяна', 'img/empty.png?a2499e3b0', '2021-02-20', '2026-06-28 19:11:50', '2026-07-02 12:20:22'),
(11890, 565, NULL, 'Артём Фёдорович Сычёв', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую всім кому потрібна допомога адвоката який знає свою справу, дуже професійно робе свою роботу....', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-12-30 00:00:00', NULL, '41daf2f8b1945c03328ec7565a45295f8346dfe8', 'google', 'Артём Фёдорович Сычёв', 'img/empty.png?a2499e3b0', '2020-12-30', '2026-06-28 19:11:50', '2026-07-02 12:20:22'),
(11891, 565, NULL, 'Світлана', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталися до Максима Олексійовича за допомогою. Дуже вдячні йому за людяність і професіоналізм. Рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-12-25 00:00:00', NULL, '9c9d0a305fae04fcd7db338353944540f0717378', 'google', 'Світлана', 'img/empty.png?a2499e3b0', '2020-12-25', '2026-06-28 19:11:50', '2026-07-02 12:20:22'),
