(12009, 592, NULL, 'Сергей', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Верни пожалуйста деньги, которые ты обманным путем вытянул с меня под видом оказания услуг. И если я не мог на тот момент контролировать тебя , так как я находился за границей ,это не повод разводить на деньги , и создавать видимость оказания услуг. Я ещё проверю есть ли лицензия на адвоката ,как пишеться на сайте .Если есть ,то напишу жалобу туда ,кто эту лицензию выдавал.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-01-26 00:00:00', NULL, '0410da452697a7a06184a89e25f025f96c22912e', 'google', 'Сергей', NULL, '2022-01-26', '2026-06-28 19:13:11', '2026-06-29 14:22:02'),
(12010, 592, NULL, 'Сергей', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Взял у меня деньги и ни чего не сделал .Только рассказывал ,что он делает . Пока я не узнал истинную ситуацию,что он ни к кому не обращался и ни чего не делал , а только вытягивал с меня деньги.я ставлю оценку 1 ,но другого варианта нет, а так и она завышенная.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-01-26 00:00:00', NULL, 'a6a1093cc0d9aed9ede970614c9fa2cbd31cbe3c', 'google', 'Сергей', NULL, '2022-01-26', '2026-06-28 19:13:11', '2026-06-29 14:22:02'),
(12011, 592, NULL, 'Сергей', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Я поставил оценку 1 ,но и это много. Он вообще не заслуживает ни какой оценки . Оценивать не за что. Одним словом аферист.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-01-26 00:00:00', NULL, '98bd1c7b5235590db88105ed9f2ccc83fd995697', 'google', 'Сергей', NULL, '2022-01-26', '2026-06-28 19:13:12', '2026-06-29 14:22:02'),
(12012, 592, NULL, 'Сергей', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Аферист. Берёт деньги и ни чего не делает , а создаёт видимость что делает. И знания на адвоката у него и близко нет.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-01-26 00:00:00', NULL, '9736f4d951e33ba1c4ae5871a30ca65a757678a0', 'google', 'Сергей', NULL, '2022-01-26', '2026-06-28 19:13:12', '2026-06-29 14:22:02'),
(12013, 552, NULL, 'Ira Vepretskaya', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Мария Анатольевна вчера на встрече которую ждала около часа вместо того,чтобы показать отчёт о проделанной работе,стала угрожать,что знает мою личную информацию и моего сына...и адрес мой...и если я не уберу жалобы,она меня ославит в интернете...но вот забыла она что за разглашение личной информации статья...я все зафиксировала на телефон...она меня выгнала...сказав идите в суд пишите жалобы...вот я и пишу... знайте теперь кто такая Фортушко Мария Анатольевна и желаю не попадать к ней...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-27 00:00:00', NULL, '3dad4de0c5e4021e364a76d045d39e6f99044f36', 'google', 'Ira Vepretskaya', NULL, '2026-06-27', '2026-06-28 21:07:53', '2026-07-02 12:18:54'),
(12014, 552, NULL, 'Ira Vepretskaya', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Крайне недовольна работой Марии Анатольевны! Уже более трёх месяцев после подписания договора я не могу достучаться к ним...на словах... всё сделали...но так покажите,где отчёт о проделанной работе...в позапрошлый раз она его порвала...я отказалась от их услуг...написала 2 претензии,на них никто не ответил...и вот спустя два месяца уже эта Мария Анатольевна Фортушко звонит и предлагает наконец то такой обмен,я убираю жалобы...а она мне покажет отчёт... представляете...да отчёт...я не согласилась... нужно посмотреть...что сделано...она назначила встречу,я пришла , её нет ... жду... Звонит эта Мария и говорит что только что заболела...предупредить... нельзя...я в шоке...но допускаю... бывает...хотя раньше тоже такое было .. пишу ей... когда сможет...пусть напишет... позвонила...опять назначили время...я уже отпуск на работе взяла...приезжаю... жду.. через 15 мин. Она выходит и просит подождать... ещё 15 мин.и в итоге...я просидела около часа...за это время... звонила ей...не ответила,проходила мимо меня..и ничего не сказала...на рецепции стояла...смеялась...я в телефоном режиме...общалась со своим юристом...так она..писала .они провоцируют ..вызывают на конфликт...чтобы потом представить меня скандалисткой... спокойно сидите.. ждите...потом эта Мария подошла и провела меня в кабинет..и ..показала только выписку из ВЛК...,а отчёт где?...сказала уберите при мне жалобы...я покажу отчёт...я отказалась ...в итоге отчёт не показан...да его и нет...и ещё стала опять угрожать...что она знает,мой адрес...и в интернете напишет...и вообще идите в суд ... пишите жалобы...и вот так закончилась эта встреча... ужасная компания ...и эта юрист Мария Анатольевна... никому не советую обращаться к ним...и будьте осторожны при подписании договора...иду в суд...и ещё есть несколько вариантов...вот журналисты предлагают снять о них ролик...не советую обращаться в ЦПД!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-26 00:00:00', NULL, '99b1ced41c9b0c944ff7e70275a9ef17375b71e5', 'google', 'Ira Vepretskaya', NULL, '2026-06-26', '2026-06-28 21:07:53', '2026-07-02 12:18:54'),
(12015, 552, NULL, 'Ігор', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Допомогли своєчасно оформити документи для виїзду за кордон, процедура ця непроста і доволі неприємно юрист Роман один із команди юристів взявся за цю справу і в принципі Ми навіть не відчули дискомфорту все як в людей дякую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-24 00:00:00', NULL, '5152b726488e68f385a3bb515081ca45efb5b668', 'google', 'Ігор', NULL, '2026-06-24', '2026-06-28 21:07:53', '2026-07-02 12:18:54'),
(12016, 552, NULL, 'Клієнт ****0544', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Роман, юрист який мені допоміг вчасно виправити помилку , ситуація виникла навколо подання декларації і юрист Роман вчасно вказав мені на помилки які могли мати наслідки дуже вдячна за поради та консультації', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-24 00:00:00', NULL, 'abaab265c7728c0d5b2ac1719c46f6a4c77914b5', 'google', 'Клієнт ****0544', NULL, '2026-06-24', '2026-06-28 21:07:53', '2026-07-02 12:18:54'),
(12017, 552, NULL, 'Клієнт ****0235', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Бажаю здоров\'я хочу залишити відгук і подяку від нашого підрозділу в нас на митниці була затримка з допомогою від волонтерської організації ми Звернулися до юриста Романа та надали йому Грант на виконання нашої задачі з чим Роман успішно справився Дякуємо Слава Україні!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-24 00:00:00', NULL, '6e3095193b5b9271056ba81fb7db8f5f9e38d252', 'google', 'Клієнт ****0235', NULL, '2026-06-24', '2026-06-28 21:07:53', '2026-07-02 12:18:54'),
(12018, 552, NULL, 'Игорь Кожарин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Був у Центрі правової допомоги у юриста Богдана Володимировича. Дуже сподобалась консультація. Буду радий приїхати на повторні зустрічі', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-24 00:00:00', NULL, 'b34ca98a2bebee90b7b66d7f7a70361688c773d0', 'google', 'Игорь Кожарин', NULL, '2026-06-24', '2026-06-28 21:07:53', '2026-07-02 12:18:54'),
(12019, 552, NULL, 'Олена Інкогніто', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Це не юридична компанія. Працює в них така собі Ілона. Бреше в очі. Взагалі не компетентна. Заплатила гроші, залишилась без нічого. Ні грошей ні пенсіїї. Зустічав *юрист* Дмитро. Запевнив, що все буде добре тіко гроші давайте. Брехав майже рік. Люди типу освіту отримують, але не працюють. Просто курять інших та кидають на гроші. Ганьба.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-23 00:00:00', NULL, 'b5e05e0f16f9e74ae3aac0dbfa8c9c878e1a6615', 'google', 'Олена Інкогніто', NULL, '2026-06-23', '2026-06-28 21:07:54', '2026-07-02 12:18:54'),
(12020, 552, NULL, 'Володимир Рибальченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Повністю задоволений наданою мені консультацією . Все чітко, зрозуміло та на високому професійному рівні .', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-23 00:00:00', NULL, 'ce36287b536c7964525fe7f75e16fb60d8d0e654', 'google', 'Володимир Рибальченко', NULL, '2026-06-23', '2026-06-28 21:07:54', '2026-07-02 12:18:54'),
(12021, 552, NULL, 'Ira Vepretskaya', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Не довольна работой Марии Анатольевны...затягивает...игнорирует... заранее договорились о встрече... наконец то,за три месяца так и не показала отчёт о проделанной работе... предыдущий отчёт Мария Анатольевна порвала при мне...и вчера я пришла на встречу и она не пришла...якобы уехала...или заболела...и это уже не первый раз...и не предупредила... даже...что не может... вообщем, отношение к клиенту далеко не уважительное...который заплатил большую сумму денег и требует показать отчёт... крайне негативное отношение,не советую обращаться к ним.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-23 00:00:00', NULL, '2b00b2e4e53e6d00618e652af38f75f38dc11e19', 'google', 'Ira Vepretskaya', NULL, '2026-06-23', '2026-06-28 21:07:54', '2026-07-02 12:18:54'),
(12022, 552, NULL, 'Andriy Sverediuk', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Головна мета цього так званого центру — витягнути з вас повну оплату. Обіцяють швидкі терміни та результат. У підсумку: повне затягування процесу. Нічого не вирішили. Нікому не рекомендую сюди звертатися — в договорі нічого стосовно результату.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-20 00:00:00', NULL, 'cbab9250d3bd9863b5df56b0621f5cbbabb8dac4', 'google', 'Andriy Sverediuk', NULL, '2026-06-20', '2026-06-28 21:07:54', '2026-07-02 12:18:54'),
(12023, 552, NULL, 'Товкун Тамара', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую за професійне відношення та допомогу Маріє Анатоліївна! Оцінка - відмінно!.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-19 00:00:00', NULL, 'd073db8dfc874b3da72480a83952aaf41d7c301b', 'google', 'Товкун Тамара', NULL, '2026-06-19', '2026-06-28 21:07:54', '2026-07-02 12:18:54'),
(12024, 552, NULL, 'Ira Vepretskaya', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Обратилась за помощью в ЦПД,юрист Фурман Мария Анатольевна мне уверенно пообещала,что все сделает..за очень короткий срок,была названа сумма...высокая...я хотела подумать...стала давить,манипулировать,говорила ,что времени почти нет... заплатила... уже на следующий день после её рассказа...усомнилась в её ответах... доказательства у меня уже были...поняла, что это обман...и сказала ей ,что отказываюсь от их услуг,она мне подсовывали подписать акты,я отказалась,а отчёт о проделанной работе она при мне порвала..да ещё Ароматика Наталья юрист ,а она мне представила её,как адвоката...опять обман..я была в ассоциации адвокатов,сказали такой нет у них...по телефону они нашли её... всё оказалось очень плохо...я до сих пор с ними разбираюсь...на две претензии ответа нет...собираю доказательства и пойду в надлежащие органы Не советую ЦПД,не помогут, обманывают манипулируют угрожают рвут документы...не рекомендую,а отзывы положительные они пишут сами...это точно...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-17 00:00:00', NULL, 'f14cf23313be1d84410d2e64fb537db9a45e811c', 'google', 'Ira Vepretskaya', NULL, '2026-06-17', '2026-06-28 21:07:54', '2026-07-02 12:18:54'),
(12025, 552, NULL, 'Клієнт ****3001', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обратился в ЦПД к юристу Марии Анатольевне по вопросу открытых исполнительных производств. Консультацией удовлетворен. Спасибо', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-17 00:00:00', NULL, 'fe1df866816f5b406e4b8b1535447c8af336e258', 'google', 'Клієнт ****3001', NULL, '2026-06-17', '2026-06-28 21:07:54', '2026-07-02 12:18:54'),
