(12032, 552, NULL, 'Nastya Sergienko', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Анастасія Віталіївна уважно вислухала мою ситуацію, проаналізувала документи та запропонувала найбільш ефективний варіант вирішення питання. Дуже приємно працювати з юристом, який не лише добре знає закон, а й дійсно переймається інтересами клієнта', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-15 00:00:00', NULL, '41075d68745004ecd5edd9f0a82af547d1074fee', 'google', 'Nastya Sergienko', NULL, '2026-06-15', '2026-06-28 21:07:55', '2026-07-02 12:18:54'),
(12033, 552, NULL, 'Софія Іщук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити щиру подяку юристу Анастасії Віталіївні за професійну консультацію. Зверталась із складним сімейним питанням, але отримала вичерпні відповіді, детальне роз\'яснення всіх можливих варіантів вирішення ситуації та чіткий план подальших дій.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-15 00:00:00', NULL, '1b63726a330c5136f6859d6834e7cf5271b6faf2', 'google', 'Софія Іщук', NULL, '2026-06-15', '2026-06-28 21:07:55', '2026-07-02 12:18:54'),
