(23462, 594, NULL, 'Іра Слюсар', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я дуже задоволена співпрацею з компанією Мережа права. Кваліфіковані, ввічливі фахівці допомогли мені розібратися з нарахуванням пенсії, вигравши всі суди встановили справедливе нарахування індексації. Порадила своїм знайомим вашу компанію. Щиро вам дякую за вашу працю.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-19 00:00:00', NULL, '8cf007a2e6251dc68c421a1aa1c439a2d58c2a29', 'google', 'Іра Слюсар', NULL, '2026-02-19', '2026-06-28 22:17:21', '2026-07-01 08:13:51'),
(23463, 594, NULL, 'Клієнт ****2004', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я обратилася в компанию Мережа права по вопросам заниженной пенсии. Юристы просчитали все и сделали все чтобы моя пенсия увеличилась на 1500 грн. Я продолжаю с ней работать. Рекомендую Вам эту компанию', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '44aa19c13e71f3b55b224a1c1fcd4a21caeb0876', 'google', 'Клієнт ****2004', NULL, '2026-02-18', '2026-06-28 22:17:21', '2026-07-01 08:13:51'),
(23464, 594, NULL, 'Світлана Назарук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую цю компанію пенсіонерам.особисто співпраццюва з нею Як результат, виграла всі суди, отримала індексацію до пенсії, плюс компенсацію.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, 'a7cb4117cde05ec0f8603aa41ae7657f31f0eac3', 'google', 'Світлана Назарук', NULL, '2026-02-18', '2026-06-28 22:17:21', '2026-07-01 08:13:51'),
(23465, 594, NULL, 'Володимир В\'язівський', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Все зробили, як і домовлялись! Тепер з їх допомогою готуємо документи до суду, все дистанційно, без відвідування офісу. Зручно. Тільки треба мати інтернет , щоб працював і трохи вміти користуватись особистим кабінетом на сайті ПФУ', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '7553f6ad3c397f4095c0c790eea08a38ff65fb48', 'google', 'Володимир В\'язівський', NULL, '2026-02-18', '2026-06-28 22:17:21', '2026-07-01 08:13:51'),
(23466, 594, NULL, 'Клієнт ****3067', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я щиро вдячна компанії за надані послуги. Рекомендую усім звертатися. Усі питання вашої пенсії будуть вирішенні гарантовано.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '0d94d90bf3c66d046a9508914e90cdcdb1607820', 'google', 'Клієнт ****3067', NULL, '2026-02-18', '2026-06-28 22:17:21', '2026-07-01 08:13:51'),
(23467, 594, NULL, 'Алла Караченцева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Вдячна за допомогу, всі судові рішення в мою користь. Надійна компанія з професійними юристами. Дякую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '01cb55c5aaad5537c9b1fdbc7bdd3e286ea2c255', 'google', 'Алла Караченцева', NULL, '2026-02-18', '2026-06-28 22:17:22', '2026-07-01 08:13:51'),
(23468, 594, NULL, 'Валерій Денисов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокати компанії Мережа права,гарно знають свою справу та та цілеспрямовано йдуть до перемоги по справі. Приємно з вами співпрацювати. Раджу спеціалістів компанії Мережа права, ви не пошкодуєте.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, 'b6a63ec1ad0e946891da395ee51e65a7bfe70fe7', 'google', 'Валерій Денисов', NULL, '2026-02-18', '2026-06-28 22:17:22', '2026-07-01 08:13:51'),
(23469, 594, NULL, 'Клієнт ****0659', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійна, якісна робота командна робота.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '678a495919bbde4de4f48c36dcd9f3897de5286e', 'google', 'Клієнт ****0659', NULL, '2026-02-18', '2026-06-28 22:17:22', '2026-07-01 08:13:51'),
(23470, 594, NULL, 'Клієнт ****3774', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я вам дуже вдячна, мої друзі вже теж з вами', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, 'f971671e8c9a446c63cdc3e66e32e8ba747e00ac', 'google', 'Клієнт ****3774', NULL, '2026-02-18', '2026-06-28 22:17:22', '2026-07-01 08:13:51'),
(23471, 594, NULL, 'Клієнт ****7057', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро вдячна за співпрацю, працюють справжні професіонали, завжди ввічливі та відзивчиві. Рекомендую всім своїм знайомим, з моєї рекомендації вже одна людина з вами співпрацює', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '006c9a3a82341eba33f23e803f42a955027df6e7', 'google', 'Клієнт ****7057', NULL, '2026-02-18', '2026-06-28 22:17:22', '2026-07-01 08:13:51'),
(23472, 594, NULL, 'Клієнт ****0285', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Шановні пенсіонери , щиро рекомендую ЮК Мережа права для відстоювання своїх законних прав перед Пенсійним фондом України . Дякую юристам ЮК Мережа права за допомогу . Так тримати . Ви найкращі.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-18 00:00:00', NULL, '55e8016a5c1ba3c8b47bfb32e7086df47d9e6b6b', 'google', 'Клієнт ****0285', NULL, '2026-02-18', '2026-06-28 22:17:22', '2026-07-01 08:13:51'),
(23473, 594, NULL, 'Клієнт ****7271', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Вийшов на пенсію у 2021р.У 2024р. Через мережу права відсудив1200грвнів щомісячної індексації до основного тіла пенсії плюс 20 тис.гривнів заборгованості ПФУ за період судових розглядів. Рекомендую юридичну контору Мережу прева з власного досвіду, прошу не боятися адже ви можете сутєво збільшити основне тіло пенсії а судові витрати отримаєте у вигляді доплати за період судових розглядів вашої справи в судах до ПФУ в яких ви особисто навіть не будете присутніми, так як Мережа права все бере на себе. Особисто я у 2025 подав через Мережу права у суд ПФУ знов на перерахунок індексації вже за 2025р.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-17 00:00:00', NULL, '936dcbde74d3074d2ccdeab81d695930bbcdf849', 'google', 'Клієнт ****7271', NULL, '2026-02-17', '2026-06-28 22:17:22', '2026-07-01 08:13:51'),
(23474, 594, NULL, 'Клієнт ****3718', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Користуюсь вже вдруге послугами компанії. Адвокати компанії виграли вже другий суд по індексації моєї пенсії. Після першого виграного суду і(індексація 2022р) пенсійний фонд мені збільшив пенсію майже на 6000 грн, та повернув заборгованість. Зараз адвокати компанії виграли ще один суд (індексація 2024р). Вже є рішення. Чекаємо на дії Пенсійного фонду.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-17 00:00:00', NULL, '5b25c333a6091f443a2800e96a4ab5a4e4937ec8', 'google', 'Клієнт ****3718', NULL, '2026-02-17', '2026-06-28 22:17:23', '2026-07-01 08:13:51'),
(23475, 594, NULL, 'Клієнт ****0588', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Спввпрацюємо плідно. Надіюсь на позитивний результат.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-17 00:00:00', NULL, '9082fcd8a42b1387142d8705dacb90a83d9963ef', 'google', 'Клієнт ****0588', NULL, '2026-02-17', '2026-06-28 22:17:23', '2026-07-01 08:13:51'),
(23476, 594, NULL, 'Віталій Панченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро вдячний юристам ЮК \"Мережа права\" за вашу професійну та відповідальну роботу . Співпрацюю з вами два з половиною роки . За цей час компанія успішно допомогла мені у вирішенні питань військових виплат, вигравши дві справи, третя зараз розглядається у суді и знаходиться на завершальному етапі. Я повністю задоволений рівнем підготовки спеціалістів, їхнім підходом та підтримкою на кожному етапі. Ви дійсно знаете свою справу й працюєте на результат. Обов\'язково й надалі звертатимусь саме до вас, та з упевненістю рекомендую вашу команду!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-16 00:00:00', NULL, 'fe5b8850163591789a1eccf4c4c2f055a4bf1928', 'google', 'Віталій Панченко', NULL, '2026-02-16', '2026-06-28 22:17:23', '2026-07-01 08:13:51'),
(23477, 594, NULL, 'Клієнт ****7372', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Задоволенний. Якісне спілкування. Та рішення.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-16 00:00:00', NULL, '4c4122ca1f4ad8b25155526745c338f62fa8cb24', 'google', 'Клієнт ****7372', NULL, '2026-02-16', '2026-06-28 22:17:23', '2026-07-01 08:13:51'),
(23478, 594, NULL, 'Валентина Рамазанова', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Я не рекомендую гроші зтягують з людей а роботи не роблять ,а потім ще плати краще не звертатися в таку мережу права', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-16 00:00:00', NULL, 'ce13b724abcfd28427de5da8c39c820cfe79c43a', 'google', 'Валентина Рамазанова', NULL, '2026-02-16', '2026-06-28 22:17:23', '2026-07-01 08:13:51'),
(23479, 594, NULL, 'Анастасія', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже вдячна Мережа права за вирішення мого питання. Співробітники висококваліфіковані, видно коли спілкуєшся із професіоналами. Дякую вам і бажаю процвітання.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-27 00:00:00', NULL, 'e832f135ee7c61d3ddc7f546d9d4528691fc8775', 'google', 'Анастасія', NULL, '2026-01-27', '2026-06-28 22:17:23', '2026-07-01 08:13:51'),
(23480, 594, NULL, 'Клієнт ****9104', NULL, 0, NULL, NULL, 0.00, 3, NULL, 'Не чего плохо го не могу сказать за контору мереже право, хотя и не сказал бы что все замечательно, обратился к ним за помощью посли списания по состоянии здоровье , что бы мне провели индексацию зарплатой за годы службы , но и ещё двух дел, прошло больше года и не чего , не какого положительного на данный момент результатов Может этот мой отзыв хоть немного мотивирует Сотрудников Мереже Право, и более настойчиво займутся моими делами , потому что для меня это важно', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-23 00:00:00', NULL, '338d9c282a0d9388c4fcd0fd24e0daf951e7c5da', 'google', 'Клієнт ****9104', NULL, '2026-01-23', '2026-06-28 22:17:23', '2026-07-01 08:13:51'),
(23481, 594, NULL, 'Альона Денисюк', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталися в Мережу права щодо виплат чоловіку військовому. Йому після поранення не захотіли виплачуваьи повні суми. Самі намагались боротись - безрезультатно. А тут звернулись до адвоката Владислава Мандрика. Компетентний, розумний адвокат, детально пояснив весь процес, які документи зібрати. І навіть без суду отримали свої кошти. А це немаленькі суми - 134 000 гривень. В інших компаніях за таку роботу хотіли здерти з нас великі гроші. Тут теж звісно беруть оплату, але в межах розумного.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-21 00:00:00', NULL, 'fd5c60f88a494324973694b607e169fc708f1af9', 'google', 'Альона Денисюк', NULL, '2026-01-21', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23482, 594, NULL, 'Клієнт ****1557', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Разом з \"Мережею права\" моя бабуся виграла всі судові справи з повернення законного розміру пенсії. І зараз продовжується робота в судах. Велика вдячність компанії за таку потрібну роботу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-08-06 00:00:00', NULL, 'b3b012a527d6926e9f9ac51c516cbcddb32caaac', 'google', 'Клієнт ****1557', NULL, '2025-08-06', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23483, 594, NULL, 'Дарія Поддубецька', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Компанія Мережа Права допомогла мені отримати пенсію. Так справа була не легкою, але я дуже вдячна всій команді, що допомагають людям у цей не легкий час. Я дуже рекомендую компанію Мережу права, бо тут працює чесна і порядна команда. Ще раз дякую за вашу роботу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-07-15 00:00:00', NULL, '4486e755402a7a972f1087309c38ae383bd77aa3', 'google', 'Дарія Поддубецька', NULL, '2025-07-15', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23484, 594, NULL, 'Клієнт ****1124', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже швидко та грамотно отримав необхідні документи які потрібні були негайно, але через бюрократію не міг отримати їх на протязі трьох місяців. Завдяки Мережі Права документи були видані на протязі 5 днів з моменту подання запиту. Рекомендую всім хто через бюрократичну машину чи інші обставини не можуть знайти вихід. Дякую Вам велике.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-05-30 00:00:00', NULL, 'a06579ff309924efac47c1aaa98a33cf6f0aad78', 'google', 'Клієнт ****1124', NULL, '2025-05-30', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23485, 594, NULL, 'Клієнт ****7676', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже надійна компанія, постійний супровід дій по справі, завжди пропонують варіанти покращення вашого фінансового добробуту', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-05-02 00:00:00', NULL, '1ef260b1f7097c0540703b2057c4e9e9031ae0e7', 'google', 'Клієнт ****7676', NULL, '2025-05-02', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23486, 594, NULL, 'Клієнт ****4040', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Ні, не рекомендую. Ціни захмарні. Розвод по-одеські. Пропонували аудит пенсії за 2,4 тис грн. Київське бюро зробило за 600 грн.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-04-29 00:00:00', NULL, '723cc9fd67470461f8d38741c600d88d1a9d24d8', 'google', 'Клієнт ****4040', NULL, '2025-04-29', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23487, 594, NULL, 'Клієнт ****3658', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'ЮК \"Мережа права\" дійсно працює впевнено і цілеспрямовано, відстоюючи інтереси пенсіонерів-правоохоронців у судах. Уже звернулася вдруге до \" Мережі права\" і сподіваюся на позитивний результат! Рекомендую всім \"Мережу права\" і обирайте тільки цю компанію! Тут працюють професіонали своєї справи!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-04-14 00:00:00', NULL, 'e2fe58bdfa69c8a9f07b9f0725f56f637d4ac234', 'google', 'Клієнт ****3658', NULL, '2025-04-14', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23488, 594, NULL, 'Клієнт ****6211', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Однозначно рекомендую! Співпрацював з цією компанією. Все успішно. Пенсію добавили на 2000 грн. Дякую за вашу працю!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-04-10 00:00:00', NULL, '38dd7b4be15b8d3ca7983577552a65728e352c9d', 'google', 'Клієнт ****6211', NULL, '2025-04-10', '2026-06-28 22:17:24', '2026-07-01 08:13:51'),
(23489, 594, NULL, 'Клієнт ****8005', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась у компанію для вирішення питання. Співробітники віднеслись з розумінням, дуже швидко та відповідально допомогли вирішити мою справу . Кожен співробітник виконував свою роботу досконало. Дякую і щиро рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-03-23 00:00:00', NULL, '1ce48c1a1c1673095844bfa82b2d11d433255e39', 'google', 'Клієнт ****8005', NULL, '2025-03-23', '2026-06-28 22:17:25', '2026-07-01 08:13:51'),
(23490, 594, NULL, 'Клієнт ****4899', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже задоволена результатами співпраці з юристами компанії. З трьох справ, які провела компанія, за двома вже отримую суттєво підвищену пенсію, а за третьою справою вже є позитивне рішення суду. Порекомендувала компанію своїм товаришам. Дуже ввічливо та професійно відповідають на питання. Дякую та рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-03-04 00:00:00', NULL, '254fb9066faf248d3234a7eab9eeaf433f0fae60', 'google', 'Клієнт ****4899', NULL, '2025-03-04', '2026-06-28 22:17:25', '2026-07-01 08:13:51'),
(23491, 594, NULL, 'Клієнт ****8790', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже добра компанія,рекомендую, беруть передоплату, половину, інше коли отримаєш кошти, завжди відповідають, дуже добре ставлення, тримають у курсі справи.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-02-20 00:00:00', NULL, '510125bbc9a4909399e7cbb4d25ed9a6535704d3', 'google', 'Клієнт ****8790', NULL, '2025-02-20', '2026-06-28 22:17:25', '2026-07-01 08:13:51'),
(23492, 594, NULL, 'Клієнт ****3028', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Цінність виконаної роботи компанії відповідає вартості. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-02-13 00:00:00', NULL, '660aee81b71c0ab700832c8df57d52faa8592960', 'google', 'Клієнт ****3028', NULL, '2025-02-13', '2026-06-28 22:17:25', '2026-07-01 08:13:51'),
(23493, 594, NULL, 'Клієнт ****7926', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Судився два рази за перерахунок пенсії, все дуже швидко і зручно. Термін зайняв десь до 9 місяців. Після суду пенсія збільшилась вдвічі. Раджу всім пенсіонерам яким держава недоплачує пенсію звертатися в «Мережу права».', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-02-06 00:00:00', NULL, '01a527e41d357211092d2bb4feca4eacc0985920', 'google', 'Клієнт ****7926', NULL, '2025-02-06', '2026-06-28 22:17:25', '2026-07-01 08:13:51'),
(23494, 594, NULL, 'Клієнт ****7683', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу насамперед сказати, що до цього не мав діла з юридичними компаніями але в житті бувають моменти коли дійсно необхідна допомога. У цієї компанії професійний підхід до справи, кваліфікована консультація, оперативність, рекомендую! Був дуже задоволений послугами наданими мені, тому в цілому мої враження тільки позитивні', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-29 00:00:00', NULL, 'f7a96bd72ae9751f6d2c999ff5435b689f415fe3', 'google', 'Клієнт ****7683', NULL, '2025-01-29', '2026-06-28 22:17:25', '2026-07-01 08:13:51'),
(23495, 594, NULL, 'Клієнт ****7770', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже вічливі працівники. Сподобалось відношення до своїх клієнтів та виконання роботи. Всім рекомендую та буду звертатися ще!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-26 00:00:00', NULL, '0d1ce7d21b76c527c7c8428e3a55df52571d7e89', 'google', 'Клієнт ****7770', NULL, '2025-01-26', '2026-06-28 22:17:25', '2026-07-01 08:13:51'),
(23496, 594, NULL, 'Клієнт ****3331', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Моєму чоловіку збільшили пенсію, дякую компанії. Ми для цього відправили лише документи. Все інше робили юристи.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-23 00:00:00', NULL, '63702b711313c2e16d5ea4087ba666a9577e0a7b', 'google', 'Клієнт ****3331', NULL, '2025-01-23', '2026-06-28 22:17:26', '2026-07-01 08:13:51'),
(23497, 594, NULL, 'Клієнт ****5960', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже приємна компанія, вирішили мої проблеми, чесні, ввічливі, порядні спеціалісти, рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-22 00:00:00', NULL, 'f43f4771e750a21c29f83ca461cfdf5bb6be5a48', 'google', 'Клієнт ****5960', NULL, '2025-01-22', '2026-06-28 22:17:26', '2026-07-01 08:13:51'),
(23498, 594, NULL, 'Клієнт ****8040', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Свою роботу компанія виконала на відмінно. Пенсію отримую без обмежень з нарахованої індексацію', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-21 00:00:00', NULL, 'bd5d3bea1286cb41304e2c0e76a10d6d957824c1', 'google', 'Клієнт ****8040', NULL, '2025-01-21', '2026-06-28 22:17:26', '2026-07-01 08:13:51'),
(23499, 594, NULL, 'yara kokyb', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже задоволена цією компанією. Дякую фахівцям за професійну роботу, все чітко та зрозуміло пояснювали, звітували.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-20 00:00:00', NULL, 'eccc54566f7533dae153f97099398ee5a1d6f10b', 'google', 'yara kokyb', NULL, '2025-01-20', '2026-06-28 22:17:26', '2026-07-01 08:13:51'),
(23500, 594, NULL, 'Клієнт ****5960', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Сподобалась робота компанії. Пояснила юристам своє питання, а далі вся паперова рутина була їх робото. В свою чергу я отримала позитивний результат і залишилась задоволеною. З впевненістю можу рекомендувати Мережу права своїм знайомим і рідним.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-16 00:00:00', NULL, '23329587a0638257b6f0e54278ef1ca3e37e5496', 'google', 'Клієнт ****5960', NULL, '2025-01-16', '2026-06-28 22:17:26', '2026-07-01 08:13:51'),
(23501, 594, NULL, 'Олена Денисюк', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Співпрацею із юридичною компанією залишились задоволені. Звертались щодо збільшенн цивільної пенсії для бабусі. В результаті, виплати збільшились на 2000 грн. Хоч буде трохи на медикаменти. Дякую велике юристам за вашу роботу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-15 00:00:00', NULL, '3f47f2eee21b6d73954e62e6a6a6e1016f9ff4d6', 'google', 'Олена Денисюк', NULL, '2025-01-15', '2026-06-28 22:17:26', '2026-07-01 08:13:51'),
(23502, 594, NULL, 'Клієнт ****9547', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Чоловік військовий, отримав поранення, але грошей за лікування від держави так і не було. Звернулися в Мережу права. Ніхто не обіцяв, що все виплатять вже завтра, але через декілька місяців після підписання договору він отримав виплати за всі місяці. Так, заплатили відсоток від виплати, але в нас було проблеми з документами.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-14 00:00:00', NULL, '09d6f46985668de9def71d6410b748a872289193', 'google', 'Клієнт ****9547', NULL, '2025-01-14', '2026-06-28 22:17:26', '2026-07-01 08:13:51'),
(23503, 594, NULL, 'Клієнт ****4919', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Залишився без виплат. Командування 4 місяці розповідає різні байки та тлумачать закони \"по своєму\". Звернувся до \"Мережі права\". Юристи оперативно підготували запит та відправили у військову частину. Чекаємо на відповідь.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-09 00:00:00', NULL, '837f62cda66dc0bcf1b28078c2b0a10b3fd46bfa', 'google', 'Клієнт ****4919', NULL, '2025-01-09', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23504, 594, NULL, 'Mixa Penchev', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро дякую компанії \"Мережа Права\" за чудову співпрацю та професійний підхід. Весь процес був комфортним, адже спеціалісти завжди були на зв’язку, надавали кваліфіковану допомогу. Їхній професіоналізм і відповідальність заслуговують найвищої оцінки. Справу успішно вирішено, і я дуже вдячний за це', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-08 00:00:00', NULL, '1fa76d3f748b96cb7b6c8ae9c1695a3dc1e89530', 'google', 'Mixa Penchev', NULL, '2025-01-08', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23505, 594, NULL, 'Клієнт ****1124', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую компанію \"Мережа права\". Команда юристів добре попрацювала і я вже отримую суттєво підвищену пенсію. Порекомендував компанію своїм товаришам, погодились, вже теж чекають рішення суду. Ніякої мороки, компанія сама подає запити куди треба, слідкує за ходом справи та повідомляє про її стан. Дуже ввічливо та професійно відповідають на питання. Дякую та рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-01-06 00:00:00', NULL, '372fb09771c9111c58e12973a770b20ab895ca5a', 'google', 'Клієнт ****1124', NULL, '2025-01-06', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23506, 594, NULL, 'Александр Иванов', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Не рекомендую цю контору! Вже 10 місяців пройшло як я до них звернувся і вони ще навіть позов не підготували! Кажуть чекайте ми зробили запит і все! На питання кажу якщо частина не відповідає то що будете робити то починають казати чекайте!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-12-22 00:00:00', NULL, '43b9964398e91f8f128c0b1e8a6d7e9ded3b57b2', 'google', 'Александр Иванов', NULL, '2024-12-22', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23507, 594, NULL, 'Клієнт ****7308', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я пенсіонер ДСНС. Звертався в цю компанію щодо своєї пенсії і все перерахували. Почекав рік. Юристи все толково і доступно пояснюють. Головне, що мені не треба було нікуди їхати, все проходило в телефонному режимі. І вони ще надають допомогу й військовим. Загалом, позитивні враження від цієї контори.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-12-17 00:00:00', NULL, 'e3dc22a9a91186216f737e1ecb03d81ff7226300', 'google', 'Клієнт ****7308', NULL, '2024-12-17', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23508, 594, NULL, 'Клієнт ****3207', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернувся в цю компанію, тому що не виплачували за лікування і успішно. Через 6 місяців після підписання договору я отримав виплати за всі місяці. Оплата не більше, як в інших адвокатів, але попередній адвокат здер гроші і не зміг допомогти. Тому тут був радий, що все вирішилось і був згоден на таку суму.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-11-15 00:00:00', NULL, 'f98584b4c5ac86e634253b2921809dc346feffb3', 'google', 'Клієнт ****3207', NULL, '2024-11-15', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23509, 594, NULL, 'Алексей Химич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'ЮК \"Мережа права\" це професійна, серйозна, юридична компанія, якій можна довіритись. Правильний підбір кадрів дозволяє вирішити всі питання по відстоюванню власних інтересів в судах та збільшенню пенсі. Мені вже двічі була збільшена пенсія по двох програмах, зараз юристи й надалі працюють в моїх інтересах. Всім хто ще сумнівається до якої компанії звернутися - рекомендую \"Мережу права\".', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-11-11 00:00:00', NULL, '48de51f09f5c25531347a3deae86541df86ed17a', 'google', 'Алексей Химич', NULL, '2024-11-11', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23510, 594, NULL, 'Клієнт ****0414', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Задоволений роботою компанії \"Мережа права\". Гарні спеціалісти виграли для мене судову справу і тепер моя пенсія збільшена. Дякую команді за співпрацю, попереду наступний суд і перемога. Рекомендую пенсіонерам цю компанію, надійну, порядну, відповідальну.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-11-08 00:00:00', NULL, '64abae8648c3eb88ddaee25a4dc227485f3a579d', 'google', 'Клієнт ****0414', NULL, '2024-11-08', '2026-06-28 22:17:27', '2026-07-01 08:13:51'),
(23511, 594, NULL, 'Клієнт ****6599', NULL, 0, NULL, NULL, 0.00, 2, NULL, 'Шахраї , шо роблять швидко це контракт на оплату який вы не зможете розірвать . Ничім не допомагають на пряму спілкується тільки помічник який кормить завтраками', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-11-07 00:00:00', NULL, '57d7c0f3ef9a8a98c10f9e5aed65c5848431f07a', 'google', 'Клієнт ****6599', NULL, '2024-11-07', '2026-06-28 22:17:28', '2026-07-01 08:13:51'),
(23512, 594, NULL, 'Клієнт ****5945', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую юридичну компанію Мережа права. Свою роботу компанія виконала на відмінно. Пенсія отримується без обмежень у розмірі 90% з нарахованої індексацію.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-22 00:00:00', NULL, 'b59bddbdbe0fdc59d2b6f5ed5f009e7790d547db', 'google', 'Клієнт ****5945', NULL, '2024-10-22', '2026-06-28 22:17:28', '2026-07-01 08:13:51'),
(23513, 594, NULL, 'Клієнт ****5308', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Співпрацювала з юридичною компанією Мережа права. Всі позови судами різних інстанцій були задоволені на мою користь, тобто користь позивача. Я вдячна працівникам Юридичної компанії за високий професіоналізм, а також за їх роботу, яку вони робили не відволікаючи мене взагалі.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-22 00:00:00', NULL, '177f025ce4f31daa6f74d72f0a75c413121570cc', 'google', 'Клієнт ****5308', NULL, '2024-10-22', '2026-06-28 22:17:28', '2026-07-01 08:13:51'),
(23514, 594, NULL, 'Клієнт ****8219', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Нічого не хочуть робити. Їхне завдання подати позов ду суду де необхідно змінити та внести Ваші данні. А далі вони нічого не хотять робити та чекають кошти коли буде остаточне рішення. Їм необхідно постійно розповідати що вони повинні робити. Вони не знають або не хотять нічого знати елементарних речей які знає будь яка людини кола вона судилась по будь яким питанням.Почалось все з того що спочатку вони розповідали все дуже гарно. Ви підписуєте договір, а далі ми за Вас все зробимо, Вам не потрібного нічого робити тільки заплатіть частину коштів за початок справи, а ділі ми все зробимо (далі ц е тільки слова). Коли вони подали до суду позовну заяву прийшлось їх постійно підштовхувати і розповідати що їм потрібно робити. Спочатку суд зареєстрував позовну заяву та виніс рішення. Потім пройшло 3 місяця коли суд відкрив виконавче провадженя, коли я їм зателефонував і сказав чому ви далі не приймаєте ніякіх дій, то мені відповіли що повинні чекати. Тоді я їм сказав що вони повинні подати заяву не прискорення розгляду справу, добре ми подамо. Після цього було рішення суду в мою користь. Я їм скинув рішення, на що вони сказали чекаємо термін проходження апеляції. Пройшов ще місяць, знову телефоную їм що ви будите робити. На що вони сказали що чекаємо перерахунок коштів від пенсійного фонду. прийшла пенсія, кошти не перехували. Зателефонував їм чому? На що відповіли що суд відправив, но мабуть не встигло дійти. Пройшов ще місяц, перехування пенсії так і не було. Телефоную, питаю чому. На що поступиле дурне запитання,так Вам перехували пенсію, кажу ні. Так в цьому винні помічники судді, що вони повнні були направити рішення до пенсійного фонду. Тоді їх запитаю чому ви не підняли свою пяту точку та не пійшли до суду та не взяли рішення, потів не віднесли до пенсійного фонду. На що вони відповіли що ми цього не повинні робити. Наше завдання тільки складати позовну заяву і більше нічого. Виходить так що це не царське діло відбивати свої ноги. Я розуміє що в краіні йде війна і не вистачає коштів у держави, але закон повинен виконуватись. Таким чином держава затримує перерахунок щоб як можно більше зекономити коштів. Хочу продовжити далі , дана компанія не хоче лишній раз напрягатись, а тількі сидять та чекають як потиче вода. Як вони хвастаються що у нас 40 тис. клієнтів. Скажу так за весь час сумісної співпраці вони не приділяють не якої уваги до свої клієнтів. Поки не позвониш вони даже не вздумають самі зателефонувати. Попросив помічника адвоката щоб мені зателеіфонува мій адвокат, якій призначений. На що почув відповідь що адвокати зовсім не спілкуються зі своїми клієнтами. До цього я вже мав декілька разів справу з іншими адвокатьсками бюро, но такого відношення щі не бачив. На горячій лінії вся грублять, не вислуховувають ваше звернення, а тількі перебивають, не дають слово Вам сказати. Адвокта не доторкані, як і Верховна Рада України. Знайшов номер авдвоката сам особисто телефоную не відповідає, пишу в месенджер не відповідає. Коли на горячій лінії сказав що буду розрививати з вами відношення, то відповіли що не маю права. Но я свої права знаю. Хочу так сказати Вам що якщо хочите потратити свій час та нерви то Вам саме сюди. НЕ РЕКОМЕНУДЮ ЦЮ КОНТОРУ. Вони не цінять своїх клієнтів, бо уних їх 40 тис. все рівно кошти будуть.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-10-10 00:00:00', NULL, '15fc3bee8197fcf6abeccac13519dd61cd995218', 'google', 'Клієнт ****8219', NULL, '2024-10-10', '2026-06-28 22:17:28', '2026-07-01 08:13:51'),
(23515, 594, NULL, 'Клієнт ****7043', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я та мій чоловік, користувалися послугами щодо збільшення пенсії та я особисто вже отримала рішення на повернення 2000 грн., у чоловіка ще триває суд. Так от, хочу подякувати юристам юридичної компанії Мережа Права за допомогу, все пройшло на вищому рівні, так терміни більше 6 місяців, але не за вини компанії.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '8f3a917896bb2bd4c6a3a27044f44a46a92c3f7a', 'google', 'Клієнт ****7043', NULL, '2024-09-25', '2026-06-28 22:17:28', '2026-07-01 08:13:51'),
(23516, 594, NULL, 'Клієнт ****2481', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'У цій компанії працюють справжні професіонали, які знають свою справу. Дякую за допомогу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, '946fa0846a75c938692fcb52e0468d9a073f8820', 'google', 'Клієнт ****2481', NULL, '2024-09-25', '2026-06-28 22:17:28', '2026-07-01 08:13:51'),
(23517, 594, NULL, 'Клієнт ****4899', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Роботою компанії задоволений! Гарний колектив виграв для мене судову справу, збільшивши мою пенсію на 8500гривень. Рекомендую пенсіонерам цю компанію, надійну, порядну, відповідальну.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-25 00:00:00', NULL, 'fa3c1cd143bb9052de82330fa24acba6108d27b1', 'google', 'Клієнт ****4899', NULL, '2024-09-25', '2026-06-28 22:17:28', '2026-07-01 08:13:51'),
(23518, 594, NULL, 'Елена Владимировна', NULL, 0, NULL, NULL, 0.00, 2, NULL, '3 сентября будет год как заключили договор, из плюсов договор составили и прислали быстро чуть ли не в тот же день,ну и квитанции на оплату тоже присылали быстро на этом плюсы закончились. О том как продвигается дело никто не сообщил,один раз позвонили и сказали что нужно ещё раз доплатить потому что чего то там не хватает, это было в январе,оплатила и на этом все на звонки не отвечают либо игнорируют ссылаясь на занятость,дозвонилась на \" горячую линию\" сказали что перезвонят после 22.05.2024 и вот завтра уже 22.07.2024 но так и не позвонили.никому не советую и своим всем коллегам сказала что это шарашкина контора совершенно некомпетентные. Может это мне только одной так не повезло, хотя мои знакомые пенсии пересчитывают очень быстро,а тут год адвокаты не могут сдвинуться с места.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-07-22 00:00:00', NULL, '2551332caa3f5ce495ecf7681f1134861b9b8085', 'google', 'Елена Владимировна', NULL, '2024-07-22', '2026-06-28 22:17:29', '2026-07-01 08:13:51'),
(23519, 594, NULL, 'Youth Children Camp Camp', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Ця компанія заключила договір на зі мною 10000 грн. 2000 коштувало щоб вони склали заяву на відтермінування так як я вчитель, яку в результаті в ТЦК розглянули і відхилили. Бо крім довідки з школи та інших документів юрист Софія так і не сказала що потрібен військово-обліковий документ, якого не було. Єдине за що дякую, це за те що написали номер абзацу і пункту з статті 23 що стосується права на відтермінування. Коли я сказав що заяву розглянули, але відстрочку не дали, Софія сказала що переробить документ як потребує ТЦК, але ні документу нічого. В результаті мене заблокували бо я не можу дозвонитись до Софії Ігорівни. Вердикт такий. Мережа права це компанія яка гарно стелиться і як результат нічого не виконує. А ще що цікаве офіс в Дніпрі навіть переплутав реквізити по оплаті і мої кошти пішли на інший рахунок, але їх повернули. Безвідповідальність, невиконання до кінця навіть базових домовленостей вимусило мене написати цей відгук. Не звертайтесь в Мережу права,моя порада, їх Юрист Софія Ігорівна може не відповідати на повідомлення весь день, то навіщо така юридична допомога, де ти платиш гроші і робиш все сам?', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-06-19 00:00:00', NULL, '2a504afecc3727032b7145e4b2572718c58ed9ed', 'google', 'Youth Children Camp Camp', NULL, '2024-06-19', '2026-06-28 22:17:29', '2026-07-01 08:13:51'),
(23520, 594, NULL, 'Анатолий Анатолиевич', NULL, 0, NULL, NULL, 0.00, 2, NULL, 'Повністю незадоволений. Дзвоню вже сто разів. Ігнорують. Дуже багато в них справ. Обманюють і говорять, що все добре. Але коли починаю давить кажуть що не справляються бо набралися багато справ. І гроші не віддають. Не звязуйтесь.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-05-24 00:00:00', NULL, '427ffa8839d3b1bd92a149d929fd278a693eb331', 'google', 'Анатолий Анатолиевич', NULL, '2024-05-24', '2026-06-28 22:17:29', '2026-07-01 08:13:51'),
(23521, 594, NULL, 'Наталя', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обслуговування було дуже професійним і допомогло мені вирішити мої юридичні питання ефективно та безпечно.Переваги: якість , ціна , постійний звʼязок та професіоналізм юристів. Рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-09-05 00:00:00', NULL, 'af438a26d6b27e8ba619d315b153dcd76e1e5eba', 'google', 'Наталя', NULL, '2023-09-05', '2026-06-28 22:17:29', '2026-07-01 08:13:51'),
(23522, 594, NULL, 'Софія', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Розібрались в питанні, не дорого по вартості. Повернули з ними виплати брату військовослужбовцю. Можу рекомендувати своїм знайомим, все чесно і відкрито в процесі роботи', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-09-01 00:00:00', NULL, 'ed923ca0a565b2206f979a59237dfba0e6da9a43', 'google', 'Софія', NULL, '2023-09-01', '2026-06-28 22:17:29', '2026-07-01 08:13:51'),
(23523, 594, NULL, 'Олександр', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Співвідносно до ціни і якості послуг доволі добре. Оплату розбивали на аванс і по-результату, що дуже зручно. В процесі роботи інформували по основним змінам, рішення суду очікували трохи більше 2 місяців, довели до фактичного його виконання. Хотілось би звісно швидше, але з ПФУ довго чекали відповідь, адвокат самостійно туди не їздив, надсилав офіційний запит.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-09-01 00:00:00', NULL, 'f71dcfdd9273d103745a91e5f98ee72d8bb7c1d6', 'google', 'Олександр', NULL, '2023-09-01', '2026-06-28 22:17:29', '2026-07-01 08:13:51'),
(23524, 594, NULL, 'Виктория', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Працювали з цією. компанією, проблем не виникало. Процес вже завершили і результат отримали', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-09-01 00:00:00', NULL, '3fcf0664ded44463f8c996fdde7afbbf20738879', 'google', 'Виктория', NULL, '2023-09-01', '2026-06-28 22:17:29', '2026-07-01 08:13:51'),
