(23526, 594, NULL, 'Валерій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мережа права то любофф! Висококваліфікована компанія з гарними рейтингами, Мережа права на стороні простих людей!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-08-07 00:00:00', NULL, '8ecbb1faca4c801108528a8132de971c64b0b602', 'google', 'Валерій', NULL, '2023-08-07', '2026-06-28 22:17:30', '2026-07-01 08:13:51'),
