(30912, 1044, NULL, 'Ariana', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обратилась по совету знакомых для раздела имущества с мужем-немцем. Честно, больше всего переживала из-за документов и апостилей. В итоге всё сделали сами, меня не дергали лишний раз — только подписи ставила. Суд выиграли, результат такой, как и обсуждали с самого начала.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-18 00:00:00', NULL, '5cd4969e6b09d6618701aa23c1fc33cd264c5f9b', 'google', 'Ariana', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValU0Vlo1ZFZpVUk2T3JlQzNjSU5mc2l0M2d0OWFhUlJzN2FOc0kxNnpKR2dTZV9hd1U9czEyMC1jLXJwLW1vLWJyMTAw.jpeg?expires=2098363267&signature=44b8f26af0708ec788ff49b63785db8a5915e71cfadd1f50a8011e2089ce6a50', '2026-03-18', '2026-06-29 14:41:31', '2026-06-29 14:43:28'),
(30913, 1044, NULL, 'Юлия Довгошей', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обратилась по рекомендации знакомых для раздела имущества с мужем-немцем. Больше всего боялась этих бесконечных пересылок документов через границу и апостилей. Компания всё взяла на себя, мне нужно было только ставить подписи. Суд выиграли, имущество разделили так, как и договаривались на первой консультации.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-18 00:00:00', NULL, '10c9951f86db9716520139e581ad221782f599d6', 'google', 'Юлия Довгошей', NULL, '2026-03-18', '2026-06-29 14:41:31', '2026-06-29 14:43:28'),
