(32485, 552, NULL, 'Vira Bogaichuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'ХОЧУ ЗАЛИШИТИ ПОЗИТИВНИЙ ВІДГУК, ПРО КОНСУЛЬТАЦІЮ В ГАЛИНИ БОГДАНІВНИ, ПРИЄМНО ВРАЖЕНА ЗНАННЯМИ ТА КОМУНІКАЦІЄЮ ДАНОГО ЮРИСТА, РЕКОМЕНДУЮ ВИРІШУВАТИ СВОЇ СПАДКОВІ ПИТАННЯ В ДАНОГО ЮРИСТА, ТЕ ЩО НЕ МОГЛА ВИРІШИТИ ЗА 30 РОКІВ СТАЛО ЗРОЗУМІЛИМ НАПРОТЯЗІ 30 ХВИЛИН. ДУЖЕ ДЯКУЮ.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-17 00:00:00', NULL, 'd67b21fade18604ca4dbc5b61bb63fd409fe1f9f', 'google', 'Vira Bogaichuk', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSWJjc19Ua3VLREEwLVRnMkZ3RnVPNk1zSUtjTi1meDNPWlV4aHBVOS05aGRFd0lBPXMxMjAtYy1ycC1tby1icjEwMA==.jpeg?expires=2098442834&signature=8bbb512ef0c7e4910a98fb1d4c882a97879bec5fe25f146d6bdcc9590ae20bf7', '2026-04-17', '2026-06-30 12:48:16', '2026-07-02 12:18:54'),
