(33632, 1066, NULL, 'Oksana Cherkas', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Юлія - це один з найкращих адвокатів. Крім того , що професіонал у своїй справі, вона розумна, справедлива. І , найважливіше у нас час, людяна та співчутлива. Працювати з нею - задоволення.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-11-29 00:00:00', NULL, '234eff415bc752750adf5155f16d96846901037e', 'google', 'Oksana Cherkas', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSzhZMnZlbG1zQ0J2RDZvbUItVTFpbzNQak1wYnEtd1RsR3M4YnZBMmVfQmtzc0RRPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098443107&signature=5ffc2b92ed4c602e848bbaf37441e658c35a8a2e9fb0497315b8feff4eb7dea0', '2023-11-29', '2026-06-30 12:51:50', '2026-06-30 12:51:50'),
(33633, 1067, NULL, 'Lilija Jarovicka', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити свою щиру вдячність адвокату Віктору, за його допомогу в отриманні відстрочки від мобілізації. Віктор професіонал своєї справи, який поставився до моєї справи з великою увагою та розумінням. Його глибокі знання у правовій сфері та чітке пояснення всіх необхідних процедур допомогли швидко отримати бажаний результат. Доречі, до цього я також співпрацювала з іншими адвокатами, але жоден з них не надав мені стільки інформації, як Віктор. Дякую за вашу підтримку та високий рівень професіоналізму!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-07-30 00:00:00', NULL, '172cccc094bd496e4ba1e889408cd39f4b115375', 'google', 'Lilija Jarovicka', NULL, '2024-07-30', '2026-06-30 12:51:53', '2026-06-30 12:51:54'),
(33634, 1067, NULL, 'Роско Острів', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Порядний, людяний. Гарно консультує. Рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-07-13 00:00:00', NULL, 'ecc8fce7f15e97294b155d78b7cec323414feb93', 'google', 'Роско Острів', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jTGNIVDU0Yms2S2FfZGMyMktyczExOXAzQ19fcElmVTBfTV93ZXpvNGNLPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098443112&signature=1e76356b499255fdc9da382509f5a375265c34eaf475a6adbf99fbd113f67c55', '2023-07-13', '2026-06-30 12:51:53', '2026-06-30 12:51:54'),
