(33643, 1068, NULL, 'Юра', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Сміло рекомендую…досвідченні адвокати, послуги надані на високому рівні.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-11-02 00:00:00', NULL, '6a2e6c6a3fb0f9ee26def8e58790602f52dfb173', 'google', 'Юра', NULL, '2021-11-02', '2026-06-30 12:51:57', '2026-06-30 12:51:57'),
(33644, 1068, NULL, 'Людмила Адамчук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Не один раз зверталася за правовою допомогою. Дуже вдячна Вам якісно та своєчасно виконану роботу, конструктивний підхід до вирішення кожного питання та уважність до деталей. Рекомендую усім!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-30 00:00:00', NULL, '574c3e035f23c1360e73b7efefa8406f76673546', 'google', 'Людмила Адамчук', NULL, '2021-10-30', '2026-06-30 12:51:57', '2026-06-30 12:51:57'),
(33645, 1068, NULL, 'Roman', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професіонали своєї справи, допомогли ефективно вирішити проблеми зі спадщиною...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-28 00:00:00', NULL, 'dbc85f0e3275568cc101f4c8175f585a092b78e6', 'google', 'Roman', NULL, '2021-10-28', '2026-06-30 12:51:57', '2026-06-30 12:51:57'),
(33646, 1068, NULL, 'Іryna', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Потрапила у ДТП. До адвоката звернулася за порадою знайомих. Допоміг грамотно підготувати необхідні документи, а також зібрати потрібні докази. В результаті я отримала від страхової відшкодування усіх заподіяних мені збитків. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-10-01 00:00:00', NULL, '6ed79467f301c4cd82dd38fdd0b6b2b96657ad56', 'google', 'Іryna', NULL, '2021-10-01', '2026-06-30 12:51:57', '2026-06-30 12:51:57'),
(33647, 1068, NULL, 'Олег', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Професійний адвокат, рекомендую! Швидко та без додаткових проблем допоміг вирішити кредитний спір.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-09-30 00:00:00', NULL, '7fe9e8b8230ec883e903e1d704b670c1c31710dd', 'google', 'Олег', NULL, '2021-09-30', '2026-06-30 12:51:57', '2026-06-30 12:51:57'),
(33648, 1069, NULL, 'Oleksandra Vdovina', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро вдячні за підтримку, професіоналізм та небайдужість. З першого спілкування стало зрозуміло, що маємо справу з досвідченим спеціалістом, який впевнено орієнтується у своїй сфері та вміє знаходити рішення навіть у складних ситуаціях. Приємно вразили уважність, терпіння та готовність детально відповідати на всі запитання. Дуже цінуємо відповідальний підхід і щире бажання допомогти.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-05 00:00:00', NULL, 'd262fdcbb172131c8e61a37c0fcf71f66f161e20', 'google', 'Oleksandra Vdovina', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jS1Z2Y3RTeUFNT3o3MW5MMldqa1N4bXdFMmgza3pZb2xlMzR3eGdNUkJWYTRlcTZRPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098443119&signature=ca3b421a7b6a186ae340e9941e5ce80556acdebff7a8e29453331ba61799c2cf', '2026-03-05', '2026-06-30 12:52:00', '2026-06-30 12:52:01');
