(34636, 1153, NULL, 'Тимур', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Прекрасный адвокат. Честный, конкретный и вообще трудяжка. Всегда на связи, воды не льет, слова с делом не расходятся, а это в наше время очень важно. Сотрудничаем уже 4 года, на протяжении которых мысли о замене адвоката меня ни разу не посетили. Сейчас таких профи действительно немного. Галина, спасибо Вам огромное. Работаем)', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-07-02 00:00:00', NULL, '26963f3a9a651b36c14d9d5715c0f6517ace3681', 'google', 'Тимур', NULL, '2020-07-02', '2026-06-30 15:02:26', '2026-06-30 15:02:28'),
(34637, 1153, NULL, 'Андрій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Галина Анатоліївна найкращий адвокат для вирішення податкових спорів. Мав дуже складне питання з нашою податковою, завдяки зусиллям і праці адвоката, все вирішили. Чесно кажучи навіть не очікував такого результату. Якщо у вас податкова перевірка або вже її наслідки, рекомендую даного адвоката!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-07-01 00:00:00', NULL, '41fc8c1e887e9df3537a047ccc5c1daa18fd49b8', 'google', 'Андрій', NULL, '2020-07-01', '2026-06-30 15:02:26', '2026-06-30 15:02:28'),
