(34641, 1153, NULL, 'Роман Витальевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Галина Анатоліївна хочу висловити Вам щиру подяку за якісну роботу, високий професіоналізм, тактовність, відповідальність, порядність і справедливість!!! Нехай Господь Вам допомагає і захищає!!!!! Всім раджу, не пошкодуєте!!! Це знавець своєї справи, людина з високим інтелектом і професійними здібностями!!! З повагою Роман Ганушкевич', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-06-23 00:00:00', NULL, '6a0de34debc5e0f30b5b5ec8bb9e76e598114de5', 'google', 'Роман Витальевич', NULL, '2020-06-23', '2026-06-30 15:02:27', '2026-06-30 15:02:28'),
