(34650, 1153, NULL, 'Михайло', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Галина Анатоліївна професіонал в своїй сфері. Дуже задоволений її роботою, а результатом її роботи ще більше.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-06-19 00:00:00', NULL, '026aa233055cfd863890c1ed680d607791360abe', 'google', 'Михайло', NULL, '2020-06-19', '2026-06-30 15:02:28', '2026-06-30 15:02:28'),
(34651, 1153, NULL, 'Марія', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Компетентний фахівець та порядна людина,надасть консультацію та зрозуміло і внятної відповість на усі запитання.щиро дякую за надані послуги та у вирішенні мого питання.Ви справжній професіонал,я дуже задоволена Вашою работою.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2020-06-19 00:00:00', NULL, '25230bb9d8ed906c298f958a01d3f015d64b9c90', 'google', 'Марія', NULL, '2020-06-19', '2026-06-30 15:02:28', '2026-06-30 15:02:28'),
