(34907, 1220, NULL, 'Петро', NULL, 0, NULL, NULL, 0.00, 2, NULL, 'Спочатку наче гарно співпрацювали, але на жаль довелось шукати більш якісних спеціалістів.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-12-15 00:00:00', NULL, 'abb9c1f18370c2a133e4b3dbbdf126a17b335895', 'google', 'Петро', NULL, '2016-12-15', '2026-06-30 15:37:46', '2026-06-30 15:37:47'),
(34908, 1220, NULL, 'Александр', NULL, 0, NULL, NULL, 0.00, 3, NULL, 'Благодарю данной организации за юридическую помощь в оформлении необходимых документов.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-12-15 00:00:00', NULL, 'fdf0ade64b6824fb0ed372ba518bc3d8b6400b24', 'google', 'Александр', NULL, '2016-12-15', '2026-06-30 15:37:47', '2026-06-30 15:37:47'),
(34909, 1220, NULL, 'Denny Crane', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'В місцевому суді я сама представляла свої інтереси і програла. Продовжити боротьбу в апеляційному суді вже довірила цій компанії. Рішенням апеляційного суду була змінена стаття звільнення, виплачено грошову компенсацію за вимушений прогул і за моральну шкоду. Задоволена компетентністю та надійністю адвокатів.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-02-10 00:00:00', NULL, 'bcc830854480d3b5fd0df0211992a961b3203f81', 'google', 'Denny Crane', NULL, '2016-02-10', '2026-06-30 15:37:47', '2026-06-30 15:37:47'),
(34910, 1258, NULL, 'Клієнт ****7402', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу щиро подякувати адвокату Сьорі Оксані Миколаївні за професіоналізм, відповідальність та підтримку. Завдяки її грамотній роботі, уважності до деталей і наполегливості вдалося досягти справедливого результату у моїй справі. Протягом усього процесу Оксана Миколаївна завжди була на зв’язку, детально пояснювала кожен крок і вселяла впевненість. Дуже вдячна за її працю, людяність та щире бажання допомогти. Від усього серця рекомендую Сьору Оксану Миколаївну як висококваліфікованого, чесного та надійного адвоката!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-28 00:00:00', NULL, '48aef1f9f9a9cc88c1b137ac568a09d9ff6cf5b5', 'google', 'Клієнт ****7402', NULL, '2026-06-28', '2026-06-30 15:49:34', '2026-06-30 15:49:39'),
(34911, 1258, NULL, 'Клієнт ****1192', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Все сподобалось, Сьора Оксана Миколаївна компетентний адвокат, дуже допомогла!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-18 00:00:00', NULL, '8270180e047622ef896c180f82cede77625f0085', 'google', 'Клієнт ****1192', NULL, '2026-05-18', '2026-06-30 15:49:34', '2026-06-30 15:49:39'),
(34912, 1258, NULL, 'Марина Бындыч', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу щиро подякувати Сьорі Оксані Миколаївні за професіоналізм, підтримку та перемогу в моїй справі. Майже два роки ми з чоловіком не могли оформити усиновлення мого сина й постійно отримували відмови. Здавалося, що це кінець. Завдяки її грамотній роботі та наполегливості суд ухвалив позитивне рішення, і наша сім’я офіційно стала повною. Безмежно вдячна й від щирого серця рекомендую як сильного фахівця та людину, якій можна довіряти! 😍', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-01 00:00:00', NULL, 'ed8d836218664cf772fb611086a13748fa37e4e1', 'google', 'Марина Бындыч', NULL, '2026-03-01', '2026-06-30 15:49:34', '2026-06-30 15:49:39'),
(34913, 1258, NULL, 'Natalka Levus', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу щиро подякувати Оксані Миколаївні за її кропітку працю! Завдяки її професіоналізму, досвіду та індивідуальному підходу до справи, я отримала результат за декілька місяців. Результат, якого не могла досягнути роками з іншими адвокатами. Окремо хочу відзначити людяність, чуйність та підтримку на всіх етапах. Рекомендую усім!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-08 00:00:00', NULL, '590434c7f1fadc825ba6b62fe4deaa078bf62cdb', 'google', 'Natalka Levus', NULL, '2026-02-08', '2026-06-30 15:49:34', '2026-06-30 15:49:39'),
(34914, 1258, NULL, 'Клієнт ****6073', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу подякувати Оксані Миколаївні за кваліфіковану допомогу і ведення моєї справи в суді,і доведення її до позитивного фінального завершення.Рекомендую всім кому потрібен професіонал у вирішенні юридичних питань.Я задоволений результатом!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-12-03 00:00:00', NULL, '9b89fe769d3f74974e74d2324dd64790d6a0b648', 'google', 'Клієнт ****6073', NULL, '2025-12-03', '2026-06-30 15:49:34', '2026-06-30 15:49:39'),
(34915, 1258, NULL, 'Клієнт ****2862', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити щиру та глибоку подяку Сьорі Оксані Миколаївні за її професіоналізм, людяність і неймовірну відданість своїй роботі. З першої консультації стало зрозуміло, що я звернувся саме до тієї людини, яка здатна взятися навіть за найскладніші справи та довести їх до результату. Адвокат оперативно та грамотно допомогла вирішити питання про зняття з розшуку в ТЦК, взяла на себе весь супровід документів і комунікацію з відповідними установами. Завдяки її досвіду та наполегливості питання, яке здавалося майже безвихідним, було вирішене максимально швидко та з мінімальними хвилюваннями для мене. Окремо хочу відзначити її роботу в цивільному процесі щодо отримання опікунства. Підготовка документів, пояснення кожного кроку, підтримка на всіх етапах та продумана стратегія дали мені впевненість і спокій. Я відчував, що поруч фахівець, який по-справжньому зацікавлений у позитивному результаті та робить усе, аби захистити мої інтереси. Її відповідальність, уважність до деталей і щире ставлення до клієнта заслуговують найвищої оцінки. Дуже рекомендую цього адвоката всім, хто шукає не лише кваліфіковану юридичну допомогу, а й підтримку, розуміння та впевненість у результаті.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-11-30 00:00:00', NULL, '345c62117b5f528de533cf0d617cad38e87aa50b', 'google', 'Клієнт ****2862', NULL, '2025-11-30', '2026-06-30 15:49:35', '2026-06-30 15:49:39'),
(34916, 1258, NULL, 'Chilly C', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Компетентний адвокат. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-11-04 00:00:00', NULL, '64b90f47c555a8414e5126557e5029ebba6574b2', 'google', 'Chilly C', NULL, '2025-11-04', '2026-06-30 15:49:35', '2026-06-30 15:49:39'),
(34917, 1258, NULL, 'Клієнт ****4538', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Завдяки \"любим\" родичам та відмові нотаріуса, в мене вже опускалися руки у прийнятті спадщини. Проте завдяки професіоналізму Оксани Миколаївни через суд поновлено мої спадкові права. Дякую Вам Оксана Миколаївно за все, що для мене зробили та не дай Боже нікому таких родичів як у мене. Кайдашева сім\'я відпочиває', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-28 00:00:00', NULL, '8bb8b0bd37520f372963bf2b2995709cde12b425', 'google', 'Клієнт ****4538', NULL, '2025-10-28', '2026-06-30 15:49:35', '2026-06-30 15:49:39'),
