(36197, 1291, NULL, 'Виктор', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Решил вопрос быстро и очень качественно. Все на высшем уровне. Большая благодарность вам за вашу работу!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-09-26 00:00:00', NULL, '6a018dcce61f1fab85985db1c988e6cb3dca6e09', 'google', 'Виктор', NULL, '2023-09-26', '2026-06-30 15:58:03', '2026-06-30 15:58:08'),
(36198, 1291, NULL, 'Віктор', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую Вам за дуже кваліфіковану допомогу у вирішенні проблеми надзвичайної складності! Ви професіонал з великої літери.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-09-05 00:00:00', NULL, 'ad8515fc6397319f59465dd5d367d90b754faad4', 'google', 'Віктор', NULL, '2023-09-05', '2026-06-30 15:58:03', '2026-06-30 15:58:08'),
