(36404, 1293, NULL, 'Марія Волк', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую. Звертаюсь вже другий раз. Оперативний вихід на з\'язок, докладна консультативна допомога. Тут дійсно високі професіонали', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-06-27 00:00:00', NULL, '9e41fac5f2d5775615a639ac49e1021ea295cff2', 'google', 'Марія Волк', NULL, '2024-06-27', '2026-06-30 15:58:47', '2026-06-30 16:03:26'),
