(36421, 1293, NULL, 'Аnn Bast', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Добрий день, повністю задоволена послугами компанії \"Правда\". Знаходячись за кордоном, отримала розлучення в Україні. Співробітниця компанії , з якою спілкувались в процесі, все добре пояснювала, відповідала професійно на всі мої запитання. Дякую за якісно виконану роботу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-05-23 00:00:00', NULL, '4e6502ed32b56e0f2b37b731cbb6c645496eddab', 'google', 'Аnn Bast', NULL, '2024-05-23', '2026-06-30 15:58:50', '2026-06-30 16:03:26'),
