(36425, 1293, NULL, 'Дмитрий Шаула', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Заплатив за послуги з розлучення 3000 грн - все виконали професійно. Швидко склали позов і через місяць суд ухвалив рішення про розлучення.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-05-16 00:00:00', NULL, '31e3fd91474523fa48a9cf2a506f143c369e3498', 'google', 'Дмитрий Шаула', NULL, '2024-05-16', '2026-06-30 15:58:50', '2026-06-30 16:03:26'),
