(36435, 1293, NULL, 'Kolya Drach', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звертався за допомогою , щоб розлучитись . Знаходжусь за кордоном, вирішили дане питання дуже швидко та легко без моєї участі. Дуже вдячний.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-30 00:00:00', NULL, '1ec70d23ec973f4ee0e07e6fb1c14b508a45e5bc', 'google', 'Kolya Drach', NULL, '2024-04-30', '2026-06-30 15:58:52', '2026-06-30 16:03:26'),
(36436, 1293, NULL, 'Serhii andriuschcenko', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обратился в адвокатское бюро Правда, Юлия Александровна занималась моим разводом дистанционно, так как я нахожусь за границей, все зделали качественно быстро, цена удовлетворительная не дорого, всегда меня держала в курсе, звонила писала во время процесса, я очень доволен рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-24 00:00:00', NULL, '30add177c9576188f0c74d836d90c0e6a0348bc5', 'google', 'Serhii andriuschcenko', NULL, '2024-04-24', '2026-06-30 15:58:52', '2026-06-30 16:03:26'),
(36437, 1293, NULL, 'таміла Плохань', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась за допомогою до Адвокатського Об\'єднання \"Правда\", з приводу розірвання шлюбу. Обслуговування було дуже професійним і допомогли мені швидко розірвати шлюб. Переваги: якість , ціна , постійний звʼязок та професіоналізм юристів. Рекомендую. Хочу відзначити доброзичливість, тактовність, порядність та надійність, отримала грамотні, чіткі відповіді на свої питання.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-22 00:00:00', NULL, '5edba498d4ba6a6affb7a10b6f34cd9e645062cb', 'google', 'таміла Плохань', NULL, '2024-04-22', '2026-06-30 15:58:52', '2026-06-30 16:03:26'),
(36438, 1293, NULL, 'Карина Чумаченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась до Адвокатського обʼєднання Правда за юридичною допомогою з приводу розлучення. Я знаходжусь закордоном, а мій чоловік не хотів розлучатися. Юристи кваліфіковано, якісно та швидко вирішили моє питання. Все щоб було потрібно від мене це підписати договір, все інше було зроблено без моєї участі. Та без згоди мого чоловіка! Юристи отримали рішення суду по моїй справі так ще й зробили процедуру апостилювання в найкоротші терміни. Це дуже зручний сервіс, бо можна зробити все разом і не потрібно шукати інших спеціалістів! І ціни дійсно найдешевші по всій Україні!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-22 00:00:00', NULL, 'd89b76fec51320f91255b37ef3c4c2553e311b86', 'google', 'Карина Чумаченко', NULL, '2024-04-22', '2026-06-30 15:58:52', '2026-06-30 16:03:26'),
(36439, 1293, NULL, 'Julia Ivon', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернулась до адвокатського об’єднання «Правда», так як шляхом перекредитування потрапила до боргової ями, усі гроші витрачала на погашення відсотків, але борги не зменшувалися. Співпрацею дуже задоволена, адвокати компанії допомогли списати відсотки та закрити кредити за адекватними цінами👌🏻', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-22 00:00:00', NULL, 'd4a4b613a4a2b18b3b94678d65037b0393f7c015', 'google', 'Julia Ivon', NULL, '2024-04-22', '2026-06-30 15:58:52', '2026-06-30 16:03:26'),
(36440, 1293, NULL, 'Maria Murashkina', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталась до Адвокаського об\'єднання Правда за допомогою по кредитам. Вже навіть не знала в кого просити допомоги... Юристи справжні професіонали! Дуже допомогли закрити кредити по вигідним умовам. Буду рекомендувати знайомим..', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-22 00:00:00', NULL, 'ad2c36c8d4be48bd0d3f11dd0bef44c1a0803ac7', 'google', 'Maria Murashkina', NULL, '2024-04-22', '2026-06-30 15:58:52', '2026-06-30 16:03:26'),
(36441, 1293, NULL, 'Аліна Дем\'янюк', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Необхідно було отримати дублікати свідоцтв та апостилювати, я знаходжусь закордоном і мені допомогли все зробити дистанційно, під час співпраці постійно сповіщали на якому етапі документи, відповідали на всі мої запитання. Команда справжніх професіоналів, сервіс на вищому рівні та зробили все за дуже приємною ціною. Дякую, що працюєте та допомагаєте у такий складний час! Бажаю процвітання вашій компанії та буду рекомендувати вас!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-22 00:00:00', NULL, '1f6c634a723431226696dc2f63f0fa36a71d024e', 'google', 'Аліна Дем\'янюк', NULL, '2024-04-22', '2026-06-30 15:58:52', '2026-06-30 16:03:26'),
(36442, 1293, NULL, 'Влад Власта', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталися до цього обʼєднання з приводу розлучення. Дуже сподобався сервіс. Вони дійсно дуже швидко та за адекватну ціну розірвали шлюб. А саме головне що отримали самі рішення суду та надіслали мені його з подарунком. Це було дуже приємно та несподівано. Я рекомендую цю компанію. Справжні професіонали своєї справи. Постійно тримали мене в курсі справи . Молодці, побільше таких компаній.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-22 00:00:00', NULL, '5cfc2ed8ab639e011f982435479d8f157b79b710', 'google', 'Влад Власта', NULL, '2024-04-22', '2026-06-30 15:58:53', '2026-06-30 16:03:26'),
(36443, 1293, NULL, 'Надія Корольова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу подякувати адвокатському об\'єднанню \"Правда\" за допомогу і підтримку (юридичну і психологічну). Звернулась в компанію за консультацією щодо розірвання шлюбу. І отримала детальне роз\'яснення і покрокову інструкцію щодо необхідних документів для оформлення позовної заяви та порядок дій. А головне - підтримку на всіх етапах співпраці. При чому, перебуваючи за кордоном з дітьми, отримала професійну допомогу адвоката без можливості особистої присутності на судовому засіданні. Вітаю з успішно виграною справою. Дякую за співпрацю, ваш професіоналізм та увагу до клієнтів! Успіхів та процвітання вашій компанії!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-04-22 00:00:00', NULL, '5af65e42574bcbc37b00954536b1706980fb690e', 'google', 'Надія Корольова', NULL, '2024-04-22', '2026-06-30 15:58:53', '2026-06-30 16:03:26'),
(36444, 1294, NULL, 'Anna Ivleva', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернулася за рекомендацією та залишилася дуже задоволена! Якісний підхід до справи. Розібралися із запитом швидко. Довіра з першої зустрічі! 🙂…', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-03-15 00:00:00', NULL, 'a048a5a51d88a171eb114eb5cc85f079e1281d9b', 'google', 'Anna Ivleva', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jS3JIUmtsMEZxQW9aRnRfX3dmTXk2X19pLVdZZ1BDYllNMk93eXdVUTBZT3NIZUxBPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098454334&signature=a2fbb7dbca3b2203b6b3b25b34d46e7d8eaaa26de4dcf8849b88dc90cefa4e3e', '2026-03-15', '2026-06-30 15:58:59', '2026-06-30 15:59:07'),
(36445, 1294, NULL, 'Lilia Taran', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити щиру вдячність адвокату Юрію Голосову та юридичній фірмі \"Нікітінський і Партнери\" за неоціненну допомогу у моїй надзвичайно складній справі щодо міжнародного викрадення дітей. Коли я опинилася у цій критичній ситуації, мені потрібен був не просто юрист, а справжній професіонал, який розуміє тонкощі сімейного права та міжнародних конвенцій. Юрій проявив себе як висококваліфікований спеціаліст, який діє рішуче, оперативно та з глибоким знанням справи. Його підхід — це поєднання холоднокровної стратегії та справжньої людської підтримки. Він завжди на зв’язку, детально пояснює кожен крок і дає впевненість у тому, що справедливість буде відновлена. Якщо ви шукаєте надійного захисника у найскладніших сімейних спорах, щиро рекомендую звертатися саме до Юрія Голосова. Це людина, якій можна довірити найцінніше — безпеку та майбутнє своєї родини. Дякую за вашу працю!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-05 00:00:00', NULL, '82b9b286ed653cab8fdd7919ae0a988be7326d4a', 'google', 'Lilia Taran', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValdScVhFNUZveENmSmk4ZWdudDhfUE5oU0NCSWZtdEZ3bUdwOWZRMS1md2FrLWhhTDdpPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098454334&signature=9a0473be98a060483520c6408e4f0b13adbb78c125e84e1e604908f15e75c62b', '2026-02-05', '2026-06-30 15:58:59', '2026-06-30 15:59:07'),
(36446, 1294, NULL, 'Родідял Марина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щира подяка юристу Барвенко Ярославу Віталійовичу. Ми співпрацюємо вже понад рік і за цей час переконалися у його високому професіоналізмі та відповідальному підході до справи. Ярослав Віталійович надав кваліфіковану допомогу у складних питаннях, пов’язаних із військовою службою мого чоловіка: професійні консультації, грамотне складання документації та якісний юридичний супровід на всіх етапах. Саме завдяки його роботі нам вдалося досягти поставленої мети. Окремо хочу відзначити його надійність, щирість і порядність — це людина, якій справді можна довіряти. Плануємо й надалі продовжувати співпрацю та щиро рекомендуємо Ярослава Віталійовича як компетентного й відповідального адвоката.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-05 00:00:00', NULL, '14e556867ee49ffb0b22e8d7552a4146f28e1543', 'google', 'Родідял Марина', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValhmMTc1bkVudVZBTk5FMzlLNWtCTEpCSUJ3a1VMUTA3NGV1YnVNNnRLSXZ5OHFiZFJVRnc9dzMwMC1oMzAwLXAtcnAtbW8tYnIxMDA=.jpeg?expires=2098454334&signature=d4662dff57bd09b19571a408bcf4c534169621221691c2f3e1aa190fcfbd8063', '2026-02-05', '2026-06-30 15:58:59', '2026-06-30 15:59:07'),
(36447, 1294, NULL, 'Денис Иванченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Вищий пілотаж! Компетентність, професіоналізм,-поза, всякої конкуренції !!!. Дуже, приємно, здивований і дуже задоволений, швидкістю та результатом! Дякую величезне!!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-05 00:00:00', NULL, 'a9ad5b4a8f5682febfde5f91ac393a1b19aa79b3', 'google', 'Денис Иванченко', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSk1ldlJnZWc5YmFaS1M0RktUYzlPdUh1dVAxd1l1Z1dIcDNrWUIyRU02a25YN3BRPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098454334&signature=bc6574bb7b2b0cb0087d2fbad77f2523b273e26f2f526647c04f2d9d179f8e1f', '2026-02-05', '2026-06-30 15:58:59', '2026-06-30 15:59:07'),
(36448, 1294, NULL, 'Вадим Колесник', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Користувався послугами адвоката Ярослвава Барвенко. Він мене супроводжував впродовж 9 місяців поки я проходив ВЛК декілька разів. Висновок ВЛК 3 рази видавали мені з порушеннями (не правильна стаття), і Ярослав допоміг мені добитися виправлення цієї помилки. Діло дійшло майже до суду, але вийшло вирішити в досудовому порядку. Дякую за добру роботу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-05 00:00:00', NULL, '96e5b53db8aa6c349cc4df1c89d3fa0b18ce66d8', 'google', 'Вадим Колесник', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValdhRmU4bGNwM1JyOW1yakZncWxTcGQtWkEwNFpISmFaZ0xRamZzVjhWRTdGZnZLaU09dzMwMC1oMzAwLXAtcnAtbW8tYmEzLWJyMTAw.jpeg?expires=2098454334&signature=e99d4402eeda185b6519e7c2d01b1b594a362c9b1f71c6c23af8702a6c43ff79', '2026-02-05', '2026-06-30 15:58:59', '2026-06-30 15:59:07'),
