(36634, 1297, NULL, 'Оля Кудрявцева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую співробітникам агентства нерухомості за те що допомогли здійснити швидкий продаж квартири, угода була вигідною і мені навіть не довелося знижувати ціну.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, 'fdc181b67b9e8faaed3f771c13d5aa079ea5f77e', 'google', 'Оля Кудрявцева', NULL, '2018-10-17', '2026-06-30 15:59:43', '2026-06-30 15:59:47'),
(36635, 1297, NULL, 'Евгений Кравчук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Співробітники агентства Європа серйозно ставляться до своєї роботи! Якісно, швидко і професійно вирішують питання будь-якої складності! Всім раджу звертатися безпосередньо до них!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '8d5090e326eebe3830e1af7c66ead5d610cb033d', 'google', 'Евгений Кравчук', NULL, '2018-10-17', '2026-06-30 15:59:43', '2026-06-30 15:59:47'),
(36636, 1297, NULL, 'Ольга Полякова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую співробітникам компанії за те що допомогли знайти хороший варіант заміського будинку. Операція вже відбулася, всі необхідні документи теж для мене підготували.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '5f33e35ed67c52348671f38c1010636e1bc6cff1', 'google', 'Ольга Полякова', NULL, '2018-10-17', '2026-06-30 15:59:43', '2026-06-30 15:59:47'),
(36637, 1297, NULL, 'Сергей Вишняков', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу подякувати співробітників агентства нерухомості за те що проявили професіоналізм і оперативність при продажу моєї квартири. Угода виявилася для мене дуже вигідною.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '471393588dc767b2b55b9a5e417d7b3a659ce383', 'google', 'Сергей Вишняков', NULL, '2018-10-17', '2026-06-30 15:59:43', '2026-06-30 15:59:47'),
(36638, 1297, NULL, 'Петр Игнатьев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Через це агентство нерухомості брав собі квартиру. Операція була складною, тому що було 4 продавця. У підсумку угоду провели безпечно для мене і тепер у мене є свій квартира.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '2d904f4d81fe2944fcc388311045f92b73e64fa8', 'google', 'Петр Игнатьев', NULL, '2018-10-17', '2026-06-30 15:59:44', '2026-06-30 15:59:47'),
(36639, 1297, NULL, 'Витя Осипов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу подякувати це агентство нерухомості за те що допомогли знайти квартиру. Квартир в хорошому стані, коштує недорого. Та й сам процес угоди пройшов швидко і без проблем.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '4ebb7e4ff88562a4930f8e4b016fa3603619e8b9', 'google', 'Витя Осипов', NULL, '2018-10-17', '2026-06-30 15:59:44', '2026-06-30 15:59:47'),
(36640, 1297, NULL, 'Виктор Герасимов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую співробітникам агентства нерухомості за проявлений професіоналізм і оперативність. Клієнта для оренди квартири знайшли швидко. Знижувати ціну не довелося.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, 'f14d3990003a8d24d529e182d97b8bebd7b08d87', 'google', 'Виктор Герасимов', NULL, '2018-10-17', '2026-06-30 15:59:44', '2026-06-30 15:59:47'),
(36641, 1297, NULL, 'Илья Буров', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Агентство нерухомості сподобалося. Тут працюють професіонали. У короткі терміни мені підібрали квартиру, допомогли оформити всі необхідні документи до її купівлі.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '484d5b0bcd03c3e4b01acba460801fe1d66bb516', 'google', 'Илья Буров', NULL, '2018-10-17', '2026-06-30 15:59:44', '2026-06-30 15:59:47'),
(36642, 1297, NULL, 'Анна Исакова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Гарне агентство нерухомості, раджу сюди звертатися. Тут працюють фахівці хорошої кваліфікації. Швидко знайшли покупців на мою квартиру, допомогли з оформленням документів.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '8acd61405d70322b85ae8b4f795aa1a9ef59f399', 'google', 'Анна Исакова', NULL, '2018-10-17', '2026-06-30 15:59:44', '2026-06-30 15:59:47'),
(36643, 1297, NULL, 'Вадик Носков', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Гарне агентство нерухомості. Через нього купував квартиру. Сподобалося що знайшли багато відповідних варіантів, провели операцію, перевірили квартиру на юридичну чистоту. За це заплатив недорого, в інших агентствах подібні послуги коштують дорожче.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '5284edbd3d942926298229732242c21ea8f61a44', 'google', 'Вадик Носков', NULL, '2018-10-17', '2026-06-30 15:59:44', '2026-06-30 15:59:47'),
(36644, 1297, NULL, 'Вика Турова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Гарне агенство нерухомості, не в перший раз мені допомагають. В останнє звернення шукали мені квартиру на тривалий термін в оренду. Підібрали дуже хороший і недорогий варіант!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '7ec1a5268fc44352f6bf0911cf4bea741b5fee52', 'google', 'Вика Турова', NULL, '2018-10-17', '2026-06-30 15:59:44', '2026-06-30 15:59:47'),
(36645, 1297, NULL, 'Алина Толкина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Добре що є таке агентство нерухомості, якому можна довірити продаж своєї квартири. Угода відбулася швидко, на цілком прийнятних умовах. Мені самій нічого робити не довелося!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '0dc8dbee4807729b20b58bb52be50840e72f4295', 'google', 'Алина Толкина', NULL, '2018-10-17', '2026-06-30 15:59:45', '2026-06-30 15:59:47'),
(36646, 1297, NULL, 'Степан Потапов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мені потрібно було знайти покупця на мою квартиру. Займатися пошуком самостійно часу не було. Тут швидко знайшли покупця, комісія смішна. Плюс документи все оформили.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, 'a64214a8112bf91f00b21f364dcb133b70579e91', 'google', 'Степан Потапов', NULL, '2018-10-17', '2026-06-30 15:59:45', '2026-06-30 15:59:47'),
(36647, 1297, NULL, 'Иван Симонов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Саме в це агентство нерухомості я вирішив звернутися про рекомендації свого знайомого і залишився задоволений якістю обслуговування. У короткі терміни мені підібрали кілька варіантів на оренду квартири і допомогли скласти договір оренди. При пошуку врахували всі мої побажання. Такий сервіс мені до душі і я всім рекомендую звертатися в це АН', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '216503467fe9f92795bb72085f76649ebdc2e33d', 'google', 'Иван Симонов', NULL, '2018-10-17', '2026-06-30 15:59:45', '2026-06-30 15:59:47'),
(36648, 1297, NULL, 'Вика Беспалова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мені дуже сподобалося це агенство нерухомості, тому що у них зібрана велика база об\'єктів нерухомості і мені швидко знайшли однокімнатну квартиру в оренду. Окрема подяка співробітникам за професіоналізм і добре ставлення до клієнтів. мені приділили належну увагу, розпитали все і дали рекомендації з приводу договору оренди.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-10-17 00:00:00', NULL, '452c2838153c37a029394b248aceff2073ec5b27', 'google', 'Вика Беспалова', NULL, '2018-10-17', '2026-06-30 15:59:45', '2026-06-30 15:59:47'),
(36649, 1297, NULL, 'Марина Логинова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне очень понравилось это агенство недвижимости, именно тут мне смогли быстро подобрать квартиру для покупки. Мне нужна была однокомнатная квартира в центре города. за несколько дней мне нашли очень хорошие варианты под мои требования. В итоге вчера состоялась сделка. Проблем не возникло. Всем сотрудникам спасибо.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-07-06 00:00:00', NULL, 'fab6833e1721d52c389cc383af875c2237189095', 'google', 'Марина Логинова', NULL, '2018-07-06', '2026-06-30 15:59:45', '2026-06-30 15:59:47'),
(36650, 1297, NULL, 'Валерий Сысоев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне нужна была трехкомнатная квартира но времени на самостоятельные поиски не было. Да и так как рынок недвижимости вторичный. были опасения связанные с мошенниками. Решил обратиться в агенство недвижимости. Огромное спасибо сотрудникам за оперативный поиск квартиры и помощь в оформлении сделки. Все прошло успешно.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-07-05 00:00:00', NULL, 'acd75b19a5c3041ff5e0f8a789721baa0a8e3351', 'google', 'Валерий Сысоев', NULL, '2018-07-05', '2026-06-30 15:59:45', '2026-06-30 15:59:47'),
(36651, 1297, NULL, 'Лера Селиверстова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне очень понравилось это агенство недвижимости. Здесь большая база объектов, которая регулярно обновляется. Мне нужна была помощь в подборе квартиры на покупку, двушка. Требований было много но не смотря на это сотрудникам агенства удалось быстро подобрать мне интересные варианты. Сделка по покупке состоялась 2 дня назад.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-22 00:00:00', NULL, 'c96fef947619c44b88f705a5c85d3f7a9edc6f33', 'google', 'Лера Селиверстова', NULL, '2018-06-22', '2026-06-30 15:59:45', '2026-06-30 15:59:47'),
(36652, 1297, NULL, 'Юрий Емельянов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'В это агенство недвижимости обращался впервые. Хотелось бы сказать огромное спасибо за быстро оказанную мне помощь. Мне подобрали квартиру на покупку. Искал 3 комнатную квартиру. Предложенный объект недвижимости полностью соответствовал моим требованиям. Комиссия агенства была минимальной, это очень порадовало.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-22 00:00:00', NULL, '4d01de2939f1f77c402d9cb38e843ce57efe0711', 'google', 'Юрий Емельянов', NULL, '2018-06-22', '2026-06-30 15:59:46', '2026-06-30 15:59:47'),
(36653, 1297, NULL, 'Валя Григорьева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Нужна была помощь в поиске квартиры и последующем оформлении сделки купли продажи квартиры. Хорошо что обратилась именно сюда. Здесь работают профессионалы и база объектов недвижимости очень большая. Квартиру подыскали мне очень быстро. Сделку сопроводили без проблем. Проверили на юридическую чистоту. Подготовили документы.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-22 00:00:00', NULL, '87688b981a73dbd58ee9d06bdb7e00e55cb92de9', 'google', 'Валя Григорьева', NULL, '2018-06-22', '2026-06-30 15:59:46', '2026-06-30 15:59:47'),
(36654, 1297, NULL, 'Надя Комарова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне очень понравилось это агенство недвижимости. Здесь мне помогли найти квартиру в аренду. Причем поиск был осуществлен в довольно короткий промежуток времени. так же оказали помощь в оформлении договора аренды. Когда решусь на покупку квартиры то тоже обращусь сюда. База объявлений у них нереально большая.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-19 00:00:00', NULL, '5cb85794a71ea215d5261ea40c6bac2977646d19', 'google', 'Надя Комарова', NULL, '2018-06-19', '2026-06-30 15:59:46', '2026-06-30 15:59:47'),
(36655, 1297, NULL, 'Игорь Карпов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне очень понравилось это агенство недвижимости, потому что именно тут, благодаря большой базе объектов, мне подобрали красивую и просторную квартиру, которая полностью удовлетворяла моим требованиям. Сделку по покупке квартиры мне тоже помогли провести. Огромное спасибо за то что покупка квартиры была такой легкой.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-10 00:00:00', NULL, '2a5b066ca9a3403369fb22baf834cd2f1513bbc3', 'google', 'Игорь Карпов', NULL, '2018-06-10', '2026-06-30 15:59:46', '2026-06-30 15:59:47'),
(36656, 1297, NULL, 'Женя Самсонова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне очень понравилось это агенство недвижимости. Очень большая база объектов, которая постоянно пополняется. Мне надо было найти квартиру на длительную аренду, которая попадала бы под определенные критерии и специалисты компании очень быстро это сделали. Составили договор аренды. Комиссия за услуги была небольшой.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-10 00:00:00', NULL, 'c0c414a41b55bc2c3cb25f4ee4d8b520e0fdc481', 'google', 'Женя Самсонова', NULL, '2018-06-10', '2026-06-30 15:59:46', '2026-06-30 15:59:47'),
(36657, 1297, NULL, 'Вова Исаев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'В агенство недвижимости обращался за помощью в поиске трехкомнатной квартиры в городе Одесса. Остался доволен высоким уровнем обслуживания. Сотрудники агенства недвижимости нашли мне хорошие варианты, съездили со мной посмотрели их. Так же была оказана помощь в проведении сделки купли-продажи. Огромное спасибо.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-07 00:00:00', NULL, '3bb824bf8003fc4d9d3cbbb400f9bb03bb27ae30', 'google', 'Вова Исаев', NULL, '2018-06-07', '2026-06-30 15:59:46', '2026-06-30 15:59:47'),
(36658, 1297, NULL, 'John Stones', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне нужна была помощь в подборе квартиры на первичном рынке недвижимости и сопровождение сделки и я обратился в эту компанию. Огромное спасибо сотрудникам за оперативный поиск квартиры и подготовку документов купли-продажи. Сделка прошла легко и без проблем. Видно что работали профессионалы. Рекомендую всем.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-07 00:00:00', NULL, '2919b9e4cea6b099190c92da5bb42b40e6bb548c', 'google', 'John Stones', NULL, '2018-06-07', '2026-06-30 15:59:46', '2026-06-30 15:59:47'),
(36659, 1297, NULL, 'Степан Потапов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Мне нужно было найти покупателя на мою квартиру. Заниматься поиском самостоятельно времени не было. Здесь быстро нашли покупателя, комиссия смешная. Плюс документы все оформили.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-08-29 00:00:00', NULL, '6f81337d54aeadfae3b5e9909cd4cc30516e66f9', 'google', 'Степан Потапов', NULL, '2016-08-29', '2026-06-30 15:59:47', '2026-06-30 15:59:47'),
(36660, 1297, NULL, 'Анна Исакова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хорошее агентство недвижимости, советую сюда обращаться. Здесь работают специалисты хорошей квалификации. Быстро нашли покупателей на мою квартиру, помогли с оформлением документов.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-07-25 00:00:00', NULL, '238d83dfee5a6242f37f5537bb51038b485a2f04', 'google', 'Анна Исакова', NULL, '2016-07-25', '2026-06-30 15:59:47', '2026-06-30 15:59:47'),
(36661, 1297, NULL, 'Вика Турова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хорошее агенство недвижимости, не в первый раз мне помогают. В последнее обращение искали мне квартиру на длительный срок в аренду. Подобрали очень хороший и недорогой вариант!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-07-19 00:00:00', NULL, 'c2e57d2486a642f9feb15ca26d846c6e52c6ddb1', 'google', 'Вика Турова', NULL, '2016-07-19', '2026-06-30 15:59:47', '2026-06-30 15:59:47'),
(36662, 1297, NULL, 'Илья Буров', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Агентство недвижимости понравилось. Тут работают профессионалы. В короткие сроки мне подобрали квартиру, помогли оформить все необходимые документы к ее покупке.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-07-07 00:00:00', NULL, 'd36a755f3d843c5e1ddcc2b9dd76b614099f926e', 'google', 'Илья Буров', NULL, '2016-07-07', '2026-06-30 15:59:47', '2026-06-30 15:59:47'),
(36663, 1297, NULL, 'Виктор Герасимов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Спасибо сотрудникам агентства недвижимости за проявленный профессионализм и оперативность. Клиента для аренды квартиры нашли быстро. Снижать цену не пришлось.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-07-07 00:00:00', NULL, '6ab387afba1b3fa1ad235d082f950da79201a743', 'google', 'Виктор Герасимов', NULL, '2016-07-07', '2026-06-30 15:59:47', '2026-06-30 15:59:47'),
(36664, 1297, NULL, 'Алина Толкина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хорошо что есть такое агентство недвижимости, которому можно доверить продажу своей квартиры. Сделка состоялась быстро, на вполне приемлемых условиях. Мне самой ничего делать не пришлось!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-07-07 00:00:00', NULL, 'bbd3d51dded2b9129fbf5e69e528393adef50146', 'google', 'Алина Толкина', NULL, '2016-07-07', '2026-06-30 15:59:47', '2026-06-30 15:59:47'),
(36665, 1298, NULL, 'Алена', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Вкотре отримала якісну та професійну юридичну допомогу. Починаючи від супроводу правочину до отримання апостилів на документи та відправлення їх до Німеччини.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-13 00:00:00', NULL, '38ceb303b77232c2ab3f703e5988aadab820da26', 'google', 'Алена', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSVY1Yi1feUZ1MFBsYUUtVnBjei1hZG9PaTY3U1l5YXJsSWZSZXd5VmtzX2VETmZBPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098454388&signature=ae5a2d1ebfd5cc08dccb5363eab7336b3465fc3f09b3aac3d5b9ae311cc05966', '2026-02-13', '2026-06-30 15:59:52', '2026-06-30 15:59:55'),
(36666, 1298, NULL, 'Андрій Слободський', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити велику вдячність Ользі, за перемогу в суді. Завдяки вашій стратегії та впевненості ми отримали справедливе рішення. Професіоналізм на найвищому рівні. Якщо вам потрібен адвокат, який дійсно бореться за результат — звертайтеся саме сюди.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-13 00:00:00', NULL, '6055b4269824ea8b5aea4165eed44450567b1d27', 'google', 'Андрій Слободський', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValVzMmhDdWdvS3lBYWw1RmtZWWZ5NDZyM0d2dDZZNkJYanI4ZXZkNXRqZkJKTk9CbjFlYnc9dzMwMC1oMzAwLXAtcnAtbW8tYmEzLWJyMTAw.jpeg?expires=2098454388&signature=38f95fc7d95e982d32e1a15cb77bbdb526738770dc2004a44da3dd43ee1e76cd', '2026-01-13', '2026-06-30 15:59:52', '2026-06-30 15:59:55'),
(36667, 1298, NULL, 'САФ-Інжиніринг', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро дякую, за професійну допомогу та успішне вирішення питання. Дуже задоволений індивідуальним підходом, чіткістю в комунікації та глибоким знанням справи. Рекомендую як надійного фахівця!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-13 00:00:00', NULL, '639f1cc56b074212f477fa844299269de8989e54', 'google', 'САФ-Інжиніринг', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValVsOTdqeHRRU1c4N3ExQzRrVG1IUFIwR25Cc05uWkxDa05YMS1sN0lwbzVrWVp3Yjg9dzMwMC1oMzAwLXAtcnAtbW8tYnIxMDA=.jpeg?expires=2098454388&signature=69df520b2b082c3d00d5f97e2ca75241467983e29f91cb47bd86bf880f5192e3', '2026-01-13', '2026-06-30 15:59:52', '2026-06-30 15:59:55'),
(36668, 1298, NULL, 'Ирина Подолян', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро дякую адвокату Ользі Вікторівні за професійну та відповідальну роботу у справі про розірвання шлюбу. Вона є компетентним фахівцем: мені усе було чітко пояснено і зрозуміло. Ольга Карпова завжди була на зв’язку, оперативно відповідала на запитання. Я повністю задоволена результатом, тому можу без зайвих вагань рекомендувати її всім, хто шукає надійного, уважного та професійного адвоката.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-13 00:00:00', NULL, 'ab5b29a2547bf72507f91103a0f1801b337e9299', 'google', 'Ирина Подолян', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSXNBN2RWVWIwN2NBOUtkVVBEbVVZRWF4eTdNYzE1XzBCVEJRTm9uWUxPcjFvQmd3PXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098454388&signature=09c8124ea844a03bb8935ccdfefc81f7439548e9307428931a885b25dc8cb5b9', '2026-01-13', '2026-06-30 15:59:52', '2026-06-30 15:59:55'),
(36669, 1298, NULL, 'Elmar Useynov', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Гарне і чітке обслуговування, ні якої затримки в документах. Рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-01-13 00:00:00', NULL, '5289dc3ab9315ba1cfb603cc8e84a134000842a3', 'google', 'Elmar Useynov', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jTEFuamlvN25LZURuX0Z2WkdKZWt2MmtiekN5UWFFOGhmSVo0eG5WZ0tRSTFseFBRPXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098454388&signature=b017e25dcc87f05104b2756cb163c5c5eeb587dae73205f5442d81295a05acb0', '2026-01-13', '2026-06-30 15:59:52', '2026-06-30 15:59:55'),
