(36721, 1299, NULL, 'Paul G', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Шукали фірму, щоб узаконити побудовані без відповідних дозволів будинок і господарські споруди. Вартість оформлення документів у Євгена виявилася однією з найнижчих. При особистій зустрічі Євген відразу викликав ...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-09-03 00:00:00', NULL, '270c606c0fa1329441ced77a9dcbc1b2d408245d', 'google', 'Paul G', NULL, '2018-09-03', '2026-06-30 16:00:04', '2026-06-30 16:00:04'),
(36722, 1299, NULL, 'Мария Кодымская', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталася до Євгена по-приводу розлучення і розділу майна. Колишній чоловік намагався майно нажите в шлюбі перепродати без мого відома. Євген оперативно наклав арешт на все наше майно, а потім розділив його між мною ...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-09-03 00:00:00', NULL, '0fe4892c43fea17dbf6e8863f869519a78929c31', 'google', 'Мария Кодымская', NULL, '2018-09-03', '2026-06-30 16:00:04', '2026-06-30 16:00:04'),
(36723, 1299, NULL, 'Ксения Лазарева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити Величезну Подяка Євгену Шамильевич !!! Я Дуже рада що саме Він зайнявся і Довів до завершення наші Дуже важкі і заплутані справи. Він Професіонал Своєї Справи! Дуже Чуйний і Уважний людина! Якби не він ...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-09-03 00:00:00', NULL, 'fb43e6635f5295cade8af7fde434e8dabf1c8188', 'google', 'Ксения Лазарева', NULL, '2018-09-03', '2026-06-30 16:00:04', '2026-06-30 16:00:04'),
(36724, 1299, NULL, 'Ксения Лазарева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу выразить Огромную Благодарность Евгению Шамильевичу!!! Я Очень рада что именно Он занялся и Довел до завершения наши Очень трудные и запутанные дела. Он Профессионал Своего Дела! Очень Чуткий и Внимательный человек! Если б не он мы бы проиграли наши дела в судах. Я безмерно Вам Благодарна!! Евгений Шамильевич, Желаю вам всего самого наилучшего! Вы Адвокат с Большой буквы!!! Всем рекомендую адвоката Гареева Евгения Шамильевича!!!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-01-27 00:00:00', NULL, '9d358c679e01226eb19fc3ea7ff8731a196f545e', 'google', 'Ксения Лазарева', NULL, '2018-01-27', '2026-06-30 16:00:04', '2026-06-30 16:00:04'),
(36725, 1299, NULL, 'Юлия Годунко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обратилась к Евгению по совету знакомых. Очень помог по вопросу взыскания ущерба после ДТП, виновником которого я не являлась. Огромное спасибо.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2017-07-18 00:00:00', NULL, '70b3ea166da955e139ea48aae2b95f1615d0c2fd', 'google', 'Юлия Годунко', NULL, '2017-07-18', '2026-06-30 16:00:04', '2026-06-30 16:00:04'),
(36726, 1300, NULL, 'Alexandra', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити щиру і глибоку подяку за допомогу в моїй непростій ситуації. У момент коли здавалося що виходу вже немає, я звернулося за консультацією - і це було правильне рішення. Упевненості. Такі фахівці сьогодні-велика рідкість. А помічниця Алеся це людина з великим серцем. Я їй дуже блогодарно.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-02-26 00:00:00', NULL, 'a831dc6cb27fb296f5e3bc11a4d160c68085c8ce', 'google', 'Alexandra', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSWxPT2ZiaDVDUUhRdllfcmNnNFh3UUlyR0FnOVRMOEdmcVJWWWxqLU9ZX1dQVnF3PXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098454410&signature=44d929b653f77d6c15b2d906a98241a89101eb192570db62a57d2f2ef1b8163e', '2026-02-26', '2026-06-30 16:00:13', '2026-06-30 16:00:19');
