(36998, 1309, NULL, 'Георгій', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую за моє звільнення за рішенням суду. Побратими до Вас звернуться з аналогічним питанням!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-05-01 00:00:00', NULL, 'f2d339e7ca39906404ab0765aab12a67160e9342', 'google', 'Георгій', NULL, '2023-05-01', '2026-06-30 16:01:52', '2026-06-30 16:02:02'),
