(37000, 1309, NULL, 'виктор', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Скольких развел уже страшно и представить этот аферист на Фрон его этого шарлатана который только врет и обманывает людей на деньги .', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-28 00:00:00', NULL, '20afee57f1bfcd75b1b7709b6380ba6ecac41baf', 'google', 'виктор', NULL, '2023-04-28', '2026-06-30 16:01:52', '2026-06-30 16:02:02'),
(37001, 1309, NULL, 'Елена', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Люди не обращайтесь к этому шарлатану 60 тысяч на ветер перевести не перевел уволить не уволили еще просит 20 тыся на повторный процес ,все что пишут помог воранье он настоящий шарлатан и обманщик ищите пожалуста нормальных адвокатов а не тик ток адвоката как этот', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-28 00:00:00', NULL, '85c5c9d8d297fa68d474bd1d39fcf296450e498f', 'google', 'Елена', NULL, '2023-04-28', '2026-06-30 16:01:52', '2026-06-30 16:02:02'),
(37002, 1309, NULL, 'Ігор Пархоменко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Працював з Дмитром Ігоровичем ще два роки тому по кредитам, вдалося сплатити без процентів з його допомогою. Нещодавно звернувся за допомогою моєму товаришу та він допоміг його звільнити з армії. Ще дуже корисні поради в тікток дякую вам', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-28 00:00:00', NULL, 'ff27101eacddab4248b8573e24f6dc9dd28c9bc1', 'google', 'Ігор Пархоменко', NULL, '2023-04-28', '2026-06-30 16:01:53', '2026-06-30 16:02:02'),
