(37084, 1316, NULL, 'Alexandr Grygoriev', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Зв\'язок з інформаційним відділом? Жоден з телефонів не працює близько 2 тижнів. Чи має сенс писати на email? Дякуємо. Поштою швидко відповіли. Міняю оцінку.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-09-28 00:00:00', NULL, 'dcb4641c72aea78a24f29c4bc00963e528721399', 'google', 'Alexandr Grygoriev', NULL, '2018-09-28', '2026-06-30 16:02:25', '2026-06-30 16:02:26'),
(37085, 1316, NULL, 'Олег Балконский', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я тут подавав на аліменти, розлучався. Ніяких зволікань і затримок. Раніше до судді треба було чергу вистояти. Суд був в приміщенні гуртожитку. Вузькі коридори, тіснота і задуха. Сісти ніде. Там був АД! Зараз чисте, світле приміщення. Ніяких черг. Подав секретарю документи, викликали, розглянули ... Нерви не витрачати. Мої справи розглядали судді Калашникова і Васильків. Грамотні і досвідчені судді. Моя вдячність суддям. В інформаційному центрі молода людина ввічливо і доступно допоможе вирішити будь-яке питання. Мені суд подобається.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-09-28 00:00:00', NULL, '8ec58e30417cde790fb64cd59bbfc315306da551', 'google', 'Олег Балконский', NULL, '2018-09-28', '2026-06-30 16:02:25', '2026-06-30 16:02:26'),
(37086, 1316, NULL, 'Aleksander Orłow', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Судебная система феодального строя', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-06-14 00:00:00', NULL, '55c93e593fd6cc68b06103f504c66662b2be2cf7', 'google', 'Aleksander Orłow', NULL, '2018-06-14', '2026-06-30 16:02:25', '2026-06-30 16:02:26'),
(37087, 1316, NULL, 'Кот Матроскин', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Более невкусного кофе с молоком, чем готовят за деньги в этом суде, я не пил нигде. К тому же молоко добавляют несвежее.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2018-02-20 00:00:00', NULL, '25d81a11e36d62fa6a79cc385262c7e59ee4727c', 'google', 'Кот Матроскин', NULL, '2018-02-20', '2026-06-30 16:02:26', '2026-06-30 16:02:26'),
(37088, 1316, NULL, 'Олег Балконский', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Я здесь подавал на алименты, разводился. Никаких проволочек и задержек. Раньше к судье надо было очередь выстоять. Суд был в помещении общаги. Узкие коридоры, теснота и духота. Присесть негде. Там был АД! Сейчас чистое, светлое помещение. Никаких очередей. Подал секретарю документы, вызвали, рассмотрели... Нервы не тратишь. Мои дела рассматривали судьи Калашникова и Васильков. Грамотные и опытные судьи. Моя благодарность судьям. В информцентре молодой человек вежливо и доступно поможет решить любой вопрос. Мне суд нравится.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2017-07-04 00:00:00', NULL, '08561d5a76380947421f548b4ad73524b4985db2', 'google', 'Олег Балконский', NULL, '2017-07-04', '2026-06-30 16:02:26', '2026-06-30 16:02:26'),
(37089, 1316, NULL, 'Sophia Grishchenko', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Очень долго ждать подписи судьи... Меня просили прийти через неделю, мол, неизвестно, когда подпишут, но в результате, когда я приходила, мои документы подписывались за 10 мин при мне. Зачем же так тянуть?', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2017-06-27 00:00:00', NULL, '1689af7e6d571c2ff5b7cd562dd3e4c7f65e1efb', 'google', 'Sophia Grishchenko', NULL, '2017-06-27', '2026-06-30 16:02:26', '2026-06-30 16:02:26'),
(37090, 1316, NULL, 'Alexandr Grygoriev', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Как связаться с информационным отделом? Ни один из телефонов не работает около 2 недель. Имеет ли смысл писать на email? Спасибо. По почте быстро ответили. Меняю оценку.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2016-10-24 00:00:00', NULL, '144641a402bbd5caa9da094935935cf88a1d8ec3', 'google', 'Alexandr Grygoriev', NULL, '2016-10-24', '2026-06-30 16:02:26', '2026-06-30 16:02:26'),
