(39953, 1401, NULL, 'Matvii Suminov', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Збити людину на пішохідному переході, подивитись на неї, і поїхати далі. Покличемо адвоката, розберемось швидко. А, зачекайте, це був адвокат.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-19 00:00:00', NULL, '2cda86eb3ec253f6e5241f3da4c135dd2effcf80', 'google', 'Matvii Suminov', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValhTYXI0RlktNEF4TUJGaHJJLXNPbUxMUG03OW1xc3lmQkl6TEsydEFOUjU4aVdKejJ2PXczMDAtaDMwMC1wLXJwLW1vLWJhMi1icjEwMA==.jpeg?expires=2098455517&signature=2497c85390d33535e0ff927e5237408c116687e7ba2a0511bd181f95a857cff2', '2024-08-19', '2026-06-30 16:18:45', '2026-06-30 16:18:53');
