(40218, 1439, NULL, 'Jack Wolf', NULL, 0, NULL, NULL, 0.00, 4, NULL, 'Знайшов у інтернеті, почитав відгуки та вирішив звернутися за допомогою. Справу по моєму клопотанню було призупинено. Все добре.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-25 00:00:00', NULL, '669535ab005aee51845ebc924b4840ea93de0ec6', 'google', 'Jack Wolf', 'img/empty.png?a2499e3b0', '2024-08-25', '2026-06-30 16:24:53', '2026-07-02 12:40:26'),
(40219, 1439, NULL, 'Вадим Петрук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Приємно що швидко зреагували на мій запит і вирішили мою проблему. Рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-24 00:00:00', NULL, 'e4af6394a6ce1b123d4555aa359b8035a53fae4f', 'google', 'Вадим Петрук', 'img/empty.png?a2499e3b0', '2024-08-24', '2026-06-30 16:24:54', '2026-07-02 12:40:26'),
(40220, 1439, NULL, 'pismo delovoe', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Якщо вагаєтесь то не треба, мені ці козаки та козачки допомогли з ДВОМА справами по кредитах і я задоволений повністю. Їх порекомендувала мені юрист, але по інших справах. Так по сарафанці і знайшов юрконсалт) Завжди на зв\'язку, усе що питав відповідали, та із розумінням до 100 питань віднеслися. Справи виграні по кредитах, а я спокійний і задоволений. Рекомендую, та якщо є сумніви то не треба, вони справді честно, та відкрито працюють. Тож гойда !', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-22 00:00:00', NULL, '01d8bc4b634ccafb9c1473cac16753e2ee55f7ec', 'google', 'pismo delovoe', 'img/empty.png?a2499e3b0', '2024-08-22', '2026-06-30 16:24:54', '2026-07-02 12:40:26'),
(40221, 1439, NULL, 'Kristina Maliy', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже дякую за допомогу! Зверталася за двома кредитними справами все зробили на відмінно', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-22 00:00:00', NULL, '8514baf0dbab1c9cfc07197fcaa570247f663577', 'google', 'Kristina Maliy', 'img/empty.png?a2499e3b0', '2024-08-22', '2026-06-30 16:24:54', '2026-07-02 12:40:26'),
(40222, 1439, NULL, 'Ольга Городищенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Велике дякую команді Юрконсалт і особисто Івану Бабільчуку , який займався нашою справою. Ми звернулися в компанію в нелегкий для нас час, ми втратили на війні найдорожчу нам людину. Іван все детально пояснив, допоміг зібрати усі необхідні документи та завжди був на зв\'язку. І там де військомат знизував плечима більше року, справа була вирішена за 3 місяці. Результатом дуже задоволена. Рекомендувала знайомим і буду рекомендувати в подальшому. Дякую за Вашу працю!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '9c39cc0ccfca045da16cd33370592df464d0c388', 'google', 'Ольга Городищенко', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:54', '2026-07-02 12:40:26'),
(40223, 1439, NULL, 'Алексей Сергеев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Большое спасибо Геннадию и его помощнице Екатерина сделали всё как обещали.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '8e4fea5dda07a240d5e7066f82c4f26498f40f68', 'google', 'Алексей Сергеев', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:54', '2026-07-02 12:40:26'),
(40224, 1439, NULL, 'Алексей Сергеев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Всем привет!Хочу рассказать всем про Юрконсалт.Писатель с меня плохой, поэтому напишу как умею.У меня были кредиты которые начали меня сильно доставать,хотели с меня поиметь много денег.Мне посоветовали обратиться к Геннадию. Я к нему обратился и не пожалел, профессионал высшего уровня, сказал сделал.Поэтому рекомендую.Большое спасибо за работу Геннадию и его помощнице Екатерина сделали всё как обещали я очень доволен, всегда буду к ним обращаться и всем советую .', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '1e025795232a26de46379085186d3a6e64ee4701', 'google', 'Алексей Сергеев', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:54', '2026-07-02 12:40:26'),
(40225, 1439, NULL, 'Олена', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже дякую юристам Юрконсалту. Зверталась з приводу розблокування заробітньої картки банком ПУМБ. Питання було вірішене в терміни оговорені в договорі з юристами. Зворотній зв\'язок і консультації по незрозумілимим моментам на найвищому рівні. Великий плюс в наш час - це можливість розбити платежі за надання юридичної допомоги. Рекомендувала знайомим і неодмінно буду рекомендувати в подальшому. Велика дяка усім юристам Юрконсалту за вашу працю.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '55d6d287cf9ba670b0e9228a8657f6540a802c7e', 'google', 'Олена', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:54', '2026-07-02 12:40:26'),
(40226, 1439, NULL, 'Yevhen Viter', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Постійно співпрацюю з січня 2024 року, маю справу з Іваном Бабільчуком. Результатами дуже задоволений, застосовується індивідуальний підхід, послуги надаються фахово та оперативно', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, 'c8da9546a9dfeb06070095f26fd2f13a93d8797a', 'google', 'Yevhen Viter', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:55', '2026-07-02 12:40:26'),
(40227, 1439, NULL, 'Вячеслав Валерьевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дуже приємно було працювати з \"Юрконсалт\" особиста подяка Геннадію Олександровичу,який допоміг нам розірвати валютний кредит 2007р,зняти всі обмеження (хата, банківські картки та інше майно)реально допомогли та виграли всі суди яки НЕ могли їнши адвокати (були тільки обіцянки ВСЕ БУДЕ ДОБРЕ,поки колектора не почали чергувати в парадной)ні хто не требував гроші на перед,тільки по результатам.Дякуємо Вам м.Одеса сім\'я Яніни !!!!Бажаємо міцного здоров\'я та мирного неба та закінчення війни', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '03d1a5523d75d315b5c29a7025ca98b64a5f1b0b', 'google', 'Вячеслав Валерьевич', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:55', '2026-07-02 12:40:26'),
(40228, 1439, NULL, 'Alla', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендую,справа складна але вирішена.Всі питання вирішували, результати повідомляли одразу.Дякую за Вашу працю.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '04b5d1ccee0bd71899b00698635d19eec0a3e336', 'google', 'Alla', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:55', '2026-07-02 12:40:26'),
(40229, 1439, NULL, 'Виктория Грибко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Рекомендуємо. У вирішенні нашого питання нам допомагала юрист Вікторія. Все детально пояснила, допомогла зібрати усі необхідні документи та завжди була, і досі залишається на звʼязку. Якщо виникають питання можна консультуватися онлайн, що є дуже зручно для нас.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '86a24814f67f184b23e779a999339b257ca8d42c', 'google', 'Виктория Грибко', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:55', '2026-07-02 12:40:26'),
(40230, 1439, NULL, 'Светлана', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Для ведення переговорів з банком, вибрала саме Геннадія Працевитого. І не помилилася. Питання було вирішено чітко, зрозуміло і у короткий термін. Тому, коли була необхідність допомога по справі про скасування заповіту, навіть не було вагань, до кого звертатись. Завдяки правильно вибраній стратегії, отримали очікуваний результат.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '5ae4bcb2db8eec4155c6a4e1e499462b37923d22', 'google', 'Светлана', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:55', '2026-07-02 12:40:26'),
(40231, 1439, NULL, 'Алёна Саламаха', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обращались за помощью к адвокату Ивану Бабильчуку. Спасибо ему большое, помог решить наш вопрос. Искренне рекомендую адвокатское бюро, Юрконсалт', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '9523fb4a69e297c0ce6ae6d8f0fccc5abdf7568f', 'google', 'Алёна Саламаха', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:55', '2026-07-02 12:40:26'),
(40232, 1439, NULL, 'oleksandra pavlovskaya', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Зверталася за допомогою у вирішенні кредитних питань. Геннадій Працевитий допоміг вирішити питання з Ідея банком на мою користь. Якщо вам потрібно розвязати питання з банківськими установами- рекомендую звернутися саме до нього.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, '6b3cbba55b3b3767fcdc26ffdf056bb5c3ac932e', 'google', 'oleksandra pavlovskaya', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:55', '2026-07-02 12:40:26'),
(40233, 1439, NULL, 'Olena Viktorivna', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Звернулися в дуже складний час для нашої сім’ї-втрата чоловіка та батька двох повнолітніх синів. Була на панікі та розгублена. Звернулася до Геннадія Працевитого про допомогу. Швидко та професійно допоміг з оформленням компенсації, допоміг з оформленням документів. Залишаємося на зв’язку та якщо виникають в нас питання радимося із Геннадієм в телефонному режимі. Дякую за підтримку та супровід нашої справи.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-08-21 00:00:00', NULL, 'f7d6ef218017f9bcc7f2812b57b32564202d695f', 'google', 'Olena Viktorivna', 'img/empty.png?a2499e3b0', '2024-08-21', '2026-06-30 16:24:56', '2026-07-02 12:40:26'),
(40234, 1439, NULL, 'Карина Овсянникова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Добрый день! Благодарим за Высокий профессионализм, оказанную поддержку и безоплатную помощь Адвоката Димитрашко Дениса Владимировича (Адвокатское бюро Юрконсалт). Большая благодарность от Крымской Светланы Юрьевны.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-01-12 00:00:00', NULL, 'e18e3e3849547266bba95dd414bccaa41fd0dd31', 'google', 'Карина Овсянникова', 'img/empty.png?a2499e3b0', '2022-01-12', '2026-06-30 16:24:56', '2026-07-02 12:40:26'),
