(40317, 1276, NULL, 'Максим', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Делили имущество с бывшей супругой. Хорошо попался вменяемый адвокат по семейным делам в Запорожье, у которого был опыт работы в подобных спорах. Очень благодарны за помощь и выполненную работу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-30 00:00:00', NULL, '33acb163eda10d8b431ad055fc8998e1978e0a3d', 'google', 'Максим', 'img/empty.png?a2499e3b0', '2024-01-30', '2026-06-30 16:25:23', '2026-07-02 12:43:16'),
(40318, 1276, NULL, 'Андрей', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат делал юридическое сопровождение в ТЦК и СП для получения отсрочки. Все что пообещал, выполнил. Это лучший военный адвокат в Запорожье. Рекомендую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-29 00:00:00', NULL, '7cc37d7fb9e39e599075c406718f183300f07804', 'google', 'Андрей', 'img/empty.png?a2499e3b0', '2024-01-29', '2026-06-30 16:25:23', '2026-07-02 12:43:16'),
(40319, 1276, NULL, 'Татьяна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обращалась онлайн к адвокату с вопросом расторжения брака, поскольку находилась за границей. Адвокат по семейным делам, заключил со мной договор и сделал расторжение брака через суд. С работой и результатом адвоката вполне довольна.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-28 00:00:00', NULL, '6922180ac42f6b190c9613a34befb97f50699147', 'google', 'Татьяна', 'img/empty.png?a2499e3b0', '2024-01-28', '2026-06-30 16:25:23', '2026-07-02 12:43:16'),
(40320, 1276, NULL, 'Ростислав Шумов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Быстро и недорого, плюс гарантия результата по моему делу, вот что привлекло в первую очередь меня для заключения договора с данным адвокатом в Запорожье. То что пообещал адвокат, он сделал. Меня не интересовало как это будет сделано, меня интересовал результат и сроки. Поэтому, выполнив то что договаривались я ставлю положительный отзыв данному адвокату!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-27 00:00:00', NULL, '1b82d42c430721d09e792e45a88933e50b50ee14', 'google', 'Ростислав Шумов', 'img/empty.png?a2499e3b0', '2024-01-27', '2026-06-30 16:25:23', '2026-07-02 12:43:16'),
(40321, 1276, NULL, 'Томчук Сергей', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'К адвокату в Запорожье обратился с вопросом о снятии с регистрации бывшей жены по месту жительства, поскольку она уехала в Польшу и со мной развелась заочно Адвокат через решение суда, выписал бывшую жену в довольно короткий срок Спасибо за помощь!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-26 00:00:00', NULL, '43e3e37613d60420dbcc5c5a34d0379ae7d29fa1', 'google', 'Томчук Сергей', 'img/empty.png?a2499e3b0', '2024-01-26', '2026-06-30 16:25:24', '2026-07-02 12:43:16'),
(40322, 1276, NULL, 'Алла Барвинникова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обращалась к адвокату по семейным делам в Запорожье с вопросом о взыскании алиментов. За небольшую сумму, адвокат составил иски и подал в суд. Результатом по делу вполне довольна!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-16 00:00:00', NULL, '3d0b6398a62ff4eafff3408156f47d53e5206cff', 'google', 'Алла Барвинникова', 'img/empty.png?a2499e3b0', '2024-01-16', '2026-06-30 16:25:24', '2026-07-02 12:43:16'),
(40323, 1276, NULL, 'Марина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Иск о расторжении брака был составлен адвокатом и подан в суд в течении суток. Очень понравилась работа семейного адвоката в Запорожье, быстрота, слаженность действий, доступные цены!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-11 00:00:00', NULL, '676b100bf4261c92139c9115b75e76c0514eb52d', 'google', 'Марина', 'img/empty.png?a2499e3b0', '2024-01-11', '2026-06-30 16:25:24', '2026-07-02 12:43:16'),
(40324, 1276, NULL, 'Кирилл Игнатьевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Был у адвоката по личной консультации по семейному делу. Очень понравилось отношение, все разъяснил. Буду готовить иск о расторжении брака. Всем советую данного семейного юр ста в Запорожье.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-10 00:00:00', NULL, 'f0c9ee75fac65314cd69427ae098c6054a106463', 'google', 'Кирилл Игнатьевич', 'img/empty.png?a2499e3b0', '2024-01-10', '2026-06-30 16:25:24', '2026-07-02 12:43:16'),
(40325, 1276, NULL, 'Сергей Н.', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обращался к адвокату в Запорожье по статье 130 купап. Дело длилось в Шевченковском районном суде города Запорожья более двух месяцев: не являлся на вызовы полицейский составивший протокол. Но адвокат смог выиграть дело и убедить суд в моей невиновности .', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-09 00:00:00', NULL, '293cea89f1ede480af74fde9616bc43d15b66fe7', 'google', 'Сергей Н.', 'img/empty.png?a2499e3b0', '2024-01-09', '2026-06-30 16:25:24', '2026-07-02 12:43:16'),
(40326, 1276, NULL, 'Михаил Жердев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Оформлял документы на субсидию, и мне было отказано. Обратился к адвокату, он составил жалобы и о чудо, мне назначили причитающуюся по закону субсидию. Работой юристов доволен!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-05 00:00:00', NULL, '03cb8266dd9bda33270761353e89db721561903b', 'google', 'Михаил Жердев', 'img/empty.png?a2499e3b0', '2024-01-05', '2026-06-30 16:25:24', '2026-07-02 12:43:16'),
