(40347, 1276, NULL, 'Лисенко Олег', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат выиграл спор с воинской частью по-исландски выплаты единовременной денежной помощи при увольнении с ВСУ. Доволен результатом по делу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-09-01 00:00:00', NULL, '2096711737d82f89dde3740d51e38ab00f699ded', 'google', 'Лисенко Олег', 'img/empty.png?a2499e3b0', '2023-09-01', '2026-06-30 16:25:27', '2026-07-02 12:43:16'),
