(40434, 1276, NULL, 'Марк Логвинов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обращался к адвокату за помощью в разделении лицевых счетов в коммунальной квартире, бывшее общежитие на Украинской. Быстро все организовал и сделал. Очень доволен результатом.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-01-11 00:00:00', NULL, '6cf5eb25d7a6a337ea6237c3adf0b78baf41e8aa', 'google', 'Марк Логвинов', 'img/empty.png?a2499e3b0', '2023-01-11', '2026-06-30 16:25:40', '2026-07-02 12:43:16'),
(40435, 1276, NULL, 'Сім\'я Ходових', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Спасибо адвокату в Запорожье за бесплатную юридическую консультацию по вопросу оспаривания штрафа полиции за нарушение правил дорожного движения. Очень помогли разобраться с этим вопросом. Рекомендую как специалиста против беспредела полиции.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-01-07 00:00:00', NULL, '9a1d32e4b505ea2a77e2850ad90c7facb8579474', 'google', 'Сім\'я Ходових', 'img/empty.png?a2499e3b0', '2023-01-07', '2026-06-30 16:25:40', '2026-07-02 12:43:16'),
(40436, 1276, NULL, 'Иван Дудин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Благодарю за помощь в оспаривание выводов врачебно военной комиссии о моей частичной пригодности. Очень сильно помогли восстановить справедливость в моем деле. Вы лучший адвокат в Запорожье!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-01-03 00:00:00', NULL, '92baec6bcfe7dc6e89e505f0f2c9f21b6a6b4419', 'google', 'Иван Дудин', 'img/empty.png?a2499e3b0', '2023-01-03', '2026-06-30 16:25:40', '2026-07-02 12:43:16'),
(40437, 1276, NULL, 'Назар Солодовник', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запоріжжя, дякую за безкоштовну юридичну консультацію з податкового права під час воєнного стану. Дуже допомогли розібратися з питанням сплати ЄСВ та подачі декларації ФОП 2 групи', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-01-02 00:00:00', NULL, '4b2c4ef810317388daccbb93a6d05f6226491445', 'google', 'Назар Солодовник', 'img/empty.png?a2499e3b0', '2023-01-02', '2026-06-30 16:25:40', '2026-07-02 12:43:16'),
(40438, 1276, NULL, 'Алина Безсонова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Поздравляю вас с Новым 2023 годом! Желаю здоровья и мира над головой. Вы самый лучший мой адвокат!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-01-01 00:00:00', NULL, 'c91ba29d5ea7f4a4061787473c0a5cc202f3af51', 'google', 'Алина Безсонова', 'img/empty.png?a2499e3b0', '2023-01-01', '2026-06-30 16:25:40', '2026-07-02 12:43:16'),
(40439, 1276, NULL, 'Анастасия Корж', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Понравилось отношение адвоката к разрешению моего вопроса в Шевченковском районном суде города Запорожья по поводу установления опекунства. Сделал все максимально дёшево и самое главное быстро. Ставлю 5 балов', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-12-22 00:00:00', NULL, 'd6ca67dc85b5f8e59a9680d52141db6618ad92c7', 'google', 'Анастасия Корж', 'img/empty.png?a2499e3b0', '2022-12-22', '2026-06-30 16:25:41', '2026-07-02 12:43:16'),
(40440, 1276, NULL, 'Коптев Дмитрий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу поблагодарить адвоката в Запорожье за помощь по моему делу обжалования постановления полиции по нарушению правил дорожного движения. Очень понравился результат по делу', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-12-20 00:00:00', NULL, 'cfca6e218c74994eac46a8042668f7a824cbb8d5', 'google', 'Коптев Дмитрий', 'img/empty.png?a2499e3b0', '2022-12-20', '2026-06-30 16:25:41', '2026-07-02 12:43:16'),
(40441, 1276, NULL, 'Артем Тарасов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по уголовным делам помог быстро и недорого снять судимость через Орджоникидзевский районный суд города Запорожья. Поскольку это необходимо было срочно мне, для получения должности командира отделения. Вы лучший адвокат в Запорожье по уголовным делам.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-09-07 00:00:00', NULL, '18c94c5b68a97c0ad13ee586eb9342b91738a3b7', 'google', 'Артем Тарасов', 'img/empty.png?a2499e3b0', '2022-09-07', '2026-06-30 16:25:41', '2026-07-02 12:43:16'),
(40442, 1276, NULL, 'Громова Мария', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по делам об административным правонарушениям, закрыл дело по статье 124 КУпАП: дтп без телесных повреждений, поскольку работники полиции неправильно составили протокол об административном правонарушении и акт осмотра места происшествия. Вы лучший в Запорожье адвокат по делам об административных правоотношений', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-15 00:00:00', NULL, '81c8c908b818fb5831a550637c20c6127d2d776b', 'google', 'Громова Мария', 'img/empty.png?a2499e3b0', '2022-07-15', '2026-06-30 16:25:41', '2026-07-02 12:43:16'),
(40443, 1276, NULL, 'Алла Котева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокаты Запорожья как адвокатская компания выполнила условия нашего договора на все сто процентов, поскольку выиграла дело в суде против горсовета касательно не предоставления под застройку земельного участка в центре города и требования непонятных ,,барышей,,. Вы лучшие адвокаты по земельным делам в Запорожье', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-14 00:00:00', NULL, '3ac5fba02982f03d4537eaa3769f78106c8c0c39', 'google', 'Алла Котева', 'img/empty.png?a2499e3b0', '2022-07-14', '2026-06-30 16:25:41', '2026-07-02 12:43:16'),
(40444, 1276, NULL, 'Пономаренко Ольга', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокаты Запорожья по семейным делам взыскали быстро и недорого алименты на двух детей с бывшего мужа военнослужащего, который имеет возможность обеспечивать детей но морозится. Суд расставил все точки над і. Вы лучшие семейные адвокаты в Запорожье', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-13 00:00:00', NULL, '5ddd92fc0e59b34e813603ec8024e01b8b5bb20b', 'google', 'Пономаренко Ольга', 'img/empty.png?a2499e3b0', '2022-07-13', '2026-06-30 16:25:41', '2026-07-02 12:43:16'),
(40445, 1276, NULL, 'Валентина Ковальчук', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по пенсионным делам помог правильно пересчитать назначенную пенсию и увидел ошибку пенсионного фонда в определении коэффициента и принятия во внимание средней заработной платы за определенный период работы, который был проигнорирован работником пенсионного фонда. Очень понравилось отношение адвоката к решению моей проблемы.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-12 00:00:00', NULL, '29eba7d927731cf741636bcf9fe835fedce77515', 'google', 'Валентина Ковальчук', 'img/empty.png?a2499e3b0', '2022-07-12', '2026-06-30 16:25:41', '2026-07-02 12:43:16'),
(40446, 1276, NULL, 'Павел Аршавников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье помог в деле о мошенничестве чтве, когда я заплатила за установку балкона почти 120 тыс. гривен, а исполнитель, просто снял замеры, разломал старый балкон и пропал. Пришлось нанимать адвоката и подавать заявление в полицию о мошенничестве. Сейчас адвокат подал ходатайство о наложении ареста на все имущество мошенника и идёт подготовка дела к суду, где я уже признана потерпевшей.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-12 00:00:00', NULL, '723bd1e0f8333f85c1cc01bb1b3e078d93509103', 'google', 'Павел Аршавников', 'img/empty.png?a2499e3b0', '2022-07-12', '2026-06-30 16:25:42', '2026-07-02 12:43:16'),
(40447, 1276, NULL, 'Наталья Иванникова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по семейным вопросам быстро и недорого расторгнуть брак через суд, исключив возможность личной встречи с бывшим уже супругом. Так не хотелось его видеть снова. Вы лучший семейный адвокат в Запорожье.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-11 00:00:00', NULL, '22f2a80e67d2db2575a6a4917568dc9cdd3f63b7', 'google', 'Наталья Иванникова', 'img/empty.png?a2499e3b0', '2022-07-11', '2026-06-30 16:25:42', '2026-07-02 12:43:16'),
(40448, 1276, NULL, 'Владислав Романенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по наследству помог отменить завещание в суде, поскольку нотариус пошла на поводу у моей соседки и заверила завещание моей бабушки которая страдала болезнью Альцгеймера, тем самым лишив меня наследства в виде квартире в центре Запорожья. Адвокат подал иск в суд и назначил проведение посмертной судебно психиатрической экспертизы, по результатам которой отменил завещание и право собственности на квартиру зарегистрированное за соседкой. Вы лучший адвокат по наследству в Запорожье', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-09 00:00:00', NULL, '80bba458698797699077e1c8f8f12eba1c16ec97', 'google', 'Владислав Романенко', 'img/empty.png?a2499e3b0', '2022-07-09', '2026-06-30 16:25:42', '2026-07-02 12:43:16'),
(40449, 1276, NULL, 'Илья Шепетов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по кредитным делам помог отменить Заочное решение Самарского районного суда города Днепропетровска о взыскании задолженности по кредитному договору, и снял наложенный частным исполнителем арест на имущество. Вы лучший кредитный адвокат в Запорожье.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-08 00:00:00', NULL, '11900bcc38d579a4812bea76512003aa6cfebccc', 'google', 'Илья Шепетов', 'img/empty.png?a2499e3b0', '2022-07-08', '2026-06-30 16:25:42', '2026-07-02 12:43:16'),
(40450, 1276, NULL, 'Анатолий Бесчастный', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по гражданским делам помог взыскать моральный ущерб за оскорбление соседом моей матери. Несколько раз предупреждали о недопустимости такого поведения и распития алкогольных напитков возле подъезда, все без толку. Как только наняли адвоката и задокументировали противоправную деятельность, да обратились в суд, соседа будто подменили). Очень доволен работой адвоката в суде и в исполнительной службе.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-07 00:00:00', NULL, '9460ed1dd441f8a465ca00cc8459dfe8d38601e1', 'google', 'Анатолий Бесчастный', 'img/empty.png?a2499e3b0', '2022-07-07', '2026-06-30 16:25:42', '2026-07-02 12:43:16'),
(40451, 1276, NULL, 'Роман Купейдонов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокаты Запорожья взыскали с соседа (должника) сумму которую он брал ещё до войны в долг под проценты, но так и не смог возвратить, игнорируя мои требования. Пришлось нанять адвокатов в Запорожье для подачи иска в суд и взыскания в принудительном порядке долга по долговой расписке. Все понравилось, особенно результат и дальнейшая помощь адвоката в исполнительной службе.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-06 00:00:00', NULL, '404eb3973a6e7c49f67d8aeb67089afa848ffeb9', 'google', 'Роман Купейдонов', 'img/empty.png?a2499e3b0', '2022-07-06', '2026-06-30 16:25:42', '2026-07-02 12:43:16'),
(40452, 1276, NULL, 'Юлия Анатольевна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Запорожье по жилищным делам помог недорого и в ускоренном варианте снять с прописки бывшего мужа, который уже не проживает в квартире более 2 лет, из-за чего я не могла оформить субсидию. Через иск в суд, адвокат снял с регистрации бывшего мужа без его согласия и участия в процессе, просто поставив перед фактом.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-05 00:00:00', NULL, '01a8768e5b771315b3a6dc0f017e71ffea94cf3b', 'google', 'Юлия Анатольевна', 'img/empty.png?a2499e3b0', '2022-07-05', '2026-06-30 16:25:42', '2026-07-02 12:43:16'),
(40453, 1276, NULL, 'Роман Неклюдов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье помог составить правильно формуляр жалобы в Европейский суд по правам человека о нарушении государством статьи 6 Конвенции о защите прав человека и согласных свобод, при рассмотрении моего деда в национальных судах. Увы, реальность такова что доказать в суде свою правоту очень стало сложно, особенно когда на иной стороне чиновник горсовета. Думаю Евросуд расставит все точки над i.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-04 00:00:00', NULL, '7f3af068e68aceb8424fa6833265f7e0ceee7785', 'google', 'Роман Неклюдов', 'img/empty.png?a2499e3b0', '2022-07-04', '2026-06-30 16:25:43', '2026-07-02 12:43:16'),
(40454, 1276, NULL, 'Климов Сергей', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по земельным делам, помог отменить договор аренды земельного пая заключённый фермером с моей поддельной подписью. Правда пришлось обращаться в суд и назначить по делу судебно почерковедческую экспертизу, но это того стоило!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-03 00:00:00', NULL, '8f16f0d79be1974f063fa3402ada4deafe8ce23a', 'google', 'Климов Сергей', 'img/empty.png?a2499e3b0', '2022-07-03', '2026-06-30 16:25:43', '2026-07-02 12:43:16'),
(40455, 1276, NULL, 'Артур Гаспарян', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по наследству, помог через суд оформить право собственности на дом доставшийся от бабушки на который были утеряны (вернее выкраны моей сестрой) документы. Все сделал максимально быстро и не дорого, даже н взирая на противодействие со стороны родной сестры, которая не хотела отдавать дом доставшийся мне по завещанию.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-02 00:00:00', NULL, 'e36e3531249f7e1d98de4085030469fbd051644d', 'google', 'Артур Гаспарян', 'img/empty.png?a2499e3b0', '2022-07-02', '2026-06-30 16:25:43', '2026-07-02 12:43:16'),
(40456, 1276, NULL, 'Варвара Федоровна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье сделал адвокатский запрос в архив Республики Казахстан где хранилось мое личное дело сданное с предприятия. Поскольку документ нужен был начисления пенсии в полном объеме.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-01 00:00:00', NULL, 'c434add03af3f2fd0ca261c76255a34a2697a400', 'google', 'Варвара Федоровна', 'img/empty.png?a2499e3b0', '2022-07-01', '2026-06-30 16:25:43', '2026-07-02 12:43:16'),
(40457, 1276, NULL, 'София Смольская', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье помог забрать с отдела полиции Вознесеновского района города Запорожья мужа, который ездил на велосипеде по городу без документов и был остановлен сотрудниками полиции. Хорошо что быстро среагировал адвокат, а то бы муж ночевал бы в райотделе полиции до утра. Спасибо за помощь, мужу будет хороший урок на будущее.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-30 00:00:00', NULL, '58ae60a0572b7d312d902d424f24fe3520a696e6', 'google', 'София Смольская', 'img/empty.png?a2499e3b0', '2022-06-30', '2026-06-30 16:25:43', '2026-07-02 12:43:16'),
(40458, 1276, NULL, 'Виталий Колосов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье, спасибо за бесплатную юридическую консультацию в телефонном режиме по вопросам нарушения правил мобилизации. Очень помогли в данном вопросе разобраться.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-28 00:00:00', NULL, '3ad67721dcc2e8aee395aa2928689e2b2948ae8e', 'google', 'Виталий Колосов', 'img/empty.png?a2499e3b0', '2022-06-28', '2026-06-30 16:25:43', '2026-07-02 12:43:16'),
