(40946, 1443, NULL, 'Katya Katya', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Очень хороший адвокат. Пыталась найти адвоката в выходной день и проконсультировать онлайн. Не могла никого найти, а Николай согласился. Обсудили вопрос и удаленно была выполнена работа. Профессионал своего дела', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-01-23 00:00:00', NULL, '7d000c2d3b79ee503d00c051d121eb53b6f46a24', 'google', 'Katya Katya', 'img/empty.png?a2499e3b0', '2021-01-23', '2026-06-30 16:27:37', '2026-07-02 12:41:41'),
(40947, 1070, NULL, 'Карельский Игорь', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Спасибо юристу за быстрое составление жалобы на исполнительную службу, которая заблокировала без каких либо оснований банковский счёт. После жалобы, счёт был разблокирован,и начальником отдела.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-05 00:00:00', NULL, 'c72122e7762fa13cc7667b148e7536a1533e8250', 'google', 'Карельский Игорь', 'img/empty.png?a2499e3b0', '2024-02-05', '2026-06-30 16:27:40', '2026-07-02 12:41:46'),
(40948, 1070, NULL, 'Владимир', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат, помог через Заводский районный суд города Запорожья восстановить пропущенный срок для вступления в наследство. Что понравилось: быстро все и оперативно. По деньгам, средняя цена по городу. Обзванивал, спрашивал у иных. Почему понравился именно этот адвокат: дал гарантию и слово сдержал. Уважаю профессионалов.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-01-03 00:00:00', NULL, '89fbc934aa147699df527b4581b71794dc6cae9f', 'google', 'Владимир', 'img/empty.png?a2499e3b0', '2024-01-03', '2026-06-30 16:27:41', '2026-07-02 12:41:46'),
(40949, 1070, NULL, 'Коваленко Артур', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат по семейным делам, оказал огромную помощь по моему семейному делу. Быстро и недорого организовал расторжение брака через суд, и выписал бывшую жену с моего дома. Осень признателен за помощь.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-12-29 00:00:00', NULL, 'a54b06a0312c11659ffec7e2f1e62e3123540db8', 'google', 'Коваленко Артур', 'img/empty.png?a2499e3b0', '2023-12-29', '2026-06-30 16:27:41', '2026-07-02 12:41:46'),
(40950, 1070, NULL, 'Наталья Егоровна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат выиграл дело против облэнерго, и отменил штраф Советую у кого проблемы с облэнерго!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-12-28 00:00:00', NULL, '831db56e695f510fabf3491491be44f5c23201d3', 'google', 'Наталья Егоровна', 'img/empty.png?a2499e3b0', '2023-12-28', '2026-06-30 16:27:41', '2026-07-02 12:41:46'),
(40951, 1070, NULL, 'Никонов Олесь', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Запорожье, спасибо за юридическую консультацию по вопросу обжалования штрафа полиции', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-12-13 00:00:00', NULL, '0e289679b8f0fd6aaeaaf5d96d9522596f17f310', 'google', 'Никонов Олесь', 'img/empty.png?a2499e3b0', '2023-12-13', '2026-06-30 16:27:41', '2026-07-02 12:41:46'),
(40952, 1070, NULL, 'Александр Ярема', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Спасибо адвокату за юридическую консультацию по вопросу вручения повестки на блокпосту. Очень помогли', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-07-15 00:00:00', NULL, '931ee029a226ef72f32356f82038bc5e02538429', 'google', 'Александр Ярема', 'img/empty.png?a2499e3b0', '2023-07-15', '2026-06-30 16:27:41', '2026-07-02 12:41:46'),
(40953, 1070, NULL, 'Ростислав Алейников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обращался к адвокату в Запорожье по вопросу взыскания алиментов с бывшей жены, поскольку ребенок стал жить со мной. Адвокат по семейным делам в Запорожье быстро подготовил пакет документов для суда и помог решить вопрос. Кстати недорого.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-07-14 00:00:00', NULL, '750bf1658b96acd73897d1d47ec87fbc6eecc696', 'google', 'Ростислав Алейников', 'img/empty.png?a2499e3b0', '2023-07-14', '2026-06-30 16:27:41', '2026-07-02 12:41:46'),
(40954, 1070, NULL, 'Лариса', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье, благодарю за консультацию по семейному делу. Очень здорово что подсказали как правильно нужно поступить', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-06-29 00:00:00', NULL, '31ca3da5e8f72497c793a8ce39d01b59df39247a', 'google', 'Лариса', 'img/empty.png?a2499e3b0', '2023-06-29', '2026-06-30 16:27:42', '2026-07-02 12:41:46'),
(40955, 1070, NULL, 'Руслан', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Понравилась консультация адвоката по наследству в Запорожье', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-26 00:00:00', NULL, 'fe00a26e0047484bed7e671affc0974fc4e8e98d', 'google', 'Руслан', 'img/empty.png?a2499e3b0', '2023-04-26', '2026-06-30 16:27:42', '2026-07-02 12:41:46'),
(40956, 1070, NULL, 'Дмитрий Козуль', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Очень помогла ваша юридическая консультация при общении на блокпосту с сотрудниками ТЦК которые хотели меня насильно забрать в военкомат, игнорируя бронь предприятия. Спасибо за помощь, вы лучший адвокат в Запорожье!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-13 00:00:00', NULL, '38026fca7c7e8ca24dfbf6add08ce537116e53f5', 'google', 'Дмитрий Козуль', 'img/empty.png?a2499e3b0', '2023-04-13', '2026-06-30 16:27:42', '2026-07-02 12:41:46'),
(40957, 1070, NULL, 'Марина Антипова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат помог отменить заочное решение суда о взыскании задолженности по коммунальным платежам за горячую воду, при этом, трубы отслежены уже были более 7 лет. И договор не заключался. Рекомендую как лучшего юриста по делам о ЖКХ в Запорожье', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-06 00:00:00', NULL, '764bbfa5a9d720f9fe89cf5a3f6403823073e53e', 'google', 'Марина Антипова', 'img/empty.png?a2499e3b0', '2023-04-06', '2026-06-30 16:27:42', '2026-07-02 12:41:46'),
(40958, 1070, NULL, 'Сім\'я Ходових', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Шановний адвокат, поздоровляю вас з Різдвом, та бажаю натхнення, та побільше виграних справ! Дуже допомогли розібратися з проблемою оскарження висновку ВЛК до вищої інстанції ЦВЛК. Хай вам щастить. З повагою, сім\'я Ходових.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-01-07 00:00:00', NULL, 'b32657e26c665f9c974bdc64aadb73c5e3c9bc80', 'google', 'Сім\'я Ходових', 'img/empty.png?a2499e3b0', '2023-01-07', '2026-06-30 16:27:42', '2026-07-02 12:41:46'),
(40959, 1070, NULL, 'Лиза Марковна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Запорожье по семейным делам помог быстроты недорого взыскать алименты и подать в исполнительную службу лист на принудительное удержание. Понравилось: быстрота и ясность работы адвоката', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-12-28 00:00:00', NULL, 'badb70ec88e6a6615ff1bc725198e2e2e0bbacf5', 'google', 'Лиза Марковна', 'img/empty.png?a2499e3b0', '2022-12-28', '2026-06-30 16:27:42', '2026-07-02 12:41:46'),
(40960, 1070, NULL, 'Василь Безкоровайний', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запоріжжя, дякую за безкоштовну юридичну консультацію з питання мобілізації батька малолітніх дітей. Дуже допомогли розібратися з підставами відстрочки від призову на військову службу у воєнний стан', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-18 00:00:00', NULL, 'ee62d66d6a73ede31176b9cc4bf939a134313621', 'google', 'Василь Безкоровайний', 'img/empty.png?a2499e3b0', '2022-06-18', '2026-06-30 16:27:43', '2026-07-02 12:41:46'),
(40961, 1070, NULL, 'Кирилл Калашников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Офис адвоката на улице Фортечной в Запорожье знаю лет 10. Ещё давно помогал расторгнуть брак в Орджоникидзевском районном суде города Запорожья а теперь, вот помогает расторгнуть второй брак. Думаю это лучший семейный адвокат в Запорожье. Советую тем кому надоела монотонная семейная кабала, без чувств. Время менять и делать выводы в жизни. Всем добра.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-05-23 00:00:00', NULL, 'dc0994f64a7859254cebf7b8c81cac5e72cf3f11', 'google', 'Кирилл Калашников', 'img/empty.png?a2499e3b0', '2022-05-23', '2026-06-30 16:27:43', '2026-07-02 12:41:46'),
(40962, 1444, NULL, 'Наташа Дяченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Было ДПТ и нужна была срочная помощь. После ремонта машина страховая ничего не хотела выплачивать. Обратились к вам и получили помощь. Страховая выплатила деньги и этого хватило. спасибо за отлично проделанную работу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2021-06-14 00:00:00', NULL, '9c43b7b1255445cf1dcf977f15454d80d02a178c', 'google', 'Наташа Дяченко', 'img/empty.png?a2499e3b0', '2021-06-14', '2026-06-30 16:27:47', '2026-07-02 12:41:49'),
