(41087, 586, NULL, 'Олег', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Хортицкой район Запорожье - спасибо за юридическую консультацию по поводу обжалования уведомления налоговой о неуплаты ЕСВ.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-07 00:00:00', NULL, '1b006206942bfa99452215a7e539eb37afb83c88', 'google', 'Олег', 'img/empty.png?a2499e3b0', '2024-02-07', '2026-06-30 16:28:44', '2026-07-02 12:42:39'),
(41088, 586, NULL, 'Алена Коршунова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Запорожье Хортицкого района помог взыскать через суд алименты на содержание ребенка с отца военнослужащего, который забыл что у него есть сын. Очень благодарна адвокату по семейным делам за помощь и скидку на услуги адвоката.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-12 00:00:00', NULL, '824c0d81c30a49f079835cf76b657e2807fd3876', 'google', 'Алена Коршунова', 'img/empty.png?a2499e3b0', '2022-07-12', '2026-06-30 16:28:44', '2026-07-02 12:42:39'),
(41089, 586, NULL, 'Игорь Лапошников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье Хортицкой район,,Бабурка,, помог закрыть дело о взыскании с меня задолженности по кредитному договору, ввиду истечения сроков исковой давности. Вы лучший кредитный адвокат в Запорожье', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-11 00:00:00', NULL, 'a1ca039aabd493871e0e94b6d0f290d10140d4a3', 'google', 'Игорь Лапошников', 'img/empty.png?a2499e3b0', '2022-07-11', '2026-06-30 16:28:44', '2026-07-02 12:42:39'),
(41090, 586, NULL, 'Олег Анатольевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье помог решить вопрос по выписке с жилья бывшего жильца, который не проживает более чем 2 года, но коммунальные приходилось платить и за него.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-04 00:00:00', NULL, 'c2fa4a1a0ef3a74363a630bc6081f3e484617819', 'google', 'Олег Анатольевич', 'img/empty.png?a2499e3b0', '2022-07-04', '2026-06-30 16:28:45', '2026-07-02 12:42:39'),
(41091, 586, NULL, 'Станислав Роженко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Понравилось быстрое и четкое решение решение моей проблемы адвокатом Хортицкого района города Запорожья. Какие плюсы, могу отметить? Прежде всего понравилась бесплатная юридическая консультация адвоката по телефону и доступная цена на предоставленные юридические услуги. Могу ли я посоветовать данного адвоката иным? Да. Это лучший в Запорожье адвокат. Который помог.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-05-23 00:00:00', NULL, '1a090907bbb860592aa0fe6febcc391e12c0f0cb', 'google', 'Станислав Роженко', 'img/empty.png?a2499e3b0', '2022-05-23', '2026-06-30 16:28:45', '2026-07-02 12:42:39'),
(41092, 1446, NULL, 'Васильев Игорь', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хорошо сделали свою работу по моему делу в Орджоникидзевском районном суде города Запорожья. Пишу отзыв благодарности! Так держать.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-05 00:00:00', NULL, '5e6be266560b6be5e56d311f4be59b0bb92ae2f2', 'google', 'Васильев Игорь', 'img/empty.png?a2499e3b0', '2024-02-05', '2026-06-30 16:28:48', '2026-07-02 12:42:43'),
(41093, 1446, NULL, 'Карина Александрова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье Алейников, помог забрать ребенка с органов опеки и попечительства куда его поместили после переселения с Мариуполя, так как ехали двумя колонами из эвакуации. Учитывая что документов не было, сгорели в доме, мне нехотели возвращать ребенка. Пришлось подключить адвоката. Адвокат все сделал быстро и совсем недорого.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-26 00:00:00', NULL, '8245ff1655bf5cdaeb8e3393c3d3c9639f4b3a34', 'google', 'Карина Александрова', 'img/empty.png?a2499e3b0', '2022-07-26', '2026-06-30 16:28:48', '2026-07-02 12:42:43'),
(41094, 1446, NULL, 'Ваданский Виталий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье взыскал причиненный мне преступлением моральный и материальный ущерб за счёт имущества подсудимых, которые напали на меня и совершили разбой. Наказанием и мерами взыскания примирение к преступникам остался доволен. Вы лучший адвокат по уголовным делам в Запорожье', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-04 00:00:00', NULL, 'c56a85f2974f8b28f0fe5c36c5b5b07b79205947', 'google', 'Ваданский Виталий', 'img/empty.png?a2499e3b0', '2022-07-04', '2026-06-30 16:28:48', '2026-07-02 12:42:43'),
(41095, 1446, NULL, 'Светлана Борисовна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Запорожье Алейников, помог расторгнуть брак в суде без моего участия. Так не хотелось снова видится с бывшим мужем. Поэтому все юридические сопровождение в Вольнянском районном суде Запорожской области где проходило слушание дела, адвокат организовал самостоятельно, мне выдал лишь на руки вступившее решение суда о расторжении брака. Вы лучший адвокат по дистанционному расторжению брака в Запорожье.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-11 00:00:00', NULL, '4c9bb2c4035d252a69fe4d0787cf98b70eb2d24d', 'google', 'Светлана Борисовна', 'img/empty.png?a2499e3b0', '2022-06-11', '2026-06-30 16:28:48', '2026-07-02 12:42:43'),
(41096, 1446, NULL, 'Леонид Львович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу поблагодарить адвоката Алейникова за помощь в перерасчёт пенсии по списку 2. Вы лучший пенсионный юрист в нашем городе. Только вы нашли ошибку пенсионного фонда при начислении мне пенсии и засчитали в страховой стаж время работы пенсионера на пенсии. Увеличив пенсию на полторы тысячи гривен. Спасибо.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-05-23 00:00:00', NULL, '5bf6fa814a701ae9154e23226e6e34c3ada495ad', 'google', 'Леонид Львович', 'img/empty.png?a2499e3b0', '2022-05-23', '2026-06-30 16:28:48', '2026-07-02 12:42:43'),
(41097, 1450, NULL, 'Сергей Сазонов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Обращался к адвокату за помощью в подготовке документов для выезда за границе в Польшу во время военного положения, поскольку я инвалид, и не знал порядок прохождения границы по новым правилам. Очень грамотный юрист в Запорожье, советую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-07 00:00:00', NULL, 'b7263c69122fed8472fbc4b6ee65f5a23e21ada8', 'google', 'Сергей Сазонов', 'img/empty.png?a2499e3b0', '2024-02-07', '2026-06-30 16:28:51', '2026-07-02 12:44:26'),
(41098, 1450, NULL, 'Владимир Алексеевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по иностранным делам помог быстро и недорого расторгнуть брак с гражданкой Сирии, которая училась у нас в медухе но уехала в Сирию. Через консульство и привлечения суда Сирии, удалось брак расторгнуть и прекратить ненужные обязательства. Очень доволен.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-03 00:00:00', NULL, 'b33979f65fd2588add9520905008e86b3245f088', 'google', 'Владимир Алексеевич', 'img/empty.png?a2499e3b0', '2022-07-03', '2026-06-30 16:28:51', '2026-07-02 12:44:26'),
(41099, 1450, NULL, 'Самвел Аратюнян', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат по Миграционным делам в Запорожье помог получить паспорт взамен старого паспорта СССР и оформить гражданство Украины, поскольку с момента развала союза я не получал паспорт гражданина Украины. Теперь у меня законное гражданство а не сид на жительство как у иных беженцев с Азербайджана, которые живут тут не легально.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-02 00:00:00', NULL, '318d0d17d30d604eb183012b306559ace97ac624', 'google', 'Самвел Аратюнян', 'img/empty.png?a2499e3b0', '2022-07-02', '2026-06-30 16:28:51', '2026-07-02 12:44:26'),
