(41111, 1454, NULL, 'Анатолий Гнидой', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат по уголовным делам в Запорожье помог снять судимость в Орджоникидзевском районном суде города Запорожья. Все быстро, ясно и за приемлемую сумму. Вы лучший адвокат в Запорожье по уголовным делам.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-12 00:00:00', NULL, 'b07f3d8c5ffad73a4278e1bca7af6e085aed232d', 'google', 'Анатолий Гнидой', 'img/empty.png?a2499e3b0', '2022-07-12', '2026-06-30 16:28:59', '2026-07-02 12:42:53'),
(41112, 1454, NULL, 'Виталий Бурлуцкий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Запорожье по уголовным делам помог выйти с Вольнянском ИК 55 условно досрочно. Поскольку администрация колонии требовала слишком много, пришлось нанять адвоката по уголовным делам в Запорожье, который сделал запросы, подал представление в суд, и смог убедить Вольнянский районный суд Запорожской области в необходимости моего условно досрочного освобождения. Сейчас я нахожусь дома! Очень доволен.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-28 00:00:00', NULL, '383dcd4548174517d8c4e51a517e4426b297d111', 'google', 'Виталий Бурлуцкий', 'img/empty.png?a2499e3b0', '2022-06-28', '2026-06-30 16:28:59', '2026-07-02 12:42:53'),
(41113, 1455, NULL, 'Алла Георгиевна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат по мобилизации Запорожье, спасибо тебе за консультацию по вопросу постановки на воинский усни и обновления данных в ТУК и СП по новому закону о мобилизации', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-05-04 00:00:00', NULL, '05990d5abcb9aa30e2b282cbe6909c8e1e95aec8', 'google', 'Алла Георгиевна', 'img/empty.png?a2499e3b0', '2024-05-04', '2026-06-30 16:29:02', '2026-07-02 12:42:56'),
(41114, 1455, NULL, 'Александр Дмитриевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Военный адвокат в Запорожье, находиться по адресу улица Школьная, 21 телефон 0639445994 Только военные дела и консультации!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-12-22 00:00:00', NULL, '2e65c9f9bdfae01e39dde33cf2d290d49b815e53', 'google', 'Александр Дмитриевич', 'img/empty.png?a2499e3b0', '2023-12-22', '2026-06-30 16:29:02', '2026-07-02 12:42:56'),
