(41176, 1070, NULL, 'назар', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Дніпро, дякую за юридичну підтримку та консультації на протязі всього процесу з приводу ДТП. Ви найкращій в Дніпропетровську адвокат зі справ про дтп', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-08-16 00:00:00', NULL, 'd956312ec616f439e9d53f42517962c54d57297f', 'google', 'назар', NULL, '2023-08-16', '2026-06-30 17:26:54', '2026-07-02 12:41:46'),
