(41178, 1070, NULL, 'Александр Гресь', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, спасибо за юридическую консультацию по вопросу пересечения границы в военное время. Очень помогли разобраться в сложившейся ситуации', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-06-05 00:00:00', NULL, 'dd42688d1c3a82860056a4505787872a7508c53c', 'google', 'Александр Гресь', NULL, '2023-06-05', '2026-06-30 17:26:54', '2026-07-02 12:41:46'),
(41179, 1070, NULL, 'Кузьменко Егор', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, спасибо за юридическую консультацию. Очень помогли разобраться с правовым вопросом.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-05-15 00:00:00', NULL, '368260310470dc30cfea9173aaba404f548f8a6d', 'google', 'Кузьменко Егор', NULL, '2023-05-15', '2026-06-30 17:26:54', '2026-07-02 12:41:46'),
(41180, 1070, NULL, 'Алексей Романов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог в деле о расторжении брака без похода в военкомат. Очень быстро и недорого, кстати. Результат понравился. Отзыв пишу лично.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-04-06 00:00:00', NULL, '8f60ed522d7228211b6dec0ce874dd0dddda7631', 'google', 'Алексей Романов', NULL, '2023-04-06', '2026-06-30 17:26:54', '2026-07-02 12:41:46'),
(41181, 1070, NULL, 'Роман Игныш', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, вы лучший адвокат в Днепропетровской области по семейным спорам. Помогли быстро и недорого организовать расторжение брака. Очень благодарен за помощь.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-03-11 00:00:00', NULL, 'b3b16193b5c49b36d6b4b25777c6eac419a56fd6', 'google', 'Роман Игныш', NULL, '2023-03-11', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41182, 1070, NULL, 'Михаил Воскобойник', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, спасибо вам за предоставленную бесплатную юридическую консультацию по вопросу выезда за границу в военное время. Очень помогли понять действующее законодательство. Благодарю! Вы действительно лучший адвокат в Днепре!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-09-15 00:00:00', NULL, '1cc13d4d4382d32d81f3ebf2a41d436ca7738d58', 'google', 'Михаил Воскобойник', NULL, '2022-09-15', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41183, 1070, NULL, 'Ольга Капустина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, спасибо за разъяснения по вопросу взыскания алиментов на несовершеннолетеюрего ребенка и маму до 3 летнего возраста. Очень помогли в данном деле. Вы лучший семейный адвокат в Днепре!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-09-10 00:00:00', NULL, '9794256b0b477f12a59dad257f3d37a96207fe73', 'google', 'Ольга Капустина', NULL, '2022-09-10', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41184, 1070, NULL, 'Михаил Пожебяков', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр как специалист по семейным делам осень хорош. Проконсультировал, составил недорого иск, помог в суде, забрал решение суда и исполнительный лист. Помог открыть дело в исполнительной службе. Вот что мне нравиться в профессионалах, это комплекс работы от А до Я. Одним словом молодец. И цена ниже чем у иных юристов и адвокатов в Днепре.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-09-08 00:00:00', NULL, '9dba6bfa88b7b5ba992ed9df9ec60cf08edfb25d', 'google', 'Михаил Пожебяков', NULL, '2022-09-08', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41185, 1070, NULL, 'Инна Беркова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по семейным делам, помог быстро и недорого составить и подать в суд исковое заявление о расторжении брака. Понравилось отношение адвоката к моему вопросу. Ставлю лайк!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-09-02 00:00:00', NULL, '9bbb8dbb4e16af1596fd5acc0a9d2ccbd91cd8e3', 'google', 'Инна Беркова', NULL, '2022-09-02', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41186, 1070, NULL, 'Василий Першин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог восстановить утраченные год назад водительские права, когда сотрудники полиции забрали их при остановке транспортного средства. Чем избавил меня от стояния в очередях и новой пересдачи прав в сервисном центре МВД. Очень доволен результатом за приемлемые деньги.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-26 00:00:00', NULL, 'f51888bf75d5f7dc390a22d2825c3ea68582b3c4', 'google', 'Василий Першин', NULL, '2022-07-26', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41187, 1070, NULL, 'Валик Карташов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, по трудовому праву восстановил на работе с которой меня было незаконно уволено. Плюс взыскал среднюю заработную плату за время вынужденного прогула, хотя моей вины в том не было. Вы лучший адвокат в Днепре по трудовым делам', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-21 00:00:00', NULL, 'e33504af3a23862f41e997b19ca67308eb0c0f17', 'google', 'Валик Карташов', NULL, '2022-07-21', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41188, 1070, NULL, 'Валентина Пеклушенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, помог решить через суд вопрос о снятии с регистрации бывшего жильца квартиры, который более года не проживает по адресу и не портит за коммунальные услуги. Теперь, можно хоть субсидию оформить. Вы лучший адвокат в Днепре по жилищным вопросам.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-20 00:00:00', NULL, '58a74016b9b9d42b0e3ae68d09fe55b8e2e2ab46', 'google', 'Валентина Пеклушенко', NULL, '2022-07-20', '2026-06-30 17:26:55', '2026-07-02 12:41:46'),
(41189, 1070, NULL, 'Олег Ромашин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, очень благодарен за предоставленную бесплатную юридическую консультацию по телефону. Очень помогли разобраться с вопросом мобилизации и выезда за границу волонтёра во время военного положения в стране. Удовлетворен обращением к данному адвокату в Днепре.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-19 00:00:00', NULL, '6fde032e88738462079c4cda7234cd5ec83f9a9f', 'google', 'Олег Ромашин', NULL, '2022-07-19', '2026-06-30 17:26:56', '2026-07-02 12:41:46'),
(41190, 1070, NULL, 'Люмьен Виноградова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Днепре понравился за быстрое и недорогое оказание мне юридических услуг в области семейного права, а именно касательно взыскания алиментов и подачи иска о расторжении брака. Все сделал быстро и недорого. Удивлена сервисом и быстротой. Буду рекомендовать вас как лучшего семейного юриста в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-18 00:00:00', NULL, '3b19b9ea330f12b9e056797925f36759bb75c523', 'google', 'Люмьен Виноградова', NULL, '2022-07-18', '2026-06-30 17:26:56', '2026-07-02 12:41:46'),
(41191, 1070, NULL, 'Богдан Стрижаков', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр обжаловал и отменил через суд решение налоговой о взыскании с меня графа за неуплату ЕСВ когда я был ,,спящим,, фопом. Очень доволен результатом. Поскольку двойное налогообложение запрещено.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-17 00:00:00', NULL, '0181306dc94e430534feda0ebeb529013e2d27c6', 'google', 'Богдан Стрижаков', NULL, '2022-07-17', '2026-06-30 17:26:56', '2026-07-02 12:41:46'),
(41192, 1070, NULL, 'Раиса Абрамовна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по жилищным делам помог выселить с квартиры и снять с регистрации бывшего мужа. Без похода в военкомат и без его согласия', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-16 00:00:00', NULL, '19e8b8ea45fdcb935f587fca5fdba717cd47f18c', 'google', 'Раиса Абрамовна', NULL, '2022-07-16', '2026-06-30 17:26:56', '2026-07-02 12:41:46');
