(41193, 1070, NULL, 'Владислав Семененко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по хозяйственным делам, взыскал через хозяйственный суд задолженность контрагента не доплаченную за поставку оборудования по договору. Очень понравилось отношение адвоката к выполнению своей работы, рвение, внимательность и холодный расчет анализа ситуации. Вы один из лучших адвокатов в Днепре по хозяйственным делам.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-15 00:00:00', NULL, 'f72fb18ccd95c78ac289603a768422189fa57a6f', 'google', 'Владислав Семененко', NULL, '2022-07-15', '2026-06-30 17:26:56', '2026-07-02 12:41:46'),
(41194, 1070, NULL, 'София Баркова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по кредитным делам, к которому я обратилась за юридической помощью, помог быстро и недорого отменить Заочное решение суда в пользу ПриватБанка о взыскании с меня задолженности. Ввиду пропуска сроков исковой давности со стороны истца. Довольна выполненной адвокатом работой. Вы лучший кредитный адвокат в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-14 00:00:00', NULL, 'a70ed29d71626fc1fca36fc80f29f164127cbfc9', 'google', 'София Баркова', NULL, '2022-07-14', '2026-06-30 17:26:56', '2026-07-02 12:41:46'),
(41195, 1070, NULL, 'Пономаренко Ольга', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по семейному праву помог установить в судебном порядке отцовство и взыскать с бывшего сожителя алименты на содержание его ребенка. Понравилась быстрота, доступная цена и результат. Вы лучший адвокат в Днепропетровске', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-13 00:00:00', NULL, 'bf3120b691dfc1e026931d43d3c3452973a53b52', 'google', 'Пономаренко Ольга', NULL, '2022-07-13', '2026-06-30 17:26:56', '2026-07-02 12:41:46'),
(41196, 1070, NULL, 'Павел Аршавников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Днепре помог быстро и недорого сделать иск о расторжении брака, и проконтролировал его рассмотрение в суде без участия сторон (т.е. супругов). Все качественно, быстро и самое главное не дорого если сравнивать с другими адвокатами в Днепре к которым я звонила и спрашивала цены', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-12 00:00:00', NULL, '027a4429cf85e455e6a338a9fbd637fce22508d2', 'google', 'Павел Аршавников', NULL, '2022-07-12', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41197, 1070, NULL, 'Наталья Иванникова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по трудовому праву, взыскал через суд с предприятия денежные средства, положенные при увольнении в военное время. Вы лучший адвокат по трудовым делам в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-11 00:00:00', NULL, 'ad05f995a7ee640e4c7c6872b848799f395d0ffe', 'google', 'Наталья Иванникова', NULL, '2022-07-11', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41198, 1070, NULL, 'Сидоренко Владислав', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по кредитным делам помог отменить через суд кредитный договор заключённый с банком под залог моего имущества. Вы лучший кредитный адвокат в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-11 00:00:00', NULL, 'b3b29a3d7f4a9aa634797642216d1705d4af2c80', 'google', 'Сидоренко Владислав', NULL, '2022-07-11', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41199, 1070, NULL, 'Назар Тридоля', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, очень благодарен вам за предоставленную бесплатную юридическую консультацию по телефону. Очень своевременно понял суть и направления куда дальше действовать.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-10 00:00:00', NULL, '5a62f1197e63164d315c19858f8f8abc278ea547', 'google', 'Назар Тридоля', NULL, '2022-07-10', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41200, 1070, NULL, 'Анатолий Копытин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр быстро и недорого закрыл сейчас, в военное время мой ФОП, решил вопросы с налоговой по вопросу задолженности по ЕСВ и пенсионным фондом. Посже подаст годовую декларацию и отчёты. Вообщем, заказал комплексную услугу юридического сопровождения закрытия моего бизнеса. Вы лучший адвокат в Днепре для ФОПов и ООО.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-09 00:00:00', NULL, 'c54cdf3c7a5d60ef00bdcbc9d367067ffd0b0bf8', 'google', 'Анатолий Копытин', NULL, '2022-07-09', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41201, 1070, NULL, 'Макс Непомнящий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвлкат Днепр по ДТП, смог убедить судью на основании проведенного независимого экспертного исследования что виновник в ДТП не я, а иной водитель. Рекомендую данного юриста как хорошего адвоката по делам о ДТП в Днепре. Опыт работы чувствуется сразу при общении с ним.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-08 00:00:00', NULL, 'a771806469c48718c7a875a915c852e886b37673', 'google', 'Макс Непомнящий', NULL, '2022-07-08', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41202, 1070, NULL, 'Максим Викторович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по налоговым делам отменил штраф налоговой инспекции о взыскании с меня 27000 гривень за неуплату ЕСВ когда числится фопом и работал на ином предприятии, поскольку двойное налогообложение запрещено. Правда пришлось для этого обратится в суд, но это того стоило. Вы лучший налоговый адвокат в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-07 00:00:00', NULL, '1796d33628a35434d0d3a6c10fabb0c3467d5181', 'google', 'Максим Викторович', NULL, '2022-07-07', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41203, 1070, NULL, 'Артур Самойленко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по военным вопросам помог получить в военкомате справку-разрешение для выезда студента за границу на обучение в Венгрию. Поскольку мне безосновательно отказывали, требуя прохождения медосмотра, игнорируя мою бронь как студента вуза. Вы лучший адвокат в Днепре.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-06 00:00:00', NULL, 'f02d05930d3a4d6c351b47adbea8f23cdbd896a0', 'google', 'Артур Самойленко', NULL, '2022-07-06', '2026-06-30 17:26:57', '2026-07-02 12:41:46'),
(41204, 1070, NULL, 'Маргарита Дорошенко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по приватизации сделал быстро и недорого приватизацию под ключ моей комнаты в общежитии, поскольку появился покупатель. Хотя до этого, никто из адвокатов которым я звонила не хотел браться за мое дело, поскольку нужно было много запросов и они не знали алгоритм действий. Что понравилось: доступная цена на юридические услуги в Днепре, результат и быстрота в исполнении услуг.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-05 00:00:00', NULL, '79fce3637548551b177426dcceed154fbcec3724', 'google', 'Маргарита Дорошенко', NULL, '2022-07-05', '2026-06-30 17:26:58', '2026-07-02 12:41:46'),
(41205, 1070, NULL, 'Михаил Кривонос', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по гражданским делам помог установить место проживание ребенка после расторжения брака. Поскольку, жена ведет неадекватный образ жизни, злоупотребляет алкоголем и совсем не заботится о ребенке, тратя алименты непонятно на что, но уж точно не на ребенка. Через суд адвокат установил место проживания Ия ребенка с отцом. Вы лучший адвокат по семейным делам в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-04 00:00:00', NULL, '6e0f32f02a0ba9d485895d9ee912cefc454f199f', 'google', 'Михаил Кривонос', NULL, '2022-07-04', '2026-06-30 17:26:58', '2026-07-02 12:41:46'),
(41206, 1070, NULL, 'Тимур Резник', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог в правильном перерасчете военной пенсии по новому закону, поскольку пенсионный фонд Украины забывает применять нормы закона что-то повышения размера пенсий военным и ветеранам МВД. Теперь размер пенсии вместо 3700 грн, стал 6250 грн. Разницу видите? И я вижу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-03 00:00:00', NULL, 'a1947fea7cfe14d2dbda06867a0eb37c33e84559', 'google', 'Тимур Резник', NULL, '2022-07-03', '2026-06-30 17:26:58', '2026-07-02 12:41:46'),
(41207, 1070, NULL, 'Антон Миронов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по жилищным делам помог снять с прописки без выхода в военкомат моего сына. Поскольку, если снимать с регистрации по решению суда, то справка с военкомата не нужна. Все делается автоматически', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-02 00:00:00', NULL, 'dd50f86210e57821aeb17584125c9188418d724d', 'google', 'Антон Миронов', NULL, '2022-07-02', '2026-06-30 17:26:58', '2026-07-02 12:41:46'),
(41208, 1070, NULL, 'Валерия Сычева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог установить отцовство ребенку через ДНК экспертизу и суд. Очень понравилось как помог решить семейную проблему', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-01 00:00:00', NULL, '556d231c028650539f1d72085d35a97eac390a63', 'google', 'Валерия Сычева', NULL, '2022-07-01', '2026-06-30 17:26:58', '2026-07-02 12:41:46'),
(41209, 1070, NULL, 'Настя Громыко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог поменять фамилию ребенка рождённого в браке но от иного мужчины. Думаю, это лучший семейный адвокат в Днепре который за приемлемые деньги сделал иск и помог по людски', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-30 00:00:00', NULL, 'd3d32e2bff8a53b5c747c0c29d1448393e5e01d1', 'google', 'Настя Громыко', NULL, '2022-06-30', '2026-06-30 17:26:58', '2026-07-02 12:41:46'),
(41210, 1070, NULL, 'Лариса Шульгина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по пенсионным делам, помог перейти на пенсию умершего в Донецке мужа шахтера. Сама я вынужденная переселенки, и очень понравилось отношение адвоката ко мне и моей проблеме. Все сделал быстро и недорого. Результатом довольна', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-29 00:00:00', NULL, 'f0e4116a2cc9f496f9685dc6253971bb63ec4ffc', 'google', 'Лариса Шульгина', NULL, '2022-06-29', '2026-06-30 17:26:58', '2026-07-02 12:41:46'),
(41211, 1070, NULL, 'Михаил Шульга', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвлкат Днепр помог пересчитать пенсию по новому закону, из-за чего размер был увеличен на 2100 гривен. Но так как управление пенсионного фонда не захотело самостоятельно исправлять ошибку, адвокат подал иск в административный суд, и через суд обязал сделать мне правильный перерасчёт пенсии. Кто сомневается в правильности начисления или перерасчета пенсии, советую обратиться к специалисту! А не ждать...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-28 00:00:00', NULL, 'a67afb94afe61802d913ecb0d6a36cc4bc763442', 'google', 'Михаил Шульга', NULL, '2022-06-28', '2026-06-30 17:26:59', '2026-07-02 12:41:46'),
(41212, 1070, NULL, 'Станислав Головко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по жилищным делам помог выписать бывшую жену с квартиры, в которой она не проживала более 1 года, но боясь идти в военкомат (военнообязанный медик), не хотела сниматься с прописки, доставляя мне неудобства из-за чего я был вынужден тратить на коммунальные и был лишён возможности получить субсидию за жилищно коммунальные услуги.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-27 00:00:00', NULL, '4c1d6a8ff4e92d2f9ca2cae7c73ebed962af0b74', 'google', 'Станислав Головко', NULL, '2022-06-27', '2026-06-30 17:26:59', '2026-07-02 12:41:46'),
(41213, 1070, NULL, 'Олег Всеволодович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр занимался моим кредитным делом,тогда частный исполнитель арестовал все мои банковские счета, даже детские деньги в Ощадбанка Хорошо, обратился к 1 му адвокатскому бюро Днепра за помощью. Они быстро и недорого отменили исполнительную надпись нотариуса и сняли все аресты наложенные частным исполнителем. Сейчас садимся за взысканных с меня средства. Хорошо поработали, с меня лайк!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-26 00:00:00', NULL, 'ed3030895eb7a7f47cb54a3de8503fa807a05faa', 'google', 'Олег Всеволодович', NULL, '2022-06-26', '2026-06-30 17:26:59', '2026-07-02 12:41:46'),
(41214, 1070, NULL, 'Владимир Олейников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по пенсионным делам помог выиграть дело против управления пенсионного фонда Украины в АНД районе города Днепропетровска что-то перерасчета пенсии как работающему пенсионеру. Очень доволен результатом, поскольку размер пенсии увеличился ещё на 2150 гривень. Вы лучший в Днепре адвокат по пенсионным делам который смог победить пенсионный фонд!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-26 00:00:00', NULL, 'a88c7c9325d190e7223fa7645a2bc8e99cc6a307', 'google', 'Владимир Олейников', NULL, '2022-06-26', '2026-06-30 17:26:59', '2026-07-02 12:41:46'),
(41215, 1070, NULL, 'Алексей Христов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по уголовным делам, помог с условно досрочным освобождением из хозобслуги СИЗО г. Днепропетровска, поскольку администрация учреждения не захотела направлять на меня материалы в суд, игнорируя мои поощрения и личное дело Адвокат помог мне выйти по УДО, теперь я на свободе!🎆', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-25 00:00:00', NULL, '78aa38f2a2f7924e7c61822d918c2ee540692923', 'google', 'Алексей Христов', NULL, '2022-06-25', '2026-06-30 17:26:59', '2026-07-02 12:41:46'),
(41216, 1070, NULL, 'Содомия Васецкая', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог снять с прописки и выселить из квартиры бывшего мужа, из-за которого мне начислялись лишние коммунальные и я была лишена возможности получения субсидии на оплату жилищно коммунальных платежей. Осень довольна результатом работы адвоката по жилищному праву в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-24 00:00:00', NULL, '11e49941f0caf03101377926ff46ffb332b1ed5e', 'google', 'Содомия Васецкая', NULL, '2022-06-24', '2026-06-30 17:26:59', '2026-07-02 12:41:46'),
(41217, 1070, NULL, 'Федор Паркин', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по военным делам, помог обжаловать решение комиссии ВЛК о пригодности военнослужащего к воинской службе, поскольку по тому состоянию здоровья что есть у меня, я ограничено придатный к военной службе. Очень доволен результатом по делу, который добился адвокат по военным делам в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-23 00:00:00', NULL, 'f16e57a3ea1653ab32213fe271c835c96d3b0196', 'google', 'Федор Паркин', NULL, '2022-06-23', '2026-06-30 17:26:59', '2026-07-02 12:41:46'),
(41218, 1070, NULL, 'Саша Ореховский', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по военным спорам, помог отменить в суде АНД района г. Днепропетровска постановление военкома по делу об административном правонарушении за неявку в военкомат. Поскольку, суд поверил что была уважительная причина. Очень доволен положительным решением', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-22 00:00:00', NULL, 'fa60c460be7c3a94967f65fa7624ca2c32eb2c14', 'google', 'Саша Ореховский', NULL, '2022-06-22', '2026-06-30 17:27:00', '2026-07-02 12:41:46'),
