(41220, 1070, NULL, 'Назар Омельченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по трудовым спорам проконсультировал по вопросу увольнения с работы во время военного положения. Спасибо за информацию, очень помогли и подсказали вовремя!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-20 00:00:00', NULL, '840c565f93f69808fd7e98a02b57ca2e92e5a33f', 'google', 'Назар Омельченко', NULL, '2022-06-20', '2026-06-30 17:27:00', '2026-07-02 12:41:46'),
(41221, 1070, NULL, 'Наталья Бастрыкина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог установить отцовство и взыскать алименты с биологического отца, который избегал ребенка предполагая что это не его дочь. Но времена меняются и это все надоело. Нашла данного адвоката и восстановила историческую справедливость, ребенок получил отца я алименты Спасибо за результат и поддержку.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-19 00:00:00', NULL, '85cf7e0083588f9d749d452b03a7fb3d3149386d', 'google', 'Наталья Бастрыкина', NULL, '2022-06-19', '2026-06-30 17:27:00', '2026-07-02 12:41:46'),
(41222, 1070, NULL, 'Мария Маркина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог сделать расторжение брака онлайн, без моего участия в суде. Что сэкономило очень много нервов а это главнее денег и времени. Спасибо за помощь.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-18 00:00:00', NULL, '49ccd7931b0e9b1d540feb46d8a6cd4b42bd22d8', 'google', 'Мария Маркина', NULL, '2022-06-18', '2026-06-30 17:27:00', '2026-07-02 12:41:46'),
(41223, 1070, NULL, 'Михаил Овсянников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по кредитным делам, помог довольно оперативно и самое главное по доступной цене, отменить исполнительную надпись нотариуса, снял арест частного исполнителя наложенного на имущество и банковские счета. Что понравилось а что нет? Во первых, понравилось быстрота в оказании юридической помощи Во вторых, понравилась доступная цена на услуги кредитного адвоката в Днепре И в третьих, самое главное это результат. Адвокат как пообещал так и сделал. Полностью удовлетворен результатом.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-18 00:00:00', NULL, 'd29c6f46e90a970bc07eef6ef2b70ff9aefff9d1', 'google', 'Михаил Овсянников', NULL, '2022-06-18', '2026-06-30 17:27:00', '2026-07-02 12:41:46'),
(41224, 1070, NULL, 'Петр Реагунко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, спасибо за помощь в обжаловании высновка военно врачебной комиссии по мобилизации о моем состоянии здоровья. Поскольку, с имеющимися заболеваниями, я не подлежу призыву по мобилизации согласно статье 26 Закона Украины ,, О мобилизации и мобилизационной подготовки,,. Понравилась доступная цена и результат по делу.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-17 00:00:00', NULL, '76250f0ab8012c0c5d7dcc2adbd775e8c5cdb1e0', 'google', 'Петр Реагунко', NULL, '2022-06-17', '2026-06-30 17:27:00', '2026-07-02 12:41:46'),
(41225, 1070, NULL, 'Олег Владимирович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог оформить через решение суда опеку над престарелой женщиной, требующей постороннего ухода. Что понравилось: доступная цена на услуги адвоката, постоянная связь с адвокатом, гарантия результата по делу Очень довольна адвокатом по опеки, буду рекомендовать своим друзьям и знакомым.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-16 00:00:00', NULL, '12dd0e7f65b4d11687b5b83d6b5f81c54ff01c46', 'google', 'Олег Владимирович', NULL, '2022-06-16', '2026-06-30 17:27:00', '2026-07-02 12:41:46'),
(41226, 1070, NULL, 'Наталия Наумова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, благодарю вас за юридическую консультацию по вопросу расторжения брака и взыскания алиментов. Сейчас соберу документы и обращусь к вам для составления иска.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-16 00:00:00', NULL, '7a6c00c6946d35512d8f3eb84263280a3cb56813', 'google', 'Наталия Наумова', NULL, '2022-06-16', '2026-06-30 17:27:01', '2026-07-02 12:41:46'),
(41227, 1070, NULL, 'Роман Китченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, помог получить наследство через суд. Поскольку при выезде с Мариуполя были утеряны оригиналы документов на квартиру и пришлось, признавать право собственности в судебном порядке. Что понравилось: отношение и цена', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-15 00:00:00', NULL, 'da13eef390728fe01409519b3bbdd76134101e96', 'google', 'Роман Китченко', NULL, '2022-06-15', '2026-06-30 17:27:01', '2026-07-02 12:41:46'),
(41228, 1070, NULL, 'Дарина Лаптева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, хочу вас поблагодарить за помощь в установлении отцовства моему ребенку от погибшего на войне отца. Теперь, благодаря вам, ребенок получает льготы и пенсию военнослужащего погибшего в боевых действиях Вы лучший семейный адвокат в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-15 00:00:00', NULL, '0523e536b3b2c4824267ef367766682436bb83d0', 'google', 'Дарина Лаптева', NULL, '2022-06-15', '2026-06-30 17:27:01', '2026-07-02 12:41:46'),
(41229, 1070, NULL, 'Виктор Иванский', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Днепре помог вернуть водительские права и закрыть дело по статье 130 КУпАП, поскольку полицейские нарушили процедуру остановки, прохождения медосвидетельствованмя и неправильно заполнили протокол. Очень доволен результатом по делу и возвращение водительских прав', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-14 00:00:00', NULL, 'b4988e9995c445c9745182ec9e6d87aa05910270', 'google', 'Виктор Иванский', NULL, '2022-06-14', '2026-06-30 17:27:01', '2026-07-02 12:41:46'),
(41230, 1070, NULL, 'Алексей Падченко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по жилищным делам, помог выселить с квартиры жильца который был прописан но не проживал более 2 лет, хотя я был вынужден платить за коммунальные и лишён был субсидии. Осень доволен работой жилищного адвоката в Днепре и доступной ценой на его услуги по выселению с жилья', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-14 00:00:00', NULL, '80d382f83d1f299698897959b70c806421370144', 'google', 'Алексей Падченко', NULL, '2022-06-14', '2026-06-30 17:27:01', '2026-07-02 12:41:46'),
(41231, 1070, NULL, 'Владимир Панасенков', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по кредитным делам помог быстро и недорого снять аресты частного исполнителя с моей банковской карточки, отменить через суд исполнительную надпись нотариуса и сейчас подали ещё иск о признании недействительным кредитного договора. Думаю получится и тут. Данного адвоката видео в действии, молчать он не будет, сразу пишет жалобы. Думаю это лучший кредитный адвокат в Днепропетровске', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-13 00:00:00', NULL, '07fe1399df5e4b53cb9a892884c15d6068afcae5', 'google', 'Владимир Панасенков', NULL, '2022-06-13', '2026-06-30 17:27:01', '2026-07-02 12:41:46'),
(41232, 1070, NULL, 'Богдан Рябоконь', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Приняли полицейские с травой в автомобиле. Еслиб небылоб номера телефона адвоката раскаталиб меня на ст. 307 УК Украины-распостранение, а так сделали для личного употребления-ст. 309.ч 1 УК Украины. Через месяц, после лечения в наркологии, адвокат закрыл дело по ст. 309 ч. 4 УК Украины. Это лучший адвокат по наркотикам в Днепре Советую иметь его номер телефона рядом с иконкой и паспортом.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-13 00:00:00', NULL, 'c22d78d2f7358c7200516d742360f3a5f7f456e4', 'google', 'Богдан Рябоконь', NULL, '2022-06-13', '2026-06-30 17:27:01', '2026-07-02 12:41:46'),
(41233, 1070, NULL, 'Роман Киреев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по уголовным делам помог снять судимость досрочно, поскольку это было необходимо мне для получения высшей должности и очередного звания. Ошибки молодости дают о себе знать, даже сейчас когда добровольцем пошел защищать Украину. Адвокат подал ходатайство в суд, предоставил представление командования воинской части где я прохожу службу и убедил суд АНД района г. Днепропетровска досрочно снять мне судимость. Очень доволен работой а главное результатом за доступную цену!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-12 00:00:00', NULL, 'a4dea1e06716afa2ca13c79569faef63560972d0', 'google', 'Роман Киреев', NULL, '2022-06-12', '2026-06-30 17:27:02', '2026-07-02 12:41:46'),
(41234, 1070, NULL, 'Василь Котигорошко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Дніпро допоміг зменшити розмір аліментів за позовом другої дружини, оскільки від першого шлюбу я теж маю двох дітей які потребують уваги. Суд прийняв до уваги заперечення адвоката та зменшив розмір аліментів до встановленого законодавством Ви найкращий сімейний адвокат у Дніпрі.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-12 00:00:00', NULL, '8054733cf08512cb38282b7ffd4be1c4050cae18', 'google', 'Василь Котигорошко', NULL, '2022-06-12', '2026-06-30 17:27:02', '2026-07-02 12:41:46'),
(41235, 1070, NULL, 'Ольга Копейкина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по семейным делам помог быстро и недорого взыскать алименты с бывшего мужа, поскольку я хоть и работаю на двух работах, и мою полы ещё в офисном здании в качестве подработки, но денег для содержания и воспитания детей, тем более сейчас, в военное время не хватает катастрофически. А отец детей решил расслабиться и забухать. Адвокат вправил ему мозги и через суд обязал выплачивать алименты. Что понравилось: доступная цена на услуги семейного адвоката в Днепре и гарантия результата. Адвокат что пообещал то собственно и сделал.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-11 00:00:00', NULL, 'cf8ef835c8b1a449e4c7eec3a4a0d77f192298fd', 'google', 'Ольга Копейкина', NULL, '2022-06-11', '2026-06-30 17:27:02', '2026-07-02 12:41:46'),
