(41334, 1505, NULL, 'Кирилл Завадский', NULL, 0, NULL, NULL, 0.00, 2, NULL, 'Подзвонив зранку з приводу рапортів для НГУ, запитав хто саме займається, сказали передзвонять и все...', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-17 00:00:00', NULL, 'eae22be606ea787a98968869bc15bd0b5bf0d8c7', 'google', 'Кирилл Завадский', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSmg2ODF0Tk9TbGgwNzEzMmZ5dU1xbmVDZ2F3NjNpV05Xd2FLUy0xdXJjbllmYkx3PXczMDAtaDMwMC1wLXJwLW1vLWJyMTAw.jpeg?expires=2098459639&signature=6a6f60161009ce517597791532773a7d1d1f87a15282742b0b4760ab836daff5', '2025-10-17', '2026-06-30 17:27:37', '2026-06-30 17:28:40'),
(41335, 1505, NULL, 'Андрей Момот', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити щиру подяку адвокату Олесі Левшаковій за професійну юридичну допомогу у вирішенні мого питання. Все компетентно, чітко, грамотно і зрозуміло! Дякую.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2025-10-17 00:00:00', NULL, '75ef5ea1cca5a2e19554d50ecebb7046188b6835', 'google', 'Андрей Момот', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EtL0FMVi1ValdTbVpQOXN2X1A0Vll2aW9pMXRzRUhKd0JiRHU5S0kzS0IycEx5YWZFSk1nU2R5Slk9dzMwMC1oMzAwLXAtcnAtbW8tYnIxMDA=.jpeg?expires=2098459639&signature=bb03ac0ed5074b4b864e6d03b378388a3b4083274c6845801545339c5ff2cdcc', '2025-10-17', '2026-06-30 17:27:37', '2026-06-30 17:28:40'),
