(41530, 1165, NULL, 'Владимир Панасов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепропетровск по семейным делам помог восстановить лишённое отцовство по решению суда. Осень доволен результатом, ценой и работой адвоката в целом. Вы лучший адвокат по семейным делам в Днепропетровске', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-08 00:00:00', NULL, '51a7243c7221106f1bbf4ec7059a4c5f8cfe70c4', 'google', 'Владимир Панасов', NULL, '2022-07-08', '2026-06-30 17:28:21', '2026-06-30 17:28:56'),
(41531, 1165, NULL, 'Владимир Алексеевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог быстро и главное не дорого оформить расторжение брака в судебном порядке. Через полтора месяца уже на руках было решение суда о разводе. Доволен на все 💯 процентов', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-03 00:00:00', NULL, '13d0b7b4711b36fd2c377f7c9235882d95b0ddd9', 'google', 'Владимир Алексеевич', NULL, '2022-07-03', '2026-06-30 17:28:22', '2026-06-30 17:28:56'),
(41532, 1165, NULL, 'Виктор Лапинский', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвлкат Днепр помог забрать с отдела полиции изъятый мопед. Поскольку, сделал запрос и истребовал копии документов о его покупки, оригиналы утеряли. Но и за это спасибо большое!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-01 00:00:00', NULL, 'd0e3bf792ba9347a5aa9dc790430fd7868ec8d71', 'google', 'Виктор Лапинский', NULL, '2022-07-01', '2026-06-30 17:28:22', '2026-06-30 17:28:56'),
(41533, 1165, NULL, 'Анатолий Кушнарев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, провел онлайн консультацию по Вайберу прям на блокпосту где меня остановили сотрудники полиции и стали обыскивать без причины автомобиль и мои личные вещи. Очень благодарен адвокату за разъяснения мне и сотрудникам полиции норм закона, а именно то что они имеют право проводить только поверхностный осмотр, а не обыск.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-30 00:00:00', NULL, '2afed1a454d2124c2155186b80f21a35beab931b', 'google', 'Анатолий Кушнарев', NULL, '2022-06-30', '2026-06-30 17:28:22', '2026-06-30 17:28:56'),
(41534, 1165, NULL, 'Людмила Огарева', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог быстро недорого составить иск о взыскании алиментов на несовершеннолетних детей, поскольку отец полность стал игнорировать своих детей оставив на произвол. Что понравилось: доступная цена на услуги адвоката в Днепре, сроки и результат.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-30 00:00:00', NULL, '12b5ac9d8eb3b4ebeec14ab538d76e22087f977d', 'google', 'Людмила Огарева', NULL, '2022-06-30', '2026-06-30 17:28:22', '2026-06-30 17:28:56'),
(41535, 1165, NULL, 'Игорюня Мельников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, помог по земельному спору с соседом. Вызвал полицию, техников землеустроительной и обязал установить новые межевые знаки земельного участка согласно проведенным землеустроителя и замеров, а не так как хотел сосед. Вы лучший адвокат по земельным делам в Днепре.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-29 00:00:00', NULL, '099eb59ed5fb3af2b7847834005516d04a4f7c4b', 'google', 'Игорюня Мельников', NULL, '2022-06-29', '2026-06-30 17:28:22', '2026-06-30 17:28:56'),
(41536, 1165, NULL, 'Василий Вареня', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, предоставил бесплатную консультацию по телефону по вопросу отсрочки от мобилизации в военное время. Очень помог понять основания от призыва.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-28 00:00:00', NULL, '3522438ca21adab321b77f9bb89a9f0570eee47c', 'google', 'Василий Вареня', NULL, '2022-06-28', '2026-06-30 17:28:22', '2026-06-30 17:28:56'),
(41537, 1165, NULL, 'Рустам Фаринников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвлкат Днепр по административным делам помог закрыть дело об административном правонарушении по статье 130 КУпАП, поскольку я был на метадоновой программе а не при употреблении самостоятельно наркотических веществ Справка от нарколога смогла убедить судью в моей невиновности, как итог, машина возвращена права вернули', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-28 00:00:00', NULL, 'aef35ba0e26238709e8fe707842ae31ad16b15d4', 'google', 'Рустам Фаринников', NULL, '2022-06-28', '2026-06-30 17:28:22', '2026-06-30 17:28:56'),
