(41622, 1165, NULL, 'Манина Елена', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Что понравилось по работе с данным адвокатом: доступная цена, результат и полное сопровождение с юридической точки зрения.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-05 00:00:00', NULL, '177b3a37e2525afeb500b4b8e8d4f43c58dcfcc8', 'google', 'Манина Елена', NULL, '2024-02-05', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41623, 1165, NULL, 'Игорь Лапошников', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по жилищным делам помог в судебной тяжбе с ОСББ, поскольку с меня требовали деньги не предоставив нужные услуги в полном объеме. Я уже устал эт этого беспредела и подал в суд иск, поскольку цены на коммунальные завышены. Адвокат по жилищным делам Днепр выиграл суд и поставил на место председателя ОСББ', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-11 00:00:00', NULL, '49910441509b8506faf45cc0384ceac5d1b8b21d', 'google', 'Игорь Лапошников', NULL, '2022-07-11', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41624, 1165, NULL, 'Ахмад Халифов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по иммиграционным вопросам помог получить в миграционной службе вид на жительство, даже в военное положение, что мне как студенту медицинского университета очень важно для продления учебы. Осень благодарен адвокату за помощь', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-22 00:00:00', NULL, 'c4852105203c86905f2606910c39c691368fa85a', 'google', 'Ахмад Халифов', NULL, '2022-06-22', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41625, 1165, NULL, 'Василь Безкоровайний', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Дніпро, дякую за безкоштовну юридичну консультацію з приводу мобілізації та виїзду за кордон батька малолітніх дітей. Дуже допомогли розібратися у військовому законодавстві', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-18 00:00:00', NULL, 'b76f83ebc99a6ecace0f14fff02a9e09953753a2', 'google', 'Василь Безкоровайний', NULL, '2022-06-18', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41626, 1165, NULL, 'Даша Комарницкая', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат быстро и недорого составил исковое заявление в суд о принудительном возвращении депозита с банка. И обязал судебным решением выплатить мне неустойку и саму сумму депозита, не смотря на военное положение. Очень благодарна. Вы лучший адвокат в Днепре по кредитным делам и спорам с банками.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-11 00:00:00', NULL, '469d5da5ba818627cc9a34d5e9a8f88f4f534abe', 'google', 'Даша Комарницкая', NULL, '2022-06-11', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41627, 1165, NULL, 'Павел Львович', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Благодарю за помощь и юридический совет по моему кредитному делу. Очень помогли разобраться с вопросом', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-05-30 00:00:00', NULL, '5ed9ae170aa1c10494393eae370f398a28fed226', 'google', 'Павел Львович', NULL, '2022-05-30', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41628, 1165, NULL, 'Олег Васильев', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Благодарю адвокатов адвокатской компании за помощь в решении моего вопроса об условно-досросном освобождении. Я дома. Очень благодарен.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-05-23 00:00:00', NULL, '7ddb944916774864832df1b26bcc420eb5e99082', 'google', 'Олег Васильев', NULL, '2022-05-23', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41629, 1165, NULL, 'Алла Сафронова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу поблагодарить адвоката в Днепре Андрея Владимировича за помощь в расторжении моего брака через суд. Все сделано четко, быстро и по разумной цене Спасибо, что помогли.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-05-18 00:00:00', NULL, '02cbde347b3002ff485ca8885057d4282044867a', 'google', 'Алла Сафронова', NULL, '2022-05-18', '2026-06-30 17:28:55', '2026-06-30 17:28:56'),
(41630, 1446, NULL, 'Сергей Архаров', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Очень доволен работой адвоката в Днепре в деле о наследстве с пропуском срока. Все восстановил, умничка, и помог вступить в наследство.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-05 00:00:00', NULL, 'b5d561fbb0eaa0e9f87eb1b8d0261c63d46f80c8', 'google', 'Сергей Архаров', NULL, '2024-02-05', '2026-06-30 17:28:58', '2026-07-02 12:42:43'),
(41631, 1446, NULL, 'Лариса Ильинична', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр понравился доступными ценами на юридические услуги, в частности заказывала иск о расторжении брака. Все сделал максимально быстро и по доступной цене. Рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-26 00:00:00', NULL, 'be19c58241ce1a04b47e0838463ccac63f40eb89', 'google', 'Лариса Ильинична', NULL, '2022-07-26', '2026-06-30 17:28:58', '2026-07-02 12:42:43'),
(41632, 1446, NULL, 'Бондарек Илья', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по пенсионным делам проверил правильность начисления и последующий перерасчёт пенсии мне как работающему пенсионеру. После через суд взыскал с пенсионного фонда не назначенную и не выплаченную сумму пенсии. Очень хорошо разбирается в пенсионном законодательстве данный адвокат', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-04 00:00:00', NULL, '5bade66cc0f496c03009c1b6126e7204f4691e8f', 'google', 'Бондарек Илья', NULL, '2022-07-04', '2026-06-30 17:28:59', '2026-07-02 12:42:43'),
(41633, 1446, NULL, 'Кирилл Мефодиевич', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр Абакумов проконсультировал по вопросу досрочного выхода не пенсию и покупки страхового стажа за недостающие полгода. Детально объяснив всю процедуру до мелочей. Очень доволен данной консультацией и человеком. Хороший пенсионный адвокат в Днепре!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-30 00:00:00', NULL, 'dc77fbde4b78e45a0435704af86df793711f8442', 'google', 'Кирилл Мефодиевич', NULL, '2022-06-30', '2026-06-30 17:28:59', '2026-07-02 12:42:43'),
(41634, 1446, NULL, 'Олег Боженко', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр помог взыскать с предприятия на котором я работал начисленную но не выплаченную заработную плату, отпускные и доплату за вредные условия труда на предприятии. Очень доволен результатом работы данного юриста в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-25 00:00:00', NULL, 'd0e81c5d91997b11bcd2f248788db8bb67a5632d', 'google', 'Олег Боженко', NULL, '2022-06-25', '2026-06-30 17:28:59', '2026-07-02 12:42:43'),
(41635, 1446, NULL, 'Иван Рагугов', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр, помог выиграть в хозяйственном суде спор с контрагентов по взысканию задолженности за поставку семян подсолнечника урожая 2021 года. Очень впечатлён. Вы лучший адвокат по хозяйственным делам в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-19 00:00:00', NULL, 'af7135fa93dc4517fba9ee8d40b641552b99e9b2', 'google', 'Иван Рагугов', NULL, '2022-06-19', '2026-06-30 17:28:59', '2026-07-02 12:42:43'),
(41636, 1446, NULL, 'Светлана Борисовна', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат в Днепре Адюбакумов, помог быстро и безболезненно для моей психики сделать через суд расторжение брака с моим, теперь уже бывшим мужем. Так не хотелось видеть его лично. Поэтому адвокат все сделал самостоятельно без моего личного участия. Вы лучший адвокат по расторжению брака в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-11 00:00:00', NULL, '9d95f461226c6a7add793ed9829183a974cb5aa1', 'google', 'Светлана Борисовна', NULL, '2022-06-11', '2026-06-30 17:28:59', '2026-07-02 12:42:43'),
(41637, 1442, NULL, 'лора', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Спасибі за консультацію, допомогли!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-02-02 00:00:00', NULL, '5ae423383f3969ad3b0f3ebba3b9c34f81b48b7f', 'google', 'лора', NULL, '2024-02-02', '2026-06-30 17:29:02', '2026-07-02 12:41:36'),
(41638, 1442, NULL, 'Алена Коршунова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по семейным делам, помог после расторжения брака с мужем установить и закрепить через суд то с кем будет проживать ребенок. Что дало мне основания взыскать алименты на содержание ребенка. Осень понравилось отношение адвоката к разрешению моей проблемы.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-12 00:00:00', NULL, 'f48e1e79eef7b1efe6f3293ee447a5c253c3fc2d', 'google', 'Алена Коршунова', NULL, '2022-07-12', '2026-06-30 17:29:02', '2026-07-02 12:41:36'),
(41639, 1442, NULL, 'Ваданский Виталий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по семейным делам, помог в суде взыскать алименты как на малолетнего ребенка так и на мать. Поскольку, отец (бывший муж моей сестры) полностью стал игнорировать потребности семьи и ребенка Вы лучший семейный адвокат в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-07-04 00:00:00', NULL, 'a576b6b8a294c8589e0bb199c64761ec9190a13a', 'google', 'Ваданский Виталий', NULL, '2022-07-04', '2026-06-30 17:29:02', '2026-07-02 12:41:36'),
(41640, 1442, NULL, 'Нинель Шалимова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Адвокат Днепр по семейным делам помог установить отцовство через судебную экспертизу ДНК и впоследствии на основании этого взыскать с биологического отца алименты. Что понравилось!? Во первых, результат по делу, а во вторых, доступная цена на услуги семейного адвоката в Днепре', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2022-06-24 00:00:00', NULL, 'ac93a98ea7bb1b24b72cf40ac31c68e6041d1656', 'google', 'Нинель Шалимова', NULL, '2022-06-24', '2026-06-30 17:29:02', '2026-07-02 12:41:36'),
