(41698, 552, NULL, 'Клієнт ****4276', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу виразити свою подяку Олександру Володимировича за допомогу у вирішенні питання з відстрочкою', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-06-30 00:00:00', NULL, 'ac7c80000407df6f8c212e7e74d648690172c354', 'google', 'Клієнт ****4276', NULL, '2026-06-30', '2026-07-01 08:09:39', '2026-07-02 12:18:54'),
