(41790, 552, NULL, 'Оксана', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую юристу Тимофію за проведену консультацію. Юрист розуміється в своїй справі та надає корисну інформацію', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-29 00:00:00', NULL, '87276c69ce37aab3828492254341086de34d9287', 'google', 'Оксана', NULL, '2026-05-29', '2026-07-01 08:09:53', '2026-07-02 12:18:54'),
