(41809, 552, NULL, 'назар', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Щиро дякую Зоряні Володимирівні та Центру правової допомоги за кваліфіковану допомогу! Отримала професійну консультацію, чіткі відповіді та зрозумілий план дій. Уважний та відповідальний юрист. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-28 00:00:00', NULL, '871800c9738df3aacd7bef2b38fbe9b5a9b1e2c7', 'google', 'назар', NULL, '2026-05-28', '2026-07-01 08:09:55', '2026-07-02 12:18:54'),
(41810, 552, NULL, 'Клієнт ****7591', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Була на консультації з питанням про закриття декількох МФО, Світлана Григорівна пояснила простими словами куди і як краще далі рухатися. Дуже задоволена, рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-28 00:00:00', NULL, '80772a1e1aa837788cc6c7f5cb2b76b8c9c5ac3e', 'google', 'Клієнт ****7591', NULL, '2026-05-28', '2026-07-01 08:09:55', '2026-07-02 12:18:54'),
(41811, 552, NULL, 'Клієнт ****4693', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Велика подяка Центру правової допомоги та Зоряні Володимирівні за високий професіоналізм, уважність та людяність. Консультація була безкоштовною, але настільки змістовною та професійною, що я отримала відповіді на всі свої питання та розуміння подальших дій. Видно досвід, відповідальність і щире бажання допомогти клієнту. Однозначно рекомендую звертатись!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-27 00:00:00', NULL, 'c7f62d27a2768c505eefe0ea2b57706500b03be7', 'google', 'Клієнт ****4693', NULL, '2026-05-27', '2026-07-01 08:09:56', '2026-07-02 12:18:54'),
(41812, 552, NULL, 'Анастасія Шмикова', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую Центру правової допомоги та Зоряні Володимирівні за фахову консультацію. Все було доступно, зрозуміло та професійно. Уважний підхід, чіткі відповіді та реальна допомога у вирішенні питання. Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-27 00:00:00', NULL, 'fbd5290b611d0c63806ef1fb294ad2e27428731c', 'google', 'Анастасія Шмикова', NULL, '2026-05-27', '2026-07-01 08:09:56', '2026-07-02 12:18:54'),
(41813, 552, NULL, 'Владислав Левицкий', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Консультація пройшла добре. Дізнався відповіді на своі питання, дякувати професіоналу своеі справи Роману Миколаевичу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-27 00:00:00', NULL, 'd06fd2e3b9307490c351c12da7b1bdf42a2e49a4', 'google', 'Владислав Левицкий', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jTGhIenFtelgxMmltMW9RWHpDcjJWb1padmRDUUVleGd1MHFVNEQyREFMb1BSc2VBPXMxMjAtYy1ycC1tby1icjEwMA==.jpeg?expires=2098512517&signature=07fbf46164434d56ca5b7dc5780ee88955ea8e4a51a5207ada946b5c37af0234', '2026-05-27', '2026-07-01 08:09:56', '2026-07-02 12:18:54'),
(41814, 552, NULL, 'inna inna', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу щиро подякувати Центру правової допомоги та Зоряні Володимирівні за допомогу та професіоналізм. З першої консультації стало зрозуміло, що людина дійсно знає свою справу. Моє питання було детально проаналізоване, враховані всі нюанси та запропоновані шляхи вирішення. Дуже приємне, уважне ставлення та підтримка протягом усього часу. Рекомендую Зоряну Володимирівну як грамотного, досвідченого та відповідального юриста.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-27 00:00:00', NULL, '0bb6a899c4b361f2a4a668cef7c7208472e68b8b', 'google', 'inna inna', NULL, '2026-05-27', '2026-07-01 08:09:56', '2026-07-02 12:18:54'),
(41815, 552, NULL, 'Володимир', NULL, 0, NULL, NULL, 0.00, 1, NULL, 'Звернувся до цього центру для оскарження штрафу, мене запевнили що все буде добре, що такі штрафи оскаржуються на протязі тижня від подання позову, наполягали підписати договір, за свої послуги взяли кругленьку суму, після підписання договору годували обіцянками, на звʼязок не виходили ігнорили, їм головне щоб ви заплатили гроші а дальше їм на вас нас…. Відгуки в них накручені, якщо читати реальні відгуки то там нема більше однієї зірочки, нікому не рекомендую звʼязуватись з цією шарашкіною канторою якщо хочете зберегти нерви і гроші', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-05-26 00:00:00', NULL, '00ab4914208ff4428a908d4bd3ace372e20b9b2c', 'google', 'Володимир', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSzY2ck53eWJIN3FXUzczSkY3bnExNEM4UzJVcW1Rc0FLRlU4WXlVclNUQ3dGSGJnPXMxMjAtYy1ycC1tby1icjEwMA==.jpeg?expires=2098512517&signature=8d0eff0f5adc1c0d26617e8d3713a3d6b8db1ae4978c2053d775c666a2341a72', '2026-05-26', '2026-07-01 08:09:56', '2026-07-02 12:18:54'),
