(41918, 552, NULL, 'Клієнт ****2232', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Був на консультації у Миколи Ярославовича! Дуже задоволений результатом, чудовий спеціаліст та знавець своєї справи . Рекомендую!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-30 00:00:00', NULL, 'bc152fd91689dccd7c60615780c73422c460bf96', 'google', 'Клієнт ****2232', NULL, '2026-04-30', '2026-07-01 08:10:14', '2026-07-02 12:18:54'),
(41919, 552, NULL, 'Клієнт ****4234', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Відвідав центр правової допомоги конституцію мені провів Максим Тарасович дуже дякую. Все дуже сподобалось.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-30 00:00:00', NULL, '18372937d75a399c3f7001182e417123d0966d55', 'google', 'Клієнт ****4234', NULL, '2026-04-30', '2026-07-01 08:10:15', '2026-07-02 12:18:54'),
(41920, 552, NULL, 'Клієнт ****6954', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Дякую Максиму Тарасовичу за допомогу у вирішенні мого питання. Всім рекомендую на Менцинського 1', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-30 00:00:00', NULL, 'c18a76794f903c4cbdc4720ab7e369e871071fe8', 'google', 'Клієнт ****6954', NULL, '2026-04-30', '2026-07-01 08:10:15', '2026-07-02 12:18:54'),
(41921, 552, NULL, 'Forstry', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Був на консультації у Максима Тарасовича чітко та якісно роз’яснили вирішення моєї проблеми. Вирішив співпрацювати. Моє питання, яке тривожило мене місяцями було вирішено за короткі терміни. Чудовий офіс на Менцинського 1', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-30 00:00:00', NULL, 'f2c5997cdcac0e7e429b4cfefd99d360d26bf8fe', 'google', 'Forstry', NULL, '2026-04-30', '2026-07-01 08:10:15', '2026-07-02 12:18:54'),
(41922, 552, NULL, 'Софія Гамберг', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Була на консультації у Ірини Богданівни в Центрі Правової Допомоги хочу сказати що юрист задовільнив мій запит в повному обсязі та розказала що як має бути. Я їй вдячна за професіоналізм та відповідальне ставлення до мого прийому буду радити знайомим щодо звернення до цієї компанії та до цього юриста за консультаціями.', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2026-04-30 00:00:00', NULL, 'fc91dcc2fc29104e3d6d16a73d3f28a1e74b2f23', 'google', 'Софія Гамберг', 'https://top20.ua/media-resize-url/90,90/aHR0cHM6Ly9saDMuZ29vZ2xldXNlcmNvbnRlbnQuY29tL2EvQUNnOG9jSnI5N2dqUnIxUmNKUTlYWWVSZHNBdFVlWHpGMnI2ak1PRlctUUpFQXpNVkFzYWlBPXMxMjAtYy1ycC1tby1icjEwMA==.jpeg?expires=2098512524&signature=76e451ca20baf672c408814519cacc73fa0e7458a7da69894b08d025c0f579de', '2026-04-30', '2026-07-01 08:10:15', '2026-07-02 12:18:54');
