(43067, 502, NULL, 'Vlas Slotyuk', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Велика подяка Олександру за вирішення мого питання.Дуже професійний підхід до справи з урахуванням усіх деталей ,швидкі відповіді на смс на дзвінки .Без води ,усе реально пояснив крок за кроком .Я дуже задоволений та хочу ПОРЕКОМЕНДУВАТИ ОЛЕКСАНДРА .', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-17 00:00:00', NULL, '8f943849283a645bd21d332b7d3c71a04b5d471e', 'google', 'Vlas Slotyuk', 'img/empty.png?a2499e3b0', '2024-09-17', '2026-07-02 12:12:35', '2026-07-02 12:17:48'),
(43068, 502, NULL, 'Mr _Boom', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Олександр Малик допоміг мені зібрати й оформити всі необхідні документи для отримання аліментів. Людське ставлення, індивідуальний підхід, якісне надання послуг! Найкращий сімейний адвокат у Вінниці!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-17 00:00:00', NULL, 'c97d376b521c55b064263777389829c58b5b3337', 'google', 'Mr _Boom', 'img/empty.png?a2499e3b0', '2024-09-17', '2026-07-02 12:12:35', '2026-07-02 12:17:48'),
(43069, 502, NULL, 'Jaroslav Lyashchenko', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хочу висловити слова подяки Олександру Малику за надану мені допомогу та вирішення моєї проблеми. Грамотний та тактичний підхід дозволили домогтися справедливості. Це один із тих адвокатів у Вінниці, який має величезний досвід роботи у своїй діяльності. Однозначно раджу!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-16 00:00:00', NULL, 'a1fa3d49076af14d0558346149cca77995339754', 'google', 'Jaroslav Lyashchenko', 'img/empty.png?a2499e3b0', '2024-09-16', '2026-07-02 12:12:35', '2026-07-02 12:17:48'),
(43070, 502, NULL, 'Дятлик Олександр', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Кваліфікований адвокат, професійно та ефективно вирішує юридичні питання у різних правових справах. Щиро дякую за допомогу та рекомендую!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-14 00:00:00', NULL, '75c5b3db1d0c0e57bf34f3d6cbfe21f471152eb3', 'google', 'Дятлик Олександр', 'img/empty.png?a2499e3b0', '2024-09-14', '2026-07-02 12:12:35', '2026-07-02 12:17:48'),
(43071, 502, NULL, 'София Ванина', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Якщо ви шукаєте у Вінниці досвідченого адвоката, раджу звернути увагу саме на Олександра Малика. Чіткий, впевнений у своїх діях. Допоміг довести мою невинність. При необхідності тепер знаю до кого звертатись і сміло раджу іншим!!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2024-09-13 00:00:00', NULL, 'd45f9f12c6fc92ab63fdeaa99223044f8d663d65', 'google', 'София Ванина', 'img/empty.png?a2499e3b0', '2024-09-13', '2026-07-02 12:12:35', '2026-07-02 12:17:48'),
