(43180, 502, NULL, 'Віктор', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Хороший адвокат. Допоміг мені вирішити скдну справу. Рекомендую', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-05-17 00:00:00', NULL, '58bce0a8270e33d27eef5ee5f7f232522690e6ed', 'google', 'Віктор', 'img/empty.png?a2499e3b0', '2023-05-17', '2026-07-02 12:12:52', '2026-07-02 12:17:48'),
(43181, 502, NULL, 'Ирина Ира', NULL, 0, NULL, NULL, 0.00, 5, NULL, 'Олександр Володимирович, дякуємо Вам за те, що допомогли нашій сім\'ї відстояти права на автомобіль у суді, бо митний орган нас дуже налякав і його представник говорив, що машина буде конфіскована. А Ви помогли нам виграти справу і машина у нас і штрафу немає! Дякуємо!', NULL, NULL, NULL, NULL, 'published', 'Імпортовано як зовнішній відгук Google.', NULL, NULL, 0, 'external_google_import', 0, 0, 0, 0, 0, '2023-05-17 00:00:00', NULL, 'e103a9dfc7ef477f07687614cfa0f81d7c6078e4', 'google', 'Ирина Ира', 'img/empty.png?a2499e3b0', '2023-05-17', '2026-07-02 12:12:52', '2026-07-02 12:17:48'),
